(function(){
  var sepOf = function(l){ var m = /10(.?)000 PIVX/.exec(I18N.pivxMnCollateral[l] || ''); return m ? m[1] : ','; };
  var group = function(v, sep){ return String(v).replace(/\B(?=(\d{3})+(?!\d))/g, sep); };
  var each = function(src, fn){ var o = {}; Object.keys(src).forEach(function(l){ o[l] = fn(src[l], l); }); return o; };
  Object.keys(VIVO_I18N).forEach(function(k){
    I18N[k] = each(VIVO_I18N[k], function(s, l){
      var sep = sepOf(l);
      return s.replace('{halv}', group(262800, sep)).replace('{c1}', group(5000, sep)).replace('{c2}', group(20000, sep)).replace('{enf}', group(2177696, sep)).replace('{dev}', group(1000000, sep)).replace('{blk}', group(2176696, sep));
    });
  });
  // same sentences as PIVX's, with VIVO's figures: 1 VIVO per block; 5,000 VIVO collateral
  I18N.vivoRewardB = each(I18N.pivxRewardB, function(s){ return s.replace('10 PIV', '1 VIVO'); });
  I18N.vivoMnCollateral = each(I18N.pivxMnCollateral, function(s){ return s.replace(/10(.?)000 PIVX/, '5$1000 VIVO'); });
})();

