function setHTML(sel, html){ var el = document.querySelector(sel); if(el) el.innerHTML = html; }
function setText(sel, text){ var el = document.querySelector(sel); if(el) el.textContent = text; }

function renderChart(coin, lang){
  var svg = document.querySelector('.chartSvg');
  if(!svg || !coin.chartLines) return;
  var W = 700, H = 200, padTop = 16, padBottom = 24, padRight = 90, plotW = W - padRight;
  var allValues = [];
  coin.chartLines.forEach(function(l){ l.points.forEach(function(v){ if(isFinite(v) && v > 0) allValues.push(v); }); });
  if(!allValues.length) allValues = [1];
  var logs = allValues.map(Math.log10);
  var logMin = Math.min.apply(null, logs);
  var logMax = Math.max.apply(null, logs);
  var range = (logMax - logMin) || 1;
  function yOf(v){
    if(!isFinite(v) || v <= 0) v = Math.pow(10, logMin);
    var t = (Math.log10(v) - logMin) / range;
    return H - padBottom - t * (H - padTop - padBottom);
  }
  var liveSuffix = pick(I18N.liveSuffix, lang);
  var parts = [];
  if(!coin.chartLines.some(function(l){ return l.points.length; }) && coin.emptyText){
    parts.push('<text class=chartLabel x=' + (plotW / 2) + ' y=' + (H / 2) + ' text-anchor=middle style=fill:var(--mut);font-size:14px>' + pick(coin.emptyText, lang) + '</text>');
  }
  coin.chartLines.forEach(function(l){
    var n = l.points.length;
    if(!n) return;
    var pts = l.points.map(function(v, i){
      var x = n > 1 ? (i / (n - 1)) * plotW : 0;
      return x.toFixed(1) + ',' + yOf(v).toFixed(1);
    }).join(' ');
    var lastX = plotW, lastY = yOf(l.points[n - 1]);
    var label = l.name + (l.live && l.liveOk ? liveSuffix : '');
    parts.push('<polyline class=chartLine style=stroke:' + l.color + ' points="' + pts + '"></polyline>');
    parts.push('<circle class=chartDot cx=' + lastX.toFixed(1) + ' cy=' + lastY.toFixed(1) + ' r=3.5 style=fill:' + l.color + '></circle>');
    parts.push('<text class=chartLabel x=' + (lastX + 8).toFixed(1) + ' y=' + (lastY + 4).toFixed(1) + ' style=fill:' + l.color + '>' + label + '</text>');
  });
  svg.innerHTML = parts.join('');
  setText('#dashboardView .chart + .mini', pick(I18N.chartCaption, lang));
}

var PROXY_BASE = '';

function fmtPrice(v){
  if(!isFinite(v)) return '0';
  if(v >= 100) return v.toFixed(2);
  if(v >= 1) return v.toFixed(4);
  return v.toFixed(8).replace(/0+$/,'').replace(/\.$/,'');
}

var lwChart = null, lwCandleSeries = null, lwVolumeSeries = null;

function ensureLwChart(){
  if(lwChart) return lwChart;
  var container = document.getElementById('lwCandleChart');
  if(!container || typeof LightweightCharts === 'undefined') return null;
  lwChart = LightweightCharts.createChart(container, {
    autoSize: true,
    layout: { background: { color: 'transparent' }, textColor: chartTheme().text, fontFamily: 'Inter, Segoe UI, system-ui, sans-serif' },
    grid: { vertLines: { color: chartTheme().grid }, horzLines: { color: chartTheme().grid } },
    timeScale: { timeVisible: true, secondsVisible: false, borderColor: chartTheme().line },
    rightPriceScale: { borderColor: chartTheme().line },
    crosshair: { mode: LightweightCharts.CrosshairMode.Normal },
  });
  lwCandleSeries = lwChart.addSeries(LightweightCharts.CandlestickSeries, {
    upColor: '#20df84', downColor: '#ff5b5b', borderVisible: false,
    wickUpColor: '#20df84', wickDownColor: '#ff5b5b',
    priceFormat: { type: 'price', precision: 8, minMove: 0.00000001 },
  });
  lwVolumeSeries = lwChart.addSeries(LightweightCharts.HistogramSeries, {
    priceFormat: { type: 'volume' }, priceScaleId: 'vol',
  });
  lwChart.priceScale('vol').applyOptions({ scaleMargins: { top: 0.82, bottom: 0 } });
  lwChart.priceScale('right').applyOptions({ scaleMargins: { top: 0.08, bottom: 0.22 } });
  return lwChart;
}

var activeCandleExchangeName = null;

function getCandleLine(coin){
  if(!coin.chartLines) return null;
  if(activeCandleExchangeName){
    var chosen = null;
    coin.chartLines.forEach(function(l){ if(l.name === activeCandleExchangeName) chosen = l; });
    if(chosen) return chosen;
  }
  if(coin.exchanges && coin.exchanges.length){
    var bestName = null, bestVol = -1;
    coin.exchanges.forEach(function(e){
      var num = parseFloat(String(e.volume).replace(/[^0-9.]/g, '')) || 0;
      if(num > bestVol){ bestVol = num; bestName = e.name; }
    });
    var byVolume = null;
    if(bestName) coin.chartLines.forEach(function(l){ if(l.name === bestName) byVolume = l; });
    if(byVolume){ activeCandleExchangeName = bestName; return byVolume; }
  }
  var fallback = null;
  coin.chartLines.forEach(function(l){ if(l.candlePrimary) fallback = l; });
  if(fallback) activeCandleExchangeName = fallback.name;
  return fallback;
}

function renderCandles(coin, lang){
  var line = getCandleLine(coin);
  setText('.candleCaption', pick(I18N.candleCaption, lang));
  setText('.candleChartTitle', pick(I18N.candleChartTitle, lang));
  var tickerRowEl = document.getElementById('tickerRow');
  if(tickerRowEl) Array.prototype.forEach.call(tickerRowEl.querySelectorAll('.tickerCard'), function(c){
    c.classList.toggle('tActive', !!line && c.getAttribute('data-ticker-exchange') === line.name);
  });
  if(!line){
    // no market with candles (e.g. a coin traded only against other coins): empty chart, not the previous coin's
    var nameEl0 = document.querySelector('.candleExchangeName');
    if(nameEl0) nameEl0.textContent = '—';
    if(lwCandleSeries) lwCandleSeries.setData([]);
    if(lwVolumeSeries) lwVolumeSeries.setData([]);
    return;
  }
  var nameEl = document.querySelector('.candleExchangeName');
  var liveSuffix = pick(I18N.liveSuffix, lang);
  if(nameEl) nameEl.textContent = line.name + (line.live && line.liveOk ? liveSuffix : '');
  var chart = ensureLwChart();
  if(!chart) return;
  var emptyEl = document.getElementById('lwCandleEmpty');
  var n = line.candles ? line.candles.length : 0;
  if(n < 2){
    lwCandleSeries.setData([]);
    lwVolumeSeries.setData([]);
    if(emptyEl){ emptyEl.textContent = pick(coin.emptyText || I18N.notEnoughCandles, lang); emptyEl.style.display = 'flex'; }
    return;
  }
  if(emptyEl) emptyEl.style.display = 'none';
  var candles = line.candles.slice().sort(function(a, b){ return a.t - b.t; });
  lwCandleSeries.setData(candles.map(function(c){
    return { time: c.t, open: c.o, high: c.h, low: c.l, close: c.c };
  }));
  lwVolumeSeries.setData(candles.map(function(c){
    return { time: c.t, value: c.v || 0, color: c.c >= c.o ? 'rgba(32,223,132,.45)' : 'rgba(255,91,91,.45)' };
  }));
  try{ chart.timeScale().fitContent(); }catch(e){}
}

function fetchCandleData(coin, tf){
  var line = getCandleLine(coin);
  if(!line || !line.proxyPath) return;
  var url = PROXY_BASE + line.proxyPath + '?' + line.proxyParams + '&tf=' + encodeURIComponent(tf);
  fetch(url).then(function(r){ return r.json(); }).then(function(data){
    if(!data || !data.ok) return;
    if(data.closes && data.closes.length > 1){ line.points = data.closes; line.liveOk = true; }
    if(data.candles && data.candles.length > 1) line.candles = data.candles;
    renderCandles(coin, currentLang());
  }).catch(function(){});
}

function wireTimeframeTabs(){
  var tabs = document.querySelectorAll('#candleTfTabs .tab');
  Array.prototype.forEach.call(tabs, function(btn){
    btn.onclick = function(){
      Array.prototype.forEach.call(tabs, function(b){ b.classList.remove('on'); });
      btn.classList.add('on');
      var coin = COINS[window.GalaxiaCurrentCoin];
      if(coin) fetchCandleData(coin, btn.getAttribute('data-tf'));
    };
  });
}

var tickerIntervalId = null;
var liveExchangeData = {};

// Headline price = the most liquid market (highest 24h volume), not the highest quote: a thin
// exchange can print an outlier price that the rest of the market doesn't trade at. XLN is the
// exception, by its owner's decision: the highest price among its live exchanges (same rule as
// the API, public-api.js).
var HIGHEST_PRICE_COINS = { xln: true };
function headlineTicker(id, list){
  var best = null;
  list.forEach(function(d){
    if(!d || d.price == null || !(d.price > 0) || d.cross) return;
    if(best === null){ best = d; return; }
    if(HIGHEST_PRICE_COINS[id]){ if(d.price > best.price) best = d; return; }
    if((d.volume || 0) > (best.volume || 0) || ((d.volume || 0) === (best.volume || 0) && d.price > best.price)) best = d;
  });
  return best;
}

function updateMainPriceDisplay(){
  var keys = Object.keys(liveExchangeData);
  if(!keys.length) return;
  var best = headlineTicker(window.GalaxiaCurrentCoin, keys.map(function(name){ return liveExchangeData[name]; }));
  if(!best) return;
  setText('.price', 'USDT ' + fmtPrice(best.price));
  var gainEl = document.querySelector('.gain');
  if(gainEl){
    var changeVal = best.change;
    if(changeVal == null){
      keys.some(function(name){
        var d = liveExchangeData[name];
        if(d && d.change != null){ changeVal = d.change; return true; }
        return false;
      });
    }
    if(changeVal != null){
      gainEl.style.color = changeVal >= 0 ? 'var(--green)' : 'var(--red)';
      gainEl.childNodes[0].nodeValue = (changeVal >= 0 ? '+' : '') + changeVal.toFixed(2) + '% ';
    }
  }
}

function renderTickerRow(coin, lang){
  var row = document.getElementById('tickerRow');
  if(!row || !coin.chartLines) return;
  row.innerHTML = coin.chartLines.map(function(l){
    return '<div class=tickerCard data-ticker-exchange="' + l.name + '"><div class=tHead><span class=tName>' + l.name + '</span><span class=tLive style="visibility:hidden">' + pick(I18N.tickerLive, lang) + '</span></div><div class=tPrice>—</div><div class=tBidAsk><span><span class=tLabel>' + pick(I18N.tickerBuy, lang) + '</span><span class=tBid>—</span></span><span><span class=tLabel>' + pick(I18N.tickerSell, lang) + '</span><span class=tAsk>—</span></span></div></div>';
  }).join('');
  Array.prototype.forEach.call(row.querySelectorAll('.tickerCard'), function(card){
    card.onclick = function(){
      activeCandleExchangeName = card.getAttribute('data-ticker-exchange');
      var activeTab = document.querySelector('#candleTfTabs .tab.on');
      fetchCandleData(coin, activeTab ? activeTab.getAttribute('data-tf') : '7D');
    };
  });
}

function fetchTickerRow(coin){
  var row = document.getElementById('tickerRow');
  if(!coin.chartLines) return;
  coin.chartLines.forEach(function(l){
    if(!l.proxyPath) return;
    var tickerPath = l.proxyPath.replace('/klines/', '/ticker/');
    var url = PROXY_BASE + tickerPath + '?' + l.proxyParams;
    fetch(url).then(function(r){ return r.json(); }).then(function(data){
      if(!data || !data.ok) return;
      // an answer that arrives after the visitor moved to another coin belongs to the old page
      if(COINS[window.GalaxiaCurrentCoin] !== coin) return;
      // no trade in 24h, or no trade at all yet (the market answers but has no price)
      var idle = !!data.stale || (data.price == null && !data.halted);
      if(l.cross){
        // a pair quoted in another coin (XLN/XLNFT): how much of the other coin one unit gives, live from
        // the exchange -- no USDT value, so it stays out of the headline price and of the totals
        var unit = String(data.quote || '').replace(/[^A-Z0-9]/g, ''), baseUnit = String(data.base || '').replace(/[^A-Z0-9]/g, '');
        var quiet = !!data.stale || data.pair_price == null;
        var xcard = row ? row.querySelector('[data-ticker-exchange="' + l.name + '"]') : null;
        if(xcard){
          var xp = xcard.querySelector('.tPrice'); if(xp) xp.textContent = data.pair_price != null ? fmtPrice(data.pair_price) + ' ' + unit : '\u2014';
          var xb = xcard.querySelector('.tBid'); if(xb) xb.textContent = data.pair_bid != null ? fmtPrice(data.pair_bid) : '\u2014';
          var xa = xcard.querySelector('.tAsk'); if(xa) xa.textContent = data.pair_ask != null ? fmtPrice(data.pair_ask) : '\u2014';
          var xl = xcard.querySelector('.tLive');
          if(xl){ xl.textContent = pick(quiet ? I18N.tickerInactive : I18N.tickerLive, currentLang()); xl.style.color = quiet ? 'var(--amber)' : ''; xl.style.visibility = 'visible'; }
        }
        var xrow = document.querySelector('.tablePanel tbody tr[data-ex-row="' + l.name + '"]');
        if(xrow){
          var rp = xrow.querySelector('.exPrice'); if(rp) rp.textContent = data.pair_price != null ? fmtPrice(data.pair_price) + ' ' + unit : '\u2014';
          var rc = xrow.querySelector('.exChange');
          if(rc){
            if(quiet || data.change == null){ rc.textContent = quiet ? pick(I18N.tickerInactive, currentLang()) : '\u2014'; rc.style.color = quiet ? 'var(--amber)' : 'inherit'; }
            else { rc.textContent = (data.change >= 0 ? '+' : '') + data.change.toFixed(2) + '%'; rc.style.color = data.change >= 0 ? 'var(--green)' : 'var(--red)'; }
          }
          var rv = xrow.querySelector('.exVolume'); if(rv) rv.textContent = data.base_volume != null ? Number(data.base_volume).toLocaleString('en-US', { maximumFractionDigits: 2 }) + ' ' + baseUnit : '\u2014';
        }
        return;
      }
      var card = row ? row.querySelector('[data-ticker-exchange="' + l.name + '"]') : null;
      if(card){
        if(data.price != null){ var pEl = card.querySelector('.tPrice'); if(pEl) pEl.textContent = fmtPrice(data.price) + ' USDT'; }
        if(data.bid != null){ var bEl = card.querySelector('.tBid'); if(bEl) bEl.textContent = fmtPrice(data.bid); }
        if(data.ask != null){ var aEl = card.querySelector('.tAsk'); if(aEl) aEl.textContent = fmtPrice(data.ask); }
        var liveEl = card.querySelector('.tLive');
        if(liveEl){
          liveEl.textContent = pick(data.halted ? I18N.tickerHalted : (idle ? I18N.tickerInactive : I18N.tickerLive), currentLang());
          liveEl.style.color = data.halted || idle ? 'var(--amber)' : '';
          liveEl.style.visibility = 'visible';
        }
      }
      var exRow = document.querySelector('.tablePanel tbody tr[data-ex-row="' + l.name + '"]');
      if(exRow){
        if(data.price != null){ var pc = exRow.querySelector('.exPrice'); if(pc) pc.textContent = fmtPrice(data.price); }
        // no trade in 24h, or trading paused: there is no current price to show
        else if(idle || data.halted){ var pc0 = exRow.querySelector('.exPrice'); if(pc0) pc0.textContent = '\u2014'; }
        if(data.change != null){
          var cc = exRow.querySelector('.exChange');
          if(cc){ cc.textContent = (data.change >= 0 ? '+' : '') + data.change.toFixed(2) + '%'; cc.style.color = data.change >= 0 ? 'var(--green)' : 'var(--red)'; }
        }
        if(data.volume != null){ var vc = exRow.querySelector('.exVolume'); if(vc) vc.textContent = 'USDT ' + data.volume.toLocaleString('en-US', { maximumFractionDigits: 2 }); }
        if(data.halted || idle){ var hc = exRow.querySelector('.exChange'); if(hc){ hc.textContent = pick(data.halted ? I18N.tickerHalted : I18N.tickerInactive, currentLang()); hc.style.color = 'var(--amber)'; } }
      }
      if(data.halted){ delete liveExchangeData[l.name]; return; }
      if(data.price != null || data.change != null || data.volume != null){
        liveExchangeData[l.name] = { price: data.price, change: data.change, volume: data.volume, cross: !!l.cross };
        updateMainPriceDisplay();
      }
    }).catch(function(){});
  });
}

function startTickerPolling(coin){
  if(tickerIntervalId) clearInterval(tickerIntervalId);
  fetchTickerRow(coin);
  tickerIntervalId = setInterval(function(){ fetchTickerRow(coin); }, 15000);
}

var FX_RATES = null;
var LANG_CURRENCY = {
  en:'USD', ru:'RUB', de:'EUR', pl:'PLN', es:'EUR', vi:'VND', fr:'EUR', 'pt-BR':'BRL', ar:'USD',
  bg:'BGN', cs:'CZK', da:'DKK', el:'EUR', fi:'EUR', he:'ILS', hi:'INR', hr:'EUR', hu:'HUF',
  id:'IDR', it:'EUR', ja:'JPY', ko:'KRW', lt:'EUR', nl:'EUR', no:'NOK', ro:'RON', sk:'EUR',
  sl:'EUR', sv:'SEK', th:'THB', tr:'TRY', uk:'UAH', zh:'CNY', 'zh-TW':'TWD'
};

function getLocalCurrency(){
  return LANG_CURRENCY[currentLang()] || 'USD';
}

function converterCurrencyList(){
  var local = getLocalCurrency();
  var list = ['COIN', 'USD'];
  if(list.indexOf(local) < 0) list.push(local);
  if(list.indexOf('EUR') < 0) list.push('EUR');
  return list;
}

function fetchFxRates(){
  fetch(PROXY_BASE + '/api/fx').then(function(r){ return r.json(); }).then(function(data){
    if(data && data.ok && data.rates){ FX_RATES = data.rates; runConverter(); }
  }).catch(function(){});
}

function converterCoinId(){
  var av = document.getElementById('auditoriaView');
  if(auditCoin && AUDIT_COINS[auditCoin] && av && av.classList.contains('show')) return AUDIT_COINS[auditCoin].coin;
  return window.GalaxiaCurrentCoin || 'xln';
}

var CONV_PRICE_TTL_MS = 60000;
var convPriceCache = {};
var convPriceLoading = {};
function fetchConverterPrice(id){
  var coin = COINS[id];
  if(!coin || !coin.chartLines || convPriceLoading[id]) return;
  var lines = coin.chartLines.filter(function(l){ return l.proxyPath; });
  if(!lines.length) return;
  convPriceLoading[id] = true;
  Promise.all(lines.map(function(l){
    var url = PROXY_BASE + l.proxyPath.replace('/klines/', '/ticker/') + '?' + l.proxyParams;
    return fetch(url).then(function(r){ return r.json(); }).then(function(d){ if(d && l.cross) d.cross = true; return d; }).catch(function(){ return null; });
  })).then(function(results){
    convPriceLoading[id] = false;
    var best = headlineTicker(id, results.filter(function(d){ return d && d.ok; }));
    if(best){ convPriceCache[id] = { price: best.price, at: Date.now() }; }
    if(converterCoinId() === id) runConverter();
  });
}

function getCurrentCoinPriceUsd(){
  var id = converterCoinId();
  if(id !== window.GalaxiaCurrentCoin){
    var cached = convPriceCache[id];
    if(!cached || Date.now() - cached.at > CONV_PRICE_TTL_MS) fetchConverterPrice(id);
    if(cached) return cached.price;
    var other = COINS[id];
    var seed = other ? parseFloat(String(pick(other.price, 'en')).replace(/[^0-9.]/g, '')) : NaN;
    return isFinite(seed) && seed > 0 ? seed : null;
  }
  if(HIGHEST_PRICE_COINS[id]){
    var top = headlineTicker(id, Object.keys(liveExchangeData).map(function(name){ return liveExchangeData[name]; }));
    if(top) return top.price;
  }
  var card = document.querySelector('.tickerCard.tActive .tPrice');
  if(card){
    var v = parseFloat(card.textContent);
    if(isFinite(v) && v > 0) return v;
  }
  var coin = COINS[window.GalaxiaCurrentCoin];
  if(coin && coin.price){
    var v2 = parseFloat(String(coin.price).replace(/[^0-9.]/g, ''));
    if(isFinite(v2) && v2 > 0) return v2;
  }
  return null;
}

function convToUsd(amount, currency){
  if(!isFinite(amount)) return null;
  if(currency === 'COIN'){
    var price = getCurrentCoinPriceUsd();
    return price != null ? amount * price : null;
  }
  if(currency === 'USD') return amount;
  if(FX_RATES && FX_RATES[currency] != null) return amount / FX_RATES[currency];
  return null;
}

function convFromUsd(usd, currency){
  if(usd == null || !isFinite(usd)) return null;
  if(currency === 'COIN'){
    var price = getCurrentCoinPriceUsd();
    return (price != null && price > 0) ? usd / price : null;
  }
  if(currency === 'USD') return usd;
  if(FX_RATES && FX_RATES[currency] != null) return usd * FX_RATES[currency];
  return null;
}

function fmtConvNumber(v){
  if(v == null || !isFinite(v)) return '';
  var abs = Math.abs(v);
  if(abs === 0) return '0';
  if(abs >= 1) return String(Math.round(v * 10000) / 10000);
  return v.toFixed(8).replace(/0+$/, '').replace(/\.$/, '');
}

function populateConverterCurrencies(resetToLocal){
  var coinLabel = document.getElementById('convCoinLabel');
  var toSel = document.getElementById('convToCurrency');
  if(!coinLabel || !toSel) return;
  var coin = COINS[converterCoinId()];
  var ticker = coin ? coin.ticker : 'XLN';
  coinLabel.textContent = ticker;
  var list = converterCurrencyList().filter(function(c){ return c !== 'COIN'; });
  var localCurrency = getLocalCurrency();
  var prev = toSel.value;
  toSel.innerHTML = list.map(function(c){ return '<option value="' + c + '">' + (c === 'USD' ? 'USDT' : c) + '</option>'; }).join('');
  var target = resetToLocal ? localCurrency : prev;
  toSel.value = list.indexOf(target) >= 0 ? target : list[0];
}

function runConverter(){
  var fromAmountEl = document.getElementById('convFromAmount');
  var toAmountEl = document.getElementById('convToAmount');
  var toSel = document.getElementById('convToCurrency');
  var hintEl = document.getElementById('convHint');
  if(!fromAmountEl || !toAmountEl || !toSel) return;
  var labelEl = document.getElementById('convCoinLabel');
  var labelCoin = COINS[converterCoinId()];
  if(labelEl && labelCoin && labelEl.textContent !== labelCoin.ticker) labelEl.textContent = labelCoin.ticker;
  var toCur = toSel.value;
  var fromAmount = parseFloat(fromAmountEl.value);
  var usd = convToUsd(fromAmount, 'COIN');
  var toAmount = convFromUsd(usd, toCur);
  toAmountEl.value = toAmount != null ? fmtConvNumber(toAmount) : '';
  if(hintEl){
    var price = getCurrentCoinPriceUsd();
    var coin = COINS[converterCoinId()];
    hintEl.textContent = (price != null && coin) ? ('1 ' + coin.ticker + ' = ' + fmtConvNumber(price) + ' USDT') : '';
  }
}

var converterIntervalId = null;

function initConverterForCoin(resetToLocal){
  populateConverterCurrencies(!!resetToLocal);
  runConverter();
}
window.GalaxiaRefreshConverter = function(){ initConverterForCoin(false); };

function startConverterPolling(){
  if(converterIntervalId) clearInterval(converterIntervalId);
  converterIntervalId = setInterval(function(){ runConverter(); }, 15000);
}

function initConverter(){
  var fromAmountEl = document.getElementById('convFromAmount');
  var toSel = document.getElementById('convToCurrency');
  if(!fromAmountEl) return;
  populateConverterCurrencies(true);
  fetchFxRates();
  fromAmountEl.addEventListener('input', function(){ runConverter(); });
  toSel.addEventListener('change', function(){ runConverter(); });
  runConverter();
  startConverterPolling();
}

var networkIntervalId = null;

function applyNetworkStats(coin, lang){
  var kpis = document.querySelectorAll('#dashboardView .kpi');
  if(kpis[2]){ var s2 = kpis[2].querySelector('strong'); if(s2) s2.textContent = coin.kpis[2].value; }
  if(kpis[3]){ var s3 = kpis[3].querySelector('strong'); if(s3) s3.textContent = coin.kpis[3].value; }
  var bottoms = document.querySelectorAll('.bottom');
  if(bottoms[0]) bottoms[0].innerHTML = coin.bottomStats.map(function(b){
    var label = pick(b.label, lang);
    if(b.linkUrl) return '<div><label>' + label + '</label><strong style=color:var(--cyan)><a href="' + b.linkUrl + '" target=_blank rel=noopener style=color:inherit>' + pick(b.linkText, lang) + '</a></strong></div>';
    return '<div><label>' + label + '</label><strong>' + b.value + '</strong></div>';
  }).join('');
}

function fmtHashrate(h){
  if(!isFinite(h)) return '—';
  var units = ['H/s','KH/s','MH/s','GH/s','TH/s','PH/s','EH/s'];
  var i = 0;
  while(h >= 1000 && i < units.length - 1){ h /= 1000; i++; }
  return h.toFixed(2) + ' ' + units[i];
}

function fmtUsd(v){ return 'USD ' + Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

// Fills price/market KPIs, the pool row and the volume donut from /api/network/<coin> once the
// token's DEX pool exists. Returns true the first time the pool shows up, so the page re-renders.
function applyDexMarket(coin, data){
  if(!coin.dexMarket || !data.hasPool) return false;
  var first = !coin.dexLive;
  coin.dexLive = true;
  var dexName = /pancakeswap/i.test(data.dex || '') ? 'PancakeSwap' : (data.dex || 'DEX');
  if(data.fdvUsd != null){ coin.kpis[0].value = fmtUsd(data.fdvUsd); coin.kpis[0].delta = I18N.xlnftFdvDelta; }
  if(data.liquidityUsd != null){ coin.kpis[1].value = fmtUsd(data.liquidityUsd); coin.kpis[1].delta = {sourceName:'GeckoTerminal'}; }
  if(data.priceUsd != null) coin.price = 'USD ' + fmtPrice(data.priceUsd);
  if(data.change24h != null){
    coin.change = (data.change24h >= 0 ? '+' : '') + data.change24h.toFixed(2) + '%';
    coin.changeColor = data.change24h >= 0 ? 'var(--green)' : 'var(--red)';
  }else{
    coin.change = '—'; coin.changeColor = 'inherit';
  }
  var ex = coin.exchanges[0];
  if(ex){
    ex.name = dexName;
    if(data.poolName) ex.pair = data.poolName;
    ex.price = data.priceUsd != null ? fmtPrice(data.priceUsd) : '—';
    ex.change = coin.change; ex.changeColor = coin.changeColor;
    ex.volume = data.volume24h != null ? fmtUsd(data.volume24h) : '—';
  }
  coin.donutGradient = 'conic-gradient(var(--cyan) 0 100%)';
  coin.donutText = data.volume24h != null ? 'USD<br>' + Math.round(data.volume24h).toLocaleString('en-US') : '—';
  coin.legend = [{name: dexName, value: data.volume24h != null ? fmtUsd(data.volume24h) : '—', pct:'100%', color:'var(--cyan)'}];
  coin.alerts = coin.alerts.filter(function(a){ return a.b !== I18N.xlnftPoolSoon; });
  return first;
}

// ---- "Status das Exchanges". The market lines are written from the coin's live markets (public API
// snapshot) and the masternode line from the network endpoint, so no figure in this box is typed;
// the lines kept in COINS are only facts that do not change (consensus code, contract, peg).
function liveMarketAlerts(d, lang){
  var ms = ((d && d.markets) || []).filter(function(m){ return m && m.pair && !m.reference_only; });
  var out = [];
  var tpl = function(key, vars){ return String(pick(I18N[key], lang)).replace(/\{(\w+)\}/g, function(all, k){ return vars[k] != null ? vars[k] : all; }); };
  var chg = function(m){ var c = m.change_24h_pct; return c == null ? '—' : (c >= 0 ? '+' : '') + Number(c).toFixed(2) + '%'; };
  var live = ms.filter(function(m){ return m.status === 'live'; }).sort(function(a, b){ return (b.volume_24h_usd || 0) - (a.volume_24h_usd || 0); });
  live.forEach(function(m, i){
    var v = { ex: escHtml(m.exchange), pair: escHtml(m.pair), chg: chg(m), vol: m.volume_24h_usd != null ? Number(m.volume_24h_usd).toLocaleString('en-US', { maximumFractionDigits: m.volume_24h_usd >= 1000 ? 0 : 2 }) : '—' };
    if(i === 0 && ms.length > 1 && m.volume_24h_usd > 0) out.push({ dot:'var(--cyan)', b:tpl('alertTopB', v), span:tpl('alertTopSpan', v) });
    else if(i === 0 || ms.length <= 3) out.push({ dot:'var(--green)', b:tpl('alertActiveB', v), span:tpl('alertActiveSpan', v) });
  });
  ms.filter(function(m){ return m.status === 'inactive' || m.status === 'paused'; }).forEach(function(m){
    var v = { ex: escHtml(m.exchange) };
    var span = escHtml(m.pair);
    if(m.last_trade_price_usd != null && m.last_trade_at){
      span += ' · ' + tpl('alertLastSpan', { price: fmtPrice(m.last_trade_price_usd), date: new Date(m.last_trade_at).toLocaleDateString(lang, { day:'2-digit', month:'2-digit', year:'numeric' }) });
    }
    out.push({ dot:'var(--amber)', b: m.status === 'paused' ? v.ex + ' — ' + escHtml(pick(I18N.tickerHalted, lang)) : tpl('alertInactiveB', v), span: span });
  });
  return out;
}
function networkAlert(al, net, lang){
  if(al.kind !== 'masternodes' || !net || net.masternodesOnline == null || net.masternodesOnion == null) return null;
  var n = function(x){ return Number(x || 0).toLocaleString('en-US'); };
  return { dot: al.dot,
    b: String(pick(I18N.alertMnB, lang)).replace('{n}', n(net.masternodesOnline)),
    span: String(pick(I18N.alertMnSpan, lang)).replace('{o}', n(net.masternodesOnion)).replace('{v6}', n(net.masternodesIpv6)).replace('{v4}', n(net.masternodesIpv4)) };
}
function renderAlerts(coin, lang){
  var box = document.getElementById('coinAlerts');
  if(!box){
    var first = document.querySelector('#dashboardView .alert');
    if(!first) return;
    box = first.parentElement;
    box.id = 'coinAlerts';
  }
  var btn = box.querySelector('.link');
  Array.prototype.forEach.call(box.querySelectorAll('.alert'), function(a){ a.remove(); });
  var list = coin.exchangeCoin ? [] : liveMarketAlerts(coin.liveSnap, lang);
  (coin.alerts || []).forEach(function(al){
    if(al.kind){ var live = networkAlert(al, coin.netSnap, lang); if(live) list.push(live); return; }
    list.push({ dot: al.dot, b: pick(al.b, lang), span: pick(al.span, lang) });
  });
  list.forEach(function(al){
    var div = document.createElement('div');
    div.className = 'alert';
    div.innerHTML = '<i class=dot style=background:' + al.dot + '></i><p><b>' + al.b + '</b><span>' + al.span + '</span></p>';
    box.insertBefore(div, btn);
  });
}

function fetchNetworkStats(coin, id){
  if(!coin.networkApi) return;
  fetch(PROXY_BASE + coin.networkApi).then(function(r){ return r.json(); }).then(function(data){
    if(!data || !data.ok || window.GalaxiaCurrentCoin !== id) return;
    coin.netSnap = data;
    if((coin.alerts || []).some(function(al){ return al.kind; })) renderAlerts(coin, currentLang());
    if(data.supply != null){
      var supplyStr = Math.round(data.supply).toLocaleString('en-US');
      coin.kpis[2].value = supplyStr + ' ' + coin.ticker;
      coin.bottomStats[0].value = supplyStr;
    }
    if(data.masternodesOnline != null) coin.kpis[3].value = data.masternodesOnline.toLocaleString('en-US') + ' online';
    else if(data.hashrate != null) coin.kpis[3].value = fmtHashrate(data.hashrate);
    var keyed = coin.bottomStats.some(function(b){ return b.liveKey; });
    if(keyed){
      coin.bottomStats.forEach(function(b){
        var v = b.liveKey ? data[b.liveKey] : null;
        if(v == null || !isFinite(v)) return;
        b.value = b.liveFmt === 'pct' ? v.toFixed(2) + '%' : Math.round(v).toLocaleString('en-US');
      });
    }else{
      if(data.blockCount != null) coin.bottomStats[1].value = data.blockCount.toLocaleString('en-US');
      if(data.difficulty != null) coin.bottomStats[2].value = data.difficulty.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      if(data.connections != null) coin.bottomStats[3].value = String(data.connections);
    }
    if(applyDexMarket(coin, data)){ renderCoin(id); return; }
    if(coin.dexLive){
      var kp = document.querySelectorAll('#dashboardView .kpi');
      [0, 1].forEach(function(i){ var s = kp[i] && kp[i].querySelector('strong'); if(s) s.textContent = coin.kpis[i].value; });
    }
    applyNetworkStats(coin, currentLang());
  }).catch(function(){});
}

function startNetworkPolling(coin, id){
  if(networkIntervalId) clearInterval(networkIntervalId);
  if(!coin.networkApi) return;
  fetchNetworkStats(coin, id);
  networkIntervalId = setInterval(function(){ fetchNetworkStats(coin, id); }, 30000);
}

function fetchLiveLines(coin, id){
  if(!coin.chartLines) return;
  coin.chartLines.forEach(function(l){
    if(!l.live || !l.proxyPath) return;
    var url = PROXY_BASE + l.proxyPath + '?' + l.proxyParams;
    fetch(url).then(function(r){ return r.json(); }).then(function(data){
      if(data && data.ok && data.closes && data.closes.length > 1){
        l.points = data.closes;
        l.liveOk = true;
        if(data.candles && data.candles.length > 1) l.candles = data.candles;
        if(window.GalaxiaCurrentCoin === id){
          renderChart(coin, currentLang());
          if(l.name === activeCandleExchangeName || l.candlePrimary) renderCandles(coin, currentLang());
        }
      }
    }).catch(function(){});
  });
}

