var EXSTATUS_CODES = { ok: 0, explorer_down: 1, no_supply: 2, supply_invalid: 3, stale: 4, not_circulating: 5, no_explorer: 6, read_failed: 7 };
// status code of a coin: from the exchange-coin list (the server checks its explorer and its supply
// reading) or, for a coin with its own page, from the API answer the page already loads
function explorerStatusCode(id){
  var c = exchangeCoinData[id];
  if(c) return (c.supply_status && c.supply_status.code) || null;
  var hit = liveKpiCache[id], d = hit && hit.data;
  if(!d) return null;
  return d.supply_status || (d.supply != null ? 'ok' : null);
}
function explorerStatusHtml(id, lang){
  var code = explorerStatusCode(id), i = EXSTATUS_CODES[code];
  if(i == null) return '';
  var t = EXSTATUS_I18N[lang] || EXSTATUS_I18N.en, ok = code === 'ok';
  return '<span class=exStatus data-status="' + escHtml(code) + '" style="display:block;margin-top:4px;font-size:12px;line-height:1.3;font-weight:700;white-space:normal;overflow-wrap:anywhere;color:' + (ok ? 'var(--green)' : 'var(--red)') + '">\u25CF ' + escHtml(t[i]) + '</span>' +
    (ok ? '' : '<span style="display:block;margin-top:2px;font-size:11px;line-height:1.3;font-weight:600;white-space:normal;overflow-wrap:anywhere;color:var(--red);opacity:.85">' + escHtml(t[8]) + '</span>');
}
function refreshExplorerStatus(id){
  if(window.GalaxiaCurrentCoin !== id) return;
  var el = document.getElementById('explorerStatus');
  if(el) el.innerHTML = explorerStatusHtml(id, currentLang());
}

// A market an exchange has announced but not opened yet is written in the coin with `whenListed`
// (chart line, exchange row, link). Those entries are kept apart here and only join the page when
// the server reports that market for the coin (/api/v1/coins/<id>), which it does from the first
// answer of the exchange's own ticker -- nothing is shown for a market that does not exist.
var PENDING_MARKET_KEYS = ['chartLines', 'exchanges', 'subsExchanges'];
var PENDING_MARKETS = {};
Object.keys(COINS).forEach(function(id){
  var c = COINS[id], held = {}, n = 0;
  PENDING_MARKET_KEYS.forEach(function(k){
    held[k] = (c[k] || []).filter(function(x){ return x.whenListed; });
    if(held[k].length){ n += held[k].length; c[k] = c[k].filter(function(x){ return !x.whenListed; }); }
  });
  if(n) PENDING_MARKETS[id] = held;
});
function openPendingMarkets(id, markets){
  var held = PENDING_MARKETS[id], coin = COINS[id], opened = false, on = {};
  if(!held || !coin || !markets) return false;
  markets.forEach(function(m){ on[m.exchange] = true; });
  PENDING_MARKET_KEYS.forEach(function(k){
    held[k] = held[k].filter(function(x){
      if(!on[x.name]) return true;
      (coin[k] = coin[k] || []).push(x);
      opened = true;
      return false;
    });
  });
  return opened;
}

function renderCoin(id){
  var coin = COINS[id]; if(!coin) return;
  if(window.GalaxiaCurrentCoin !== id){ activeCandleExchangeName = null; liveExchangeData = {}; }
  window.GalaxiaCurrentCoin = id;
  window.GalaxiaCoinTicker = coin.ticker;
  var lang = currentLang();

  // the address follows the coin only while its page is on screen: a redraw in the background (live
  // data, language detection) must not move it away from the view the visitor is on (Auditoria, a list)
  if(!document.querySelector('.moedasView.show, #exchangesView.show')) try{
    var shareUrl = new URL(location.href);
    shareUrl.searchParams.delete('view');
    shareUrl.searchParams.delete('exchange');
    shareUrl.searchParams.delete('audit');
    shareUrl.searchParams.delete('kind');
    shareUrl.searchParams.set('coin', id);
    history.replaceState(null, '', shareUrl.toString());
  }catch(e){}

  var coinImg = document.querySelector('#dashboardTop .coin img');
  if(coinImg){ coinImg.src = coin.icon; coinImg.alt = coin.ticker; }
  setText('#dashboardTop .asset h1', coin.name);
  var pillEl = document.querySelector('#dashboardTop .asset .pill');
  if(pillEl) pillEl.style.display = coin.isOfficial ? '' : 'none';

  renderChart(coin, lang);
  renderCandles(coin, lang);
  renderTickerRow(coin, lang);
  startTickerPolling(coin);
  startNetworkPolling(coin, id);
  fetchLiveLines(coin, id);
  initConverterForCoin();

  setText('.price', pick(coin.price, lang));
  var gainEl = document.querySelector('.gain');
  if(gainEl){ gainEl.style.color = coin.changeColor; gainEl.childNodes[0].nodeValue = pick(coin.change, lang) + ' ';
    // the "24h" suffix only makes sense next to a % change, not a status text like "pool coming soon"
    var gainSuffix = gainEl.querySelector('span'); if(gainSuffix) gainSuffix.style.display = /%$/.test(coin.change) ? '' : 'none'; }

  var kpis = document.querySelectorAll('#dashboardView .kpi');
  coin.kpis.forEach(function(k, i){
    if(!kpis[i]) return;
    var strong = kpis[i].querySelector('strong');
    var delta = kpis[i].querySelector('.delta');
    if(strong) strong.textContent = k.value;
    if(delta){
      var deltaText = (k.delta && k.delta.sourceName) ? (pick(I18N.sourcePrefix, lang) + ' ' + k.delta.sourceName) : pick(k.delta, lang);
      delta.textContent = deltaText;
    }
  });

  var donut = document.querySelector('.donut');
  if(donut){
    donut.style.background = coin.donutGradient;
    var span = donut.querySelector('span');
    if(span) span.innerHTML = coin.donutText;
  }

  setHTML('#dashboardView .legend', coin.legend.map(function(l){
    return '<div><i class=dot style=background:' + l.color + '></i><span>' + l.name + '<br><b>' + l.value + '</b></span><span>' + l.pct + '</span></div>';
  }).join(''));

  renderAlerts(coin, lang);

  setHTML('.tablePanel tbody', coin.exchanges.map(function(ex, i){
    var logoHTML = ex.logo ? ('<img src=' + ex.logo + ' alt=' + ex.name + '>') : ex.name.charAt(0);
    return '<tr data-ex-row="' + ex.name + '"><td>' + (i + 1) + '</td><td><a href="' + ex.url + '" target=_blank rel=noopener class=platform style=color:inherit;text-decoration:none><i class=badge>' + logoHTML + '</i>' + (ex.label || ex.name) + '</a></td><td>' + ex.type + '</td><td>' + ex.pair + '</td><td class=exPrice>' + pick(ex.price, lang) + '</td><td class=exChange style=color:' + ex.changeColor + '>' + pick(ex.change, lang) + '</td><td class=exVolume>' + pick(ex.volume, lang) + '</td></tr>';
  }).join(''));

  var bottoms = document.querySelectorAll('.bottom');
  if(bottoms[0]) bottoms[0].innerHTML = coin.bottomStats.map(function(b){
    var label = pick(b.label, lang);
    if(b.linkUrl) return '<div><label>' + label + '</label><strong style=color:var(--cyan)><a href="' + b.linkUrl + '" target=_blank rel=noopener style=color:inherit>' + pick(b.linkText, lang) + '</a></strong></div>';
    return '<div><label>' + label + '</label><strong>' + b.value + '</strong></div>';
  }).join('');
  // the explorer link carries the live status: explorer answering and supply verified, or the alert
  var statusPlaced = false;
  if(bottoms[1]) bottoms[1].innerHTML = coin.officialLinks.map(function(l){
    var isExplorer = !statusPlaced && (l.label === 'Explorer' || l.label === I18N.s11ContractBscScanLabel);
    if(isExplorer) statusPlaced = true;
    return '<div><label>' + pick(l.label, lang) + '</label><strong style=color:var(--cyan)><a href="' + l.url + '" target=_blank rel=noopener style=color:inherit>' + pick(l.text, lang) + '</a></strong>' +
      (isExplorer ? '<span id=explorerStatus style=display:block>' + explorerStatusHtml(id, lang) + '</span>' : '') + '</div>';
  }).join('') + (statusPlaced ? '' : '<div><label>Explorer</label><span id=explorerStatus style=display:block>' + explorerStatusHtml(id, lang) + '</span></div>');

  if(typeof window.runLang === 'function') window.runLang(lang);
  applyCoinKpiLabels(coin, lang);
  fillLiveKpis(id);
  updateCoinHeaderStar(id);
  ensureCoinSearches(lang);
}

// The language script labels the 4 KPI cards positionally with XLN's labels (Market Cap, Volume,
// Supply, Masternodes); every other coin carries its own, so they're re-applied after each language
// pass (runLang calls window.GalaxiaApplyCoinLabels) -- including on first load via ?coin=.
function applyCoinKpiLabels(coin, lang){
  var kpis = document.querySelectorAll('#dashboardView .kpi');
  coin.kpis.forEach(function(k, i){
    if(!k.label || !kpis[i]) return;
    var label = kpis[i].querySelector('.label');
    if(label) label.textContent = pick(k.label, lang);
  });
}
window.GalaxiaApplyCoinLabels = function(lang){
  var coin = COINS[window.GalaxiaCurrentCoin];
  if(coin) applyCoinKpiLabels(coin, lang || currentLang());
};

