var AUDIT_COINS = {
  xln: { coin:'xln', audit:'/api/network/xln-audit', rewards:'/api/network/xln-rewards', unit:'XLN', daemon:'lunariumcoind', supplyAudit:true, note:'rwNote', sources:null, explain:'auditExplainText', ruleUrl:'https://github.com/Lunariumcoin-Labs/LunariumCoin/blob/main/src/masternode.cpp' },
  pivx: { coin:'pivx', audit:'/api/network/pivx-audit', rewards:'/api/network/pivx-rewards', unit:'PIVX', daemon:'pivxd', supplyAudit:true, note:'rwNotePivx', sources:'explorer.pivx.org · chainz.cryptoid.info', explain:'auditExplainTextPivx', ruleUrl:'https://github.com/PIVX-Project/PIVX/blob/master/src/validation.cpp' },
  mon: { coin:'mon', audit:'/api/network/mon-audit', rewards:'/api/network/mon-rewards', unit:'MON', daemon:'moneybyted', supplyAudit:true, note:'rwNoteMon', sources:'moneybyte-explorer.org', explain:'auditExplainTextMon', capSub:'monCapSub', ruleUrl:'https://github.com/MoneyByte/MoneyByteBlockchain/blob/master/src/main.cpp' },
  ns: { coin:'ns', audit:'/api/network/ns-audit', rewards:'/api/network/ns-rewards', unit:'NS', daemon:'nodestatsd', supplyAudit:true, note:'rwNoteNs', sources:'explorer.nodestats.info · coinexplorer.net', explain:'auditExplainTextNs', officialNote:'auditNsOfficialNote', gapDecimals:2, supplyLabel:'kpiTotalSupply', ruleUrl:'https://github.com/NODESTATS-NS/nodestats/blob/main/src/masternode.cpp' }
};
AUDIT_COINS.btc = { coin:'btc', audit:'/api/network/btc-audit', rewards:null, unit:'BTC', daemon:'bitcoind', supplyAudit:true, sources:'blockchair.com · mempool.space', explain:'auditExplainTextBtc', ruleUrl:'https://github.com/bitcoin/bitcoin/blob/master/src/validation.cpp', kpi4:'hashrate', miningCard:true, gapDecimals:8 };
// Litecoin: Bitcoin's rule with 840,000-block halvings; coins mined per window measured from the supply (MWEB fees are not in the explorer's fee total)
AUDIT_COINS['ltc-coin'] = { coin:'ltc-coin', audit:'/api/network/ltc-audit', rewards:null, unit:'LTC', daemon:'litecoind', supplyAudit:true, sources:'blockchair.com', explain:'auditExplainTextLtc', ruleUrl:'https://github.com/litecoin-project/litecoin/blob/master/src/validation.cpp', kpi4:'hashrate', miningCard:true, miningNote:'miningNoteLtc', gapDecimals:8 };
// Dogecoin: random rewards up to block 145,000 (the chain's own total), then fixed, 10,000 per block forever from 600,000
AUDIT_COINS['doge-coin'] = { coin:'doge-coin', audit:'/api/network/doge-audit', rewards:null, unit:'DOGE', daemon:'dogecoind', supplyAudit:true, sources:'blockchair.com', explain:'auditExplainTextDoge', ruleUrl:'https://github.com/dogecoin/dogecoin/blob/master/src/dogecoin.cpp', kpi4:'hashrate', miningCard:true, gapDecimals:0 };
// Bitcoin Cash: Bitcoin's rule; the supply is the coins every block created, summed block by block (blockchair's summary counts orphaned blocks)
AUDIT_COINS.bch = { coin:'bch', audit:'/api/network/bch-audit', rewards:null, unit:'BCH', daemon:'bitcoind (BCHN)', supplyAudit:true, sources:'blockchair.com · rest.bch.actorforth.org (Bitcoin Cash Node)', explain:'auditExplainTextBch', ruleUrl:'https://gitlab.com/bitcoin-cash-node/bitcoin-cash-node/-/blob/master/src/validation.cpp', kpi4:'hashrate', miningCard:true, gapDecimals:8, supplyLabel:'kpiTotalSupply' };
// Dash: difficulty-era history from the chain, then Dash Core's fixed rule with the treasury and superblocks
AUDIT_COINS.dash = { coin:'dash', audit:'/api/network/dash-audit', rewards:null, unit:'DASH', daemon:'dashd', supplyAudit:true, sources:'chainz.cryptoid.info · blockchair.com', explain:'auditExplainTextDash', ruleUrl:'https://github.com/dashpay/dash/blob/master/src/validation.cpp', kpi4:'hashrate', miningCard:true, gapDecimals:2, supplyLabel:'kpiTotalSupply' };
