AUDIT_COINS.xlnft = { coin:'xlnft', audit:'/api/network/xlnft-audit', rewards:null, unit:'XLNFT', supplyAudit:true, sources:'BNB Chain (bsc-rpc.publicnode.com · bsc.rpc.blxrbdn.com) · PancakeSwap · PinkLock', explain:'tk26', ruleUrl:'https://bscscan.com/address/0x5a6625B65a917c872ceEc781B6c4419F6aBc8A48#code', kpi4:'holders', tokenCard:true, noDifficulty:true, supplyLabel:'kpiTotalSupply' };
var AUDIT_ORDER = ['xln', 'pivx', 'mon', 'ns', 'dash', 'btc', 'ltc-coin', 'doge-coin', 'bch', 'eth-coin', 'bnb', 'sol', 'xlnft'];
var auditCoin = null;
// 'stake' when a masternode + stake coin was opened from the stake group: the stake side only
var auditKind = null;

function fmtCoinAmt(v, unit){
  return v.toLocaleString('en-US', { maximumFractionDigits: 2 }) + ' ' + unit;
}

function auditNavLabel(){
  var b = document.querySelector('#auditoriaBtn span');
  return (b && b.textContent) || 'Auditoria';
}

function setAuditUrl(coinId, kind){
  try{
    var u = new URL(location.href);
    u.searchParams.delete('coin');
    u.searchParams.delete('exchange');
    u.searchParams.set('view', 'auditoria');
    if(coinId) u.searchParams.set('audit', coinId); else u.searchParams.delete('audit');
    if(coinId && kind) u.searchParams.set('kind', kind); else u.searchParams.delete('kind');
    history.replaceState(null, '', u.toString());
  }catch(e){}
}

// Same live online count shown in the Auditoria KPI above, so the two numbers always agree.
var auditLiveMasternodes = null;

function renderAuditRewards(cfg, lang){
  var grid = document.getElementById('auditRewardsGrid');
  if(!grid) return;
  setText('.auditRewardsTitleEl', pick(I18N.rwTitle, lang));
  fetch(PROXY_BASE + cfg.rewards).then(function(r){ return r.json(); }).then(function(d){
    if(auditCoin !== cfg.coin) return;
    if(!d || !d.ok){
      grid.innerHTML = '<p class=mini>' + pick(I18N.rwPending, lang) + '</p>';
      return;
    }
    var stakeOnly = auditKind === 'stake';
    var col = function(title, w){
      var mnPct = w.total > 0 ? (w.masternode / w.total) * 100 : 0;
      if(stakeOnly){
        // stake side only: what stakers received, and its share of everything the blocks paid
        return '<div class=rwCol>' +
          '<div class=rwHead><b>' + title + '</b><span>' + expT('rwBlocks', lang, { n: w.blocks.toLocaleString('en-US') }) + '</span></div>' +
          '<div class=rwTotal>' + fmtCoinAmt(w.stake, cfg.unit) + '</div><div class=rwTotalLabel>' + pick(I18N.rwStake, lang) + '</div>' +
          '<div class=rwRow><div class=rwRowHead><span>' + pick(I18N.rwTotal, lang) + '</span><b>' + fmtCoinAmt(w.total, cfg.unit) + ' · ' + (100 - mnPct).toFixed(0) + '%</b></div><div class=rwBar><i style="width:' + (100 - mnPct) + '%;background:linear-gradient(90deg,var(--violet),var(--blue))"></i></div></div>' +
          '</div>';
      }
      var mnCount = auditLiveMasternodes || d.activeMasternodes;
      var perMn = mnCount > 0 ? w.masternode / mnCount : null;
      return '<div class=rwCol>' +
        '<div class=rwHead><b>' + title + '</b><span>' + expT('rwBlocks', lang, { n: w.blocks.toLocaleString('en-US') }) + '</span></div>' +
        '<div class=rwTotal>' + fmtCoinAmt(w.total, cfg.unit) + '</div><div class=rwTotalLabel>' + pick(I18N.rwTotal, lang) + '</div>' +
        '<div class=rwRow><div class=rwRowHead><span>' + pick(I18N.kpiMasternodes, lang) + '</span><b>' + fmtCoinAmt(w.masternode, cfg.unit) + ' · ' + mnPct.toFixed(0) + '%</b></div><div class=rwBar><i style="width:' + mnPct + '%;background:linear-gradient(90deg,var(--green),var(--cyan))"></i></div></div>' +
        '<div class=rwRow><div class=rwRowHead><span>' + pick(I18N.rwStake, lang) + '</span><b>' + fmtCoinAmt(w.stake, cfg.unit) + ' · ' + (100 - mnPct).toFixed(0) + '%</b></div><div class=rwBar><i style="width:' + (100 - mnPct) + '%;background:linear-gradient(90deg,var(--violet),var(--blue))"></i></div></div>' +
        (perMn != null ? '<div class=rwPerMn><span>' + expT('rwPerMn', lang, { n: mnCount.toLocaleString('en-US') }) + '</span><b>' + fmtCoinAmt(perMn, cfg.unit) + '</b></div>' : '') +
        '</div>';
    };
    grid.innerHTML = col(pick(I18N.rwLast24h, lang), d.d1) + col(pick(I18N.rwLast30d, lang), d.d30);
    if(stakeOnly) setText('.auditKpiMn', fmtCoinAmt(d.d1.stake, cfg.unit));
    setText('.auditRewardsUpdatedEl', expT('rwUpdated', lang, { t: relTime(new Date(d.updatedAt).getTime(), lang) }));
    setText('.auditRewardsNoteEl', expT(cfg.note, lang, { v: d.blockValue, m: d.verification.matched, s: d.verification.sampled }));
  }).catch(function(){
    grid.innerHTML = '<p class=mini>' + pick(I18N.rwPending, lang) + '</p>';
  });
}

// ---- Mining coin (Bitcoin): the "Rewards generated" card shows the new coins of the last 24 hours
// and 30 days against the subsidy rule, the fees of the same blocks and the pace of the blocks; a
// third box brings the next difficulty adjustment and the next halving.
var POOL_UNKNOWN_I18N = {"en":"Unidentified pool","pt-BR":"Pool não identificado","es":"Pool no identificado","fr":"Pool non identifié","de":"Nicht identifizierter Pool","it":"Pool non identificato","ru":"Неопознанный пул","uk":"Невідомий пул","pl":"Niezidentyfikowana pula","vi":"Pool không xác định","ar":"مجمع غير معروف","bg":"Неидентифициран пул","cs":"Neidentifikovaný pool","da":"Uidentificeret pool","el":"Μη αναγνωρισμένο pool","fi":"Tunnistamaton pooli","he":"מאגר לא מזוהה","hi":"अज्ञात पूल","hr":"Neidentificirani pool","hu":"Azonosítatlan pool","id":"Pool tidak dikenal","ja":"不明なプール","ko":"알 수 없는 풀","lt":"Nenustatytas baseinas","nl":"Niet-geïdentificeerde pool","no":"Uidentifisert pool","ro":"Pool neidentificat","sk":"Neidentifikovaný pool","sl":"Neidentificiran bazen","sv":"Oidentifierad pool","th":"พูลที่ไม่ระบุ","tr":"Tanımlanamayan havuz","zh":"未识别矿池","zh-TW":"未識別礦池"};
function renderAuditMiningCard(cfg, r, lang){
  var grid = document.getElementById('auditRewardsGrid');
  if(!grid) return;
  var mg = r.mining;
  setText('.auditRewardsTitleEl', pick(I18N.rwTitle, lang));
  setText('.auditRewardsUpdatedEl', expT('rwUpdated', lang, { t: relTime(new Date(r.ts).getTime(), lang) }));
  if(!mg || (!mg.d1 && !mg.adjustment && !mg.halving && !(cfg.ethStake && r.stake) && !(cfg.bnbBurn && r.bnb))){ grid.innerHTML = '<p class=mini>' + escHtml(pick(I18N.rwPending, lang)) + '</p>'; setText('.auditRewardsNoteEl', ''); return; }
  setText('.auditRewardsNoteEl', pick(I18N[cfg.miningNote || 'miningNote'], lang).replace('{v}', r.blockSubsidy + ' ' + cfg.unit));
  var amt = function(v, d){ return Number(v).toLocaleString('en-US', { maximumFractionDigits: d == null ? 2 : d }) + ' ' + cfg.unit; };
  var num = function(v){ return Number(v).toLocaleString('en-US'); };
  var bar = function(pct, colors){ return '<div class=rwBar><i style="width:' + Math.max(0, Math.min(100, pct)) + '%;background:linear-gradient(90deg,' + colors + ')"></i></div>'; };
  var date = function(iso){ return new Date(iso).toLocaleDateString(lang); };
  var col = function(title, w){
    if(!w) return '<div class=rwCol><div class=rwHead><b>' + escHtml(title) + '</b></div><p class=mini>' + escHtml(pick(I18N.rwPending, lang)) + '</p></div>';
    var rulePct = w.byRule > 0 ? (w.minted / w.byRule) * 100 : 0;
    var feePct = w.fees != null && w.total > 0 ? (w.fees / w.total) * 100 : 0;
    return '<div class=rwCol>' +
      '<div class=rwHead><b>' + escHtml(title) + '</b><span>' + escHtml(expT('rwBlocks', lang, { n: num(w.blocks) })) + '</span></div>' +
      '<div class=rwTotal>' + amt(w.minted, cfg.amtDecimals || 8) + '</div><div class=rwTotalLabel>' + escHtml(pick(I18N[cfg.newCoinsLabel || 'miningNewCoins'], lang)) + '</div>' +
      '<div class=rwRow><div class=rwRowHead><span>' + escHtml(pick(I18N.kpiEmissionCap, lang)) + ' · ' + escHtml(pick(I18N.kpiEmissionCapSub, lang)) + '</span><b>' + amt(w.byRule, cfg.amtDecimals || 8) + ' · ' + rulePct.toFixed(2) + '%</b></div>' + bar(rulePct, 'var(--green),var(--cyan)') + '</div>' +
      (w.unlockFees != null ? '<div class=rwRow><div class=rwRowHead><span>' + escHtml(pick(I18N.miningUnlockFees, lang)) + '</span><b>' + amt(w.unlockFees, 8) + '</b></div></div>' : '') +
      (w.mweb != null ? '<div class=rwRow><div class=rwRowHead><span>' + escHtml(pick(I18N.miningMwebFees, lang)) + '</span><b>' + amt(w.mweb, 8) + '</b></div></div>' : '') +
      (w.fees != null ? '<div class=rwRow><div class=rwRowHead><span>' + escHtml(pick(I18N.miningFees, lang)) + '</span><b>' + amt(w.fees, 4) + ' · ' + feePct.toFixed(2) + '%</b></div>' + bar(feePct, 'var(--violet),var(--blue)') + '</div>' : '') +
      (w.burned != null ? '<div class=rwRow><div class=rwRowHead><span>' + escHtml(pick(I18N[cfg.burnedLabel || 'ethBurned'], lang)) + '</span><b>' + amt(w.burned, 4) + (w.minted > 0 ? ' · ' + (w.burned / w.minted * 100).toFixed(2) + '%' : '') + '</b></div>' + bar(w.minted > 0 ? w.burned / w.minted * 100 : 0, 'var(--amber),var(--red)') + '</div>' : '') +
      (w.net != null ? '<div class=rwPerMn><span>' + escHtml(pick(I18N.ethNet, lang)) + '</span><b>' + (w.net >= 0 ? '+' : '') + amt(w.net, 4) + '</b></div>' : '') +
      '<div class=rwPerMn><span>' + escHtml(pick(I18N.miningAvgBlock, lang)) + '</span><b>' + (cfg.blockSecs ? w.avgBlockSec.toFixed(2) + ' s' : (w.avgBlockSec / 60).toFixed(2) + ' min') + '</b></div>' +
      '</div>';
  };
  var extra = '';
  if(mg.adjustment || mg.halving){
    var a = mg.adjustment, hv = mg.halving;
    extra = '<div class="rwCol rwColWide">' +
      (a ? '<div class=rwPerMn><span>' + escHtml(pick(I18N.miningNextAdjust, lang)) + ' · #' + num(a.nextHeight) + '</span><b>' + (a.changePct >= 0 ? '+' : '') + a.changePct.toFixed(2) + '% · ' + escHtml(expT('rwBlocks', lang, { n: num(a.remainingBlocks) })) + ' · ' + date(a.estimatedAt) + '</b></div>' : '') +
      (hv ? '<div class=rwPerMn><span>' + escHtml(pick(I18N.miningNextHalving, lang)) + ' · #' + num(hv.height) + '</span><b>' + hv.subsidyNow + ' → ' + hv.subsidyNext + ' ' + cfg.unit + ' · ' + escHtml(expT('rwBlocks', lang, { n: num(hv.remainingBlocks) })) + ' · ≈ ' + date(hv.estimatedAt) + '</b></div>' : '') +
      '</div>';
  }
  if(cfg.ethStake && r.stake){
    extra += '<div class="rwCol rwColWide">' +
      '<div class=rwPerMn><span>' + escHtml(pick(I18N.ethStake, lang)) + '</span><b>≈ ' + amt(r.stake.activeStake, 0) + '</b></div>' +
      '<div class=rwPerMn><span>' + escHtml(pick(I18N.ethMaxEpoch, lang)) + '</span><b>' + amt(r.stake.maxPerEpoch, 4) + ' · ' + amt(r.stake.maxPerDay, 0) + ' / 24h</b></div>' +
      '</div>';
  }
  if(cfg.bnbBurn && r.bnb){
    var bx = r.bnb, nb = bx.blocks || {};
    var day = function(d){ return new Date(d + 'T12:00:00Z').toLocaleDateString(lang); };
    var row = function(label, value){ return '<div class=rwPerMn><span>' + label + '</span><b>' + value + '</b></div>'; };
    extra += '<div class="rwCol rwColWide">' +
      row(escHtml(pick(I18N.bnbBurnRatio, lang)), escHtml(pick(I18N.bnbBurnRatioVal, lang).replace('{p}', bx.burnRatioPct))) +
      row(escHtml(pick(I18N.bnbBlocksChecked, lang)) + ' · #' + num(nb.from) + '–' + num(nb.to), (nb.ok === nb.checked ? '✓ ' : '✗ ') + escHtml(pick(I18N.bnbBlocksVal, lang).replace('{ok}', num(nb.ok)).replace('{n}', num(nb.checked)).replace('{p}', bx.burnRatioPct))) +
      row(escHtml(pick(I18N.bnbBurnedTotal, lang)), amt(bx.burnedTotal, 2)) +
      row(escHtml(pick(I18N.auditValidatorsLabel, lang)), num(bx.validators)) +
      (bx.quarterly || []).slice(0, 3).map(function(q){
        return row(escHtml(pick(I18N.bnbQuarter, lang).replace('{q}', q.name)) + ' · ' + day(q.date),
          '<a href="https://bscscan.com/tx/' + escHtml(q.tx) + '" target=_blank rel=noopener style="color:inherit">' + amt(q.amount, 2) + '</a> · ' + (q.matches ? '✓ ' + escHtml(pick(I18N.bnbOnChain, lang)) : '≠ ' + escHtml(pick(I18N.bnbOnChainDiff, lang).replace('{v}', amt(q.onChain, 3)))));
      }).join('') +
      (bx.nextBurn ? row(escHtml(pick(I18N.bnbNextBurn, lang).replace('{q}', bx.nextBurn.name)), '≈ ' + amt(bx.nextBurn.amount, 0)) : '') +
      '</div>';
  }
  grid.innerHTML = col(pick(I18N.rwLast24h, lang), mg && mg.d1) + col(pick(I18N.rwLast30d, lang), mg && mg.d30) + extra;
}

// ---- Proof-of-stake network without masternodes (Solana): the "Rewards generated" card shows the
// SOL created at the last epoch boundary against the most the inflation rule allowed, and the stake
// behind it -- validators, SOL staked, share of the supply and the yield that follows from both.
function renderAuditStakeCard(cfg, r, lang){
  var grid = document.getElementById('auditRewardsGrid');
  if(!grid) return;
  setText('.auditRewardsTitleEl', pick(I18N.rwTitle, lang));
  setText('.auditRewardsUpdatedEl', expT('rwUpdated', lang, { t: relTime(new Date(r.ts).getTime(), lang) }));
  setText('.auditRewardsNoteEl', pick(I18N.rwNoteSol, lang));
  var amt = function(v, d){ return Number(v).toLocaleString('en-US', { maximumFractionDigits: d == null ? 2 : d }) + ' ' + cfg.unit; };
  var bar = function(pct, colors){ return '<div class=rwBar><i style="width:' + Math.max(0, Math.min(100, pct)) + '%;background:linear-gradient(90deg,' + colors + ')"></i></div>'; };
  var er = r.epochRewards, st = r.stake;
  var rewardsCol = er
    ? '<div class=rwCol>' +
        '<div class=rwHead><b>' + escHtml(pick(I18N.auditEpochSub, lang).replace('{n}', Number(er.epoch).toLocaleString('en-US'))) + '</b><span>' + (er.withinRule ? '✓ ' : '') + escHtml(pick(I18N.kpiEmissionCapSub, lang)) + '</span></div>' +
        '<div class=rwTotal>' + amt(er.total) + '</div><div class=rwTotalLabel>' + escHtml(pick(I18N.rwTotal, lang)) + '</div>' +
        '<div class=rwRow><div class=rwRowHead><span>' + escHtml(pick(I18N.kpiEmissionCap, lang)) + '</span><b>' + amt(er.maxByRule) + ' · ' + Number(er.pctOfRule).toFixed(2) + '%</b></div>' + bar(er.pctOfRule, 'var(--green),var(--cyan)') + '</div>' +
      '</div>'
    : '<div class=rwCol><p class=mini>' + escHtml(pick(I18N.rwPending, lang)) + '</p></div>';
  var stakeCol = st
    ? '<div class=rwCol>' +
        '<div class=rwHead><b>' + escHtml(pick(I18N.rwStake, lang)) + '</b><span>' + escHtml(pick(I18N.auditValidatorsLabel, lang)) + ': ' + Number(st.validatorsActive).toLocaleString('en-US') + ' · ' + escHtml(pick(I18N.auditOfflineTemplate, lang).replace('{n}', st.validatorsDelinquent)) + '</span></div>' +
        '<div class=rwTotal>' + amt(st.activeStake, 0) + '</div><div class=rwTotalLabel>' + escHtml(pick(I18N.rwStake, lang)) + '</div>' +
        '<div class=rwRow><div class=rwRowHead><span>' + escHtml(pick(I18N.kpiTotalSupply, lang)) + '</span><b>' + Number(st.stakedPct).toFixed(2) + '%</b></div>' + bar(st.stakedPct, 'var(--violet),var(--blue)') + '</div>' +
        '<div class=rwPerMn><span>' + escHtml(pick(I18N.auditYieldLabel, lang)) + '</span><b>' + Number(st.yieldPct).toFixed(2) + '%</b></div>' +
      '</div>'
    : '<div class=rwCol><p class=mini>' + escHtml(pick(I18N.rwPending, lang)) + '</p></div>';
  grid.innerHTML = rewardsCol + stakeCol;
}

// ---- Token audit (XLNFT): contract, liquidity and activity card, largest wallets. Texts by index, 34
// languages (see the list at the top of TK_I18N's source); I18N.tk<n> are the same texts by name.
var TK_I18N = {"en":["Contract","Code identical to the published source","Code differs from the published source","Owner","Ownership renounced","Tokens created after deployment","Burned","Liquidity","PancakeSwap pool","Liquidity tokens locked on PinkLock","Unlocks on {d}","Activity","Wallets holding XLNFT","Transfers today (UTC)","Transfers · 7 days","Transfers · 30 days","Transfers since deployment","Reading the transfer history… {p}%","Largest wallets","Share of the total supply · {h} wallets","Owner wallet","Token contract","fixed in the contract","Read straight from BNB Chain: the token contract, the PancakeSwap pool and the PinkLock locker. Updated every 20 minutes.","Holders","Top 10: {p}%","Each check reads the token straight from BNB Chain. The code running at the contract address is byte for byte the code compiled from the source published on BscScan (Solidity 0.8.19, optimizer 200, EVM paris), and that code has no function that creates tokens. All 100,000,000 XLNFT were created when the contract was deployed on {d} (block {blk}); the total can only go down, through burn or burnFrom — burned so far: {burn} XLNFT. The owner ({own}) can only transfer or renounce ownership and recover tokens sent to the contract address by mistake: the code has no fee, blacklist, pause or forced transfer. The owner’s wallet holds {op}% of the supply. {lp}% of the liquidity tokens of the PancakeSwap pool are locked on PinkLock until {u}.","Replaying all {n} transfers since the deployment, {h} wallets hold XLNFT, their balances add up exactly to the total supply and no token was created after the deployment.","Contract, liquidity and activity","Price in the pool","Burn address"],"ru":["Контракт","Код идентичен опубликованному исходному коду","Код отличается от опубликованного исходного кода","Владелец","Владение отозвано","Токены, созданные после развёртывания","Сожжено","Ликвидность","Пул PancakeSwap","Токены ликвидности заблокированы в PinkLock","Разблокировка {d}","Активность","Кошельки с XLNFT","Переводы сегодня (UTC)","Переводы · 7 дней","Переводы · 30 дней","Переводы с момента развёртывания","Чтение истории переводов… {p}%","Крупнейшие кошельки","Доля от общего предложения · {h} кошельков","Кошелёк владельца","Контракт токена","зафиксировано в контракте","Данные считываются напрямую из BNB Chain: контракт токена, пул PancakeSwap и локер PinkLock. Обновляется каждые 20 минут.","Держатели","Топ-10: {p}%","При каждой проверке токен считывается напрямую из BNB Chain. Код, работающий по адресу контракта, байт в байт совпадает с кодом, скомпилированным из исходника, опубликованного на BscScan (Solidity 0.8.19, optimizer 200, EVM paris), и в этом коде нет функции, создающей токены. Все 100 000 000 XLNFT были созданы при развёртывании контракта {d} (блок {blk}); общее количество может только уменьшаться через burn или burnFrom — сожжено на данный момент: {burn} XLNFT. Владелец ({own}) может только передать владение или отказаться от него и вернуть токены, по ошибке отправленные на адрес контракта: в коде нет комиссии, чёрного списка, паузы или принудительного перевода. В кошельке владельца находится {op}% предложения. {lp}% токенов ликвидности пула PancakeSwap заблокированы в PinkLock до {u}.","Если воспроизвести все {n} переводов с момента развёртывания, XLNFT хранятся в {h} кошельках, их балансы в сумме точно равны общему предложению, и ни один токен не был создан после развёртывания.","Контракт, ликвидность и активность","Цена в пуле","Адрес сжигания"],"de":["Vertrag","Code identisch mit dem veröffentlichten Quellcode","Code weicht vom veröffentlichten Quellcode ab","Eigentümer","Eigentum aufgegeben","Nach dem Deployment erzeugte Token","Verbrannt","Liquidität","PancakeSwap-Pool","Liquiditätstoken auf PinkLock gesperrt","Entsperrung am {d}","Aktivität","Wallets mit XLNFT","Transfers heute (UTC)","Transfers · 7 Tage","Transfers · 30 Tage","Transfers seit dem Deployment","Transferverlauf wird gelesen… {p}%","Größte Wallets","Anteil an der Gesamtmenge · {h} Wallets","Wallet des Eigentümers","Token-Vertrag","im Vertrag festgelegt","Direkt aus der BNB Chain gelesen: Token-Vertrag, PancakeSwap-Pool und PinkLock-Locker. Aktualisierung alle 20 Minuten.","Halter","Top 10: {p}%","Bei jeder Prüfung wird der Token direkt aus der BNB Chain gelesen. Der Code an der Vertragsadresse ist Byte für Byte der Code, der aus dem auf BscScan veröffentlichten Quellcode kompiliert wird (Solidity 0.8.19, Optimizer 200, EVM paris), und dieser Code hat keine Funktion, die Token erzeugt. Alle 100.000.000 XLNFT wurden beim Deployment des Vertrags am {d} (Block {blk}) erzeugt; die Gesamtmenge kann nur sinken, über burn oder burnFrom — bisher verbrannt: {burn} XLNFT. Der Eigentümer ({own}) kann nur das Eigentum übertragen oder aufgeben und versehentlich an die Vertragsadresse gesendete Token zurückholen: Der Code hat keine Gebühr, keine Blacklist, keine Pause und keinen erzwungenen Transfer. Die Wallet des Eigentümers hält {op}% der Gesamtmenge. {lp}% der Liquiditätstoken des PancakeSwap-Pools sind bis {u} auf PinkLock gesperrt.","Werden alle {n} Transfers seit dem Deployment nachvollzogen, halten {h} Wallets XLNFT, ihre Salden ergeben genau die Gesamtmenge und nach dem Deployment wurde kein Token erzeugt.","Vertrag, Liquidität und Aktivität","Preis im Pool","Burn-Adresse"],"pl":["Kontrakt","Kod identyczny z opublikowanym kodem źródłowym","Kod różni się od opublikowanego kodu źródłowego","Właściciel","Własność zrzeczona","Tokeny utworzone po wdrożeniu","Spalone","Płynność","Pula PancakeSwap","Tokeny płynności zablokowane w PinkLock","Odblokowanie {d}","Aktywność","Portfele z XLNFT","Transfery dziś (UTC)","Transfery · 7 dni","Transfery · 30 dni","Transfery od wdrożenia","Odczyt historii transferów… {p}%","Największe portfele","Udział w całkowitej podaży · {h} portfeli","Portfel właściciela","Kontrakt tokena","ustalone w kontrakcie","Odczytywane bezpośrednio z BNB Chain: kontrakt tokena, pula PancakeSwap i locker PinkLock. Aktualizacja co 20 minut.","Posiadacze","Top 10: {p}%","Każde sprawdzenie odczytuje token bezpośrednio z BNB Chain. Kod działający pod adresem kontraktu jest bajt w bajt kodem skompilowanym z kodu źródłowego opublikowanego na BscScan (Solidity 0.8.19, optimizer 200, EVM paris), a ten kod nie ma funkcji tworzącej tokeny. Wszystkie 100 000 000 XLNFT zostały utworzone przy wdrożeniu kontraktu {d} (blok {blk}); całkowita liczba może tylko maleć, przez burn lub burnFrom — dotąd spalono: {burn} XLNFT. Właściciel ({own}) może jedynie przekazać własność lub się jej zrzec oraz odzyskać tokeny wysłane omyłkowo na adres kontraktu: kod nie ma opłat, czarnej listy, pauzy ani wymuszonego transferu. Portfel właściciela posiada {op}% podaży. {lp}% tokenów płynności puli PancakeSwap jest zablokowanych w PinkLock do {u}.","Po odtworzeniu wszystkich {n} transferów od wdrożenia XLNFT posiada {h} portfeli, ich salda sumują się dokładnie do całkowitej podaży i po wdrożeniu nie utworzono żadnego tokena.","Kontrakt, płynność i aktywność","Cena w puli","Adres spalania"],"es":["Contrato","Código idéntico al código fuente publicado","El código difiere del código fuente publicado","Propietario","Propiedad renunciada","Tokens creados después del despliegue","Quemados","Liquidez","Pool de PancakeSwap","Tokens de liquidez bloqueados en PinkLock","Se desbloquean el {d}","Actividad","Billeteras con XLNFT","Transferencias hoy (UTC)","Transferencias · 7 días","Transferencias · 30 días","Transferencias desde el despliegue","Leyendo el historial de transferencias… {p}%","Billeteras más grandes","Parte del suministro total · {h} billeteras","Billetera del propietario","Contrato del token","fijado en el contrato","Leído directamente de BNB Chain: el contrato del token, el pool de PancakeSwap y el bloqueo de PinkLock. Se actualiza cada 20 minutos.","Titulares","Top 10: {p}%","Cada verificación lee el token directamente de BNB Chain. El código que se ejecuta en la dirección del contrato es, byte por byte, el código compilado a partir del código fuente publicado en BscScan (Solidity 0.8.19, optimizer 200, EVM paris), y ese código no tiene ninguna función que cree tokens. Los 100.000.000 XLNFT se crearon al desplegar el contrato el {d} (bloque {blk}); el total solo puede bajar, mediante burn o burnFrom — quemados hasta ahora: {burn} XLNFT. El propietario ({own}) solo puede transferir o renunciar a la propiedad y recuperar tokens enviados por error a la dirección del contrato: el código no tiene comisión, lista negra, pausa ni transferencia forzada. La billetera del propietario tiene el {op}% del suministro. El {lp}% de los tokens de liquidez del pool de PancakeSwap está bloqueado en PinkLock hasta el {u}.","Al reproducir las {n} transferencias desde el despliegue, {h} billeteras tienen XLNFT, sus saldos suman exactamente el suministro total y no se creó ningún token después del despliegue.","Contrato, liquidez y actividad","Precio en el pool","Dirección de quema"],"vi":["Hợp đồng","Mã giống hệt mã nguồn đã công bố","Mã khác với mã nguồn đã công bố","Chủ sở hữu","Đã từ bỏ quyền sở hữu","Token được tạo sau khi triển khai","Đã đốt","Thanh khoản","Pool PancakeSwap","Token thanh khoản bị khóa trên PinkLock","Mở khóa ngày {d}","Hoạt động","Ví đang giữ XLNFT","Giao dịch chuyển hôm nay (UTC)","Giao dịch chuyển · 7 ngày","Giao dịch chuyển · 30 ngày","Giao dịch chuyển từ khi triển khai","Đang đọc lịch sử giao dịch chuyển… {p}%","Ví lớn nhất","Tỷ lệ trên tổng cung · {h} ví","Ví chủ sở hữu","Hợp đồng token","cố định trong hợp đồng","Đọc trực tiếp từ BNB Chain: hợp đồng token, pool PancakeSwap và khóa PinkLock. Cập nhật mỗi 20 phút.","Người nắm giữ","Top 10: {p}%","Mỗi lần kiểm tra đọc token trực tiếp từ BNB Chain. Mã đang chạy tại địa chỉ hợp đồng giống từng byte với mã được biên dịch từ mã nguồn công bố trên BscScan (Solidity 0.8.19, optimizer 200, EVM paris), và mã đó không có hàm nào tạo token. Toàn bộ 100.000.000 XLNFT được tạo khi triển khai hợp đồng ngày {d} (khối {blk}); tổng số chỉ có thể giảm, qua burn hoặc burnFrom — đã đốt đến nay: {burn} XLNFT. Chủ sở hữu ({own}) chỉ có thể chuyển giao hoặc từ bỏ quyền sở hữu và lấy lại token bị gửi nhầm vào địa chỉ hợp đồng: mã không có phí, danh sách đen, tạm dừng hay chuyển cưỡng bức. Ví của chủ sở hữu giữ {op}% tổng cung. {lp}% token thanh khoản của pool PancakeSwap bị khóa trên PinkLock đến {u}.","Khi phát lại toàn bộ {n} giao dịch chuyển từ khi triển khai, có {h} ví giữ XLNFT, tổng số dư của chúng đúng bằng tổng cung và không có token nào được tạo sau khi triển khai.","Hợp đồng, thanh khoản và hoạt động","Giá trong pool","Địa chỉ đốt"],"fr":["Contrat","Code identique au code source publié","Le code diffère du code source publié","Propriétaire","Propriété abandonnée","Jetons créés après le déploiement","Brûlés","Liquidité","Pool PancakeSwap","Jetons de liquidité verrouillés sur PinkLock","Déverrouillage le {d}","Activité","Portefeuilles détenant des XLNFT","Transferts aujourd’hui (UTC)","Transferts · 7 jours","Transferts · 30 jours","Transferts depuis le déploiement","Lecture de l’historique des transferts… {p}%","Plus grands portefeuilles","Part de l’offre totale · {h} portefeuilles","Portefeuille du propriétaire","Contrat du jeton","fixé dans le contrat","Lu directement sur BNB Chain : le contrat du jeton, le pool PancakeSwap et le verrou PinkLock. Mis à jour toutes les 20 minutes.","Détenteurs","Top 10 : {p}%","Chaque contrôle lit le jeton directement sur BNB Chain. Le code exécuté à l’adresse du contrat est, octet pour octet, le code compilé à partir du code source publié sur BscScan (Solidity 0.8.19, optimizer 200, EVM paris), et ce code n’a aucune fonction qui crée des jetons. Les 100 000 000 XLNFT ont tous été créés au déploiement du contrat le {d} (bloc {blk}) ; le total ne peut que baisser, par burn ou burnFrom — brûlés à ce jour : {burn} XLNFT. Le propriétaire ({own}) peut seulement transférer ou abandonner la propriété et récupérer des jetons envoyés par erreur à l’adresse du contrat : le code n’a ni frais, ni liste noire, ni pause, ni transfert forcé. Le portefeuille du propriétaire détient {op} % de l’offre. {lp} % des jetons de liquidité du pool PancakeSwap sont verrouillés sur PinkLock jusqu’au {u}.","En rejouant les {n} transferts depuis le déploiement, {h} portefeuilles détiennent des XLNFT, leurs soldes font exactement l’offre totale et aucun jeton n’a été créé après le déploiement.","Contrat, liquidité et activité","Prix dans le pool","Adresse de burn"],"pt-BR":["Contrato","Código idêntico ao código-fonte publicado","Código diferente do código-fonte publicado","Dono","Propriedade renunciada","Tokens criados depois da implantação","Queimados","Liquidez","Pool da PancakeSwap","Tokens de liquidez travados na PinkLock","Destrava em {d}","Atividade","Carteiras com XLNFT","Transferências hoje (UTC)","Transferências · 7 dias","Transferências · 30 dias","Transferências desde a implantação","Lendo o histórico de transferências… {p}%","Maiores carteiras","Parte do supply total · {h} carteiras","Carteira do dono","Contrato do token","fixo no contrato","Lido direto da BNB Chain: o contrato do token, o pool da PancakeSwap e a trava da PinkLock. Atualizado a cada 20 minutos.","Carteiras","Top 10: {p}%","A cada checagem lemos o token direto da BNB Chain. O código que roda no endereço do contrato é, byte a byte, o código compilado a partir do código-fonte publicado no BscScan (Solidity 0.8.19, optimizer 200, EVM paris), e esse código não tem nenhuma função que crie tokens. Os 100.000.000 de XLNFT foram todos criados na implantação do contrato em {d} (bloco {blk}); o total só pode diminuir, por burn ou burnFrom — queimados até agora: {burn} XLNFT. O dono ({own}) só pode transferir ou renunciar à propriedade e resgatar tokens enviados por engano ao endereço do contrato: o código não tem taxa, lista negra, pausa nem transferência forçada. A carteira do dono guarda {op}% do supply. {lp}% dos tokens de liquidez do pool da PancakeSwap estão travados na PinkLock até {u}.","Refazendo todas as {n} transferências desde a implantação, {h} carteiras têm XLNFT, a soma dos saldos é exatamente o supply total e nenhum token foi criado depois da implantação.","Contrato, liquidez e atividade","Preço no pool","Endereço de queima"],"ar":["العقد","الكود مطابق للكود المصدري المنشور","الكود يختلف عن الكود المصدري المنشور","المالك","تم التخلي عن الملكية","رموز أُنشئت بعد النشر","المحروقة","السيولة","مجمع PancakeSwap","رموز السيولة مقفلة على PinkLock","يُفتح القفل في {d}","النشاط","المحافظ التي تحمل XLNFT","التحويلات اليوم (UTC)","التحويلات · 7 أيام","التحويلات · 30 يومًا","التحويلات منذ النشر","جارٍ قراءة سجل التحويلات… {p}%","أكبر المحافظ","الحصة من إجمالي المعروض · {h} محفظة","محفظة المالك","عقد الرمز","ثابت في العقد","تُقرأ مباشرة من BNB Chain: عقد الرمز ومجمع PancakeSwap وقفل PinkLock. يُحدَّث كل 20 دقيقة.","الحاملون","أكبر 10: {p}%","في كل فحص نقرأ الرمز مباشرة من BNB Chain. الكود الذي يعمل على عنوان العقد مطابق بايتًا ببايت للكود المُترجم من الكود المصدري المنشور على BscScan ‏(Solidity 0.8.19، optimizer 200، EVM paris)، ولا يحتوي هذا الكود على أي دالة تُنشئ رموزًا. أُنشئت كل الـ 100,000,000 XLNFT عند نشر العقد في {d} (الكتلة {blk})؛ ولا يمكن للإجمالي إلا أن ينخفض عبر burn أو burnFrom — المحروق حتى الآن: {burn} XLNFT. لا يستطيع المالك ({own}) سوى نقل الملكية أو التخلي عنها واسترداد الرموز المرسلة بالخطأ إلى عنوان العقد: لا يحتوي الكود على رسوم أو قائمة سوداء أو إيقاف مؤقت أو تحويل قسري. تحتفظ محفظة المالك بـ {op}% من المعروض. ‏{lp}% من رموز سيولة مجمع PancakeSwap مقفلة على PinkLock حتى {u}.","عند إعادة تشغيل كل التحويلات البالغة {n} منذ النشر، توجد {h} محفظة تحمل XLNFT، ومجموع أرصدتها يساوي إجمالي المعروض تمامًا، ولم يُنشأ أي رمز بعد النشر.","العقد والسيولة والنشاط","السعر في المجمع","عنوان الحرق"],"bg":["Договор","Кодът е идентичен с публикувания изходен код","Кодът се различава от публикувания изходен код","Собственик","Собствеността е отказана","Токени, създадени след внедряването","Изгорени","Ликвидност","Пул в PancakeSwap","Токени за ликвидност, заключени в PinkLock","Отключване на {d}","Активност","Портфейли с XLNFT","Преводи днес (UTC)","Преводи · 7 дни","Преводи · 30 дни","Преводи от внедряването","Четене на историята на преводите… {p}%","Най-големи портфейли","Дял от общото предлагане · {h} портфейла","Портфейл на собственика","Договор на токена","фиксирано в договора","Чете се директно от BNB Chain: договорът на токена, пулът в PancakeSwap и заключването в PinkLock. Обновява се на всеки 20 минути.","Притежатели","Топ 10: {p}%","При всяка проверка токенът се чете директно от BNB Chain. Кодът на адреса на договора е байт по байт кодът, компилиран от изходния код, публикуван в BscScan (Solidity 0.8.19, optimizer 200, EVM paris), и в този код няма функция, която създава токени. Всички 100 000 000 XLNFT са създадени при внедряването на договора на {d} (блок {blk}); общото количество може само да намалява чрез burn или burnFrom — изгорени досега: {burn} XLNFT. Собственикът ({own}) може само да прехвърли или да се откаже от собствеността и да върне токени, изпратени по грешка на адреса на договора: в кода няма такса, черен списък, пауза или принудителен превод. Портфейлът на собственика държи {op}% от предлагането. {lp}% от токените за ликвидност на пула в PancakeSwap са заключени в PinkLock до {u}.","При възпроизвеждане на всички {n} превода от внедряването XLNFT държат {h} портфейла, сборът от салдата им е точно общото предлагане и след внедряването не е създаден нито един токен.","Договор, ликвидност и активност","Цена в пула","Адрес за изгаряне"],"cs":["Kontrakt","Kód shodný se zveřejněným zdrojovým kódem","Kód se liší od zveřejněného zdrojového kódu","Vlastník","Vlastnictví zřeknuto","Tokeny vytvořené po nasazení","Spálené","Likvidita","Pool PancakeSwap","Tokeny likvidity uzamčené v PinkLock","Odemčení {d}","Aktivita","Peněženky s XLNFT","Převody dnes (UTC)","Převody · 7 dní","Převody · 30 dní","Převody od nasazení","Načítání historie převodů… {p}%","Největší peněženky","Podíl na celkové nabídce · {h} peněženek","Peněženka vlastníka","Kontrakt tokenu","pevně dané v kontraktu","Načítáno přímo z BNB Chain: kontrakt tokenu, pool PancakeSwap a zámek PinkLock. Aktualizuje se každých 20 minut.","Držitelé","Top 10: {p}%","Každá kontrola čte token přímo z BNB Chain. Kód běžící na adrese kontraktu je bajt po bajtu kód zkompilovaný ze zdrojového kódu zveřejněného na BscScan (Solidity 0.8.19, optimizer 200, EVM paris) a tento kód nemá žádnou funkci, která vytváří tokeny. Všech 100 000 000 XLNFT vzniklo při nasazení kontraktu {d} (blok {blk}); celkové množství může jen klesat, přes burn nebo burnFrom — dosud spáleno: {burn} XLNFT. Vlastník ({own}) může pouze převést vlastnictví nebo se ho vzdát a vrátit tokeny omylem poslané na adresu kontraktu: kód nemá poplatek, černou listinu, pauzu ani vynucený převod. Peněženka vlastníka drží {op} % nabídky. {lp} % tokenů likvidity poolu PancakeSwap je uzamčeno v PinkLock do {u}.","Po přehrání všech {n} převodů od nasazení drží XLNFT {h} peněženek, jejich zůstatky dávají přesně celkovou nabídku a po nasazení nevznikl žádný token.","Kontrakt, likvidita a aktivita","Cena v poolu","Adresa pro pálení"],"da":["Kontrakt","Koden er identisk med den offentliggjorte kildekode","Koden afviger fra den offentliggjorte kildekode","Ejer","Ejerskab opgivet","Tokens oprettet efter udrulningen","Brændt","Likviditet","PancakeSwap-pool","Likviditetstokens låst på PinkLock","Låses op den {d}","Aktivitet","Wallets med XLNFT","Overførsler i dag (UTC)","Overførsler · 7 dage","Overførsler · 30 dage","Overførsler siden udrulningen","Læser overførselshistorikken… {p}%","Største wallets","Andel af det samlede udbud · {h} wallets","Ejerens wallet","Tokenkontrakt","fastsat i kontrakten","Læst direkte fra BNB Chain: tokenkontrakten, PancakeSwap-poolen og PinkLock-låsen. Opdateres hvert 20. minut.","Indehavere","Top 10: {p}%","Hver kontrol læser tokenet direkte fra BNB Chain. Koden på kontraktadressen er byte for byte den kode, der kompileres fra kildekoden offentliggjort på BscScan (Solidity 0.8.19, optimizer 200, EVM paris), og den kode har ingen funktion, der opretter tokens. Alle 100.000.000 XLNFT blev oprettet, da kontrakten blev udrullet den {d} (blok {blk}); det samlede antal kan kun falde, via burn eller burnFrom — brændt indtil videre: {burn} XLNFT. Ejeren ({own}) kan kun overdrage eller opgive ejerskabet og hente tokens, der ved en fejl er sendt til kontraktadressen: koden har intet gebyr, ingen sortliste, ingen pause og ingen tvungen overførsel. Ejerens wallet har {op} % af udbuddet. {lp} % af likviditetstokens i PancakeSwap-poolen er låst på PinkLock indtil {u}.","Når alle {n} overførsler siden udrulningen genafspilles, har {h} wallets XLNFT, deres saldi giver præcis det samlede udbud, og intet token blev oprettet efter udrulningen.","Kontrakt, likviditet og aktivitet","Pris i poolen","Brændingsadresse"],"el":["Συμβόλαιο","Ο κώδικας είναι ίδιος με τον δημοσιευμένο πηγαίο κώδικα","Ο κώδικας διαφέρει από τον δημοσιευμένο πηγαίο κώδικα","Ιδιοκτήτης","Η ιδιοκτησία παραιτήθηκε","Tokens που δημιουργήθηκαν μετά την ανάπτυξη","Καμένα","Ρευστότητα","Pool του PancakeSwap","Tokens ρευστότητας κλειδωμένα στο PinkLock","Ξεκλείδωμα στις {d}","Δραστηριότητα","Πορτοφόλια με XLNFT","Μεταφορές σήμερα (UTC)","Μεταφορές · 7 ημέρες","Μεταφορές · 30 ημέρες","Μεταφορές από την ανάπτυξη","Ανάγνωση ιστορικού μεταφορών… {p}%","Μεγαλύτερα πορτοφόλια","Μερίδιο της συνολικής προσφοράς · {h} πορτοφόλια","Πορτοφόλι ιδιοκτήτη","Συμβόλαιο του token","σταθερό στο συμβόλαιο","Διαβάζεται απευθείας από το BNB Chain: το συμβόλαιο του token, το pool του PancakeSwap και το κλείδωμα του PinkLock. Ενημερώνεται κάθε 20 λεπτά.","Κάτοχοι","Top 10: {p}%","Σε κάθε έλεγχο διαβάζουμε το token απευθείας από το BNB Chain. Ο κώδικας στη διεύθυνση του συμβολαίου είναι, byte προς byte, ο κώδικας που μεταγλωττίζεται από τον πηγαίο κώδικα που δημοσιεύτηκε στο BscScan (Solidity 0.8.19, optimizer 200, EVM paris), και αυτός ο κώδικας δεν έχει καμία συνάρτηση που δημιουργεί tokens. Και τα 100.000.000 XLNFT δημιουργήθηκαν κατά την ανάπτυξη του συμβολαίου στις {d} (μπλοκ {blk})· το σύνολο μπορεί μόνο να μειωθεί, μέσω burn ή burnFrom — καμένα έως τώρα: {burn} XLNFT. Ο ιδιοκτήτης ({own}) μπορεί μόνο να μεταβιβάσει ή να παραιτηθεί από την ιδιοκτησία και να ανακτήσει tokens που στάλθηκαν κατά λάθος στη διεύθυνση του συμβολαίου: ο κώδικας δεν έχει προμήθεια, μαύρη λίστα, παύση ή αναγκαστική μεταφορά. Το πορτοφόλι του ιδιοκτήτη κατέχει το {op}% της προσφοράς. Το {lp}% των tokens ρευστότητας του pool του PancakeSwap είναι κλειδωμένο στο PinkLock έως τις {u}.","Αναπαράγοντας και τις {n} μεταφορές από την ανάπτυξη, {h} πορτοφόλια κατέχουν XLNFT, τα υπόλοιπά τους αθροίζουν ακριβώς τη συνολική προσφορά και κανένα token δεν δημιουργήθηκε μετά την ανάπτυξη.","Συμβόλαιο, ρευστότητα και δραστηριότητα","Τιμή στο pool","Διεύθυνση καύσης"],"fi":["Sopimus","Koodi on sama kuin julkaistu lähdekoodi","Koodi poikkeaa julkaistusta lähdekoodista","Omistaja","Omistajuudesta luovuttu","Käyttöönoton jälkeen luodut tokenit","Poltetut","Likviditeetti","PancakeSwap-pooli","Likviditeettitokenit lukittu PinkLockiin","Lukitus päättyy {d}","Aktiivisuus","XLNFT:tä omistavat lompakot","Siirrot tänään (UTC)","Siirrot · 7 päivää","Siirrot · 30 päivää","Siirrot käyttöönoton jälkeen","Luetaan siirtohistoriaa… {p}%","Suurimmat lompakot","Osuus kokonaistarjonnasta · {h} lompakkoa","Omistajan lompakko","Tokenin sopimus","kiinteä sopimuksessa","Luettu suoraan BNB Chainista: tokenin sopimus, PancakeSwap-pooli ja PinkLock-lukitus. Päivittyy 20 minuutin välein.","Haltijat","Top 10: {p}%","Jokainen tarkistus lukee tokenin suoraan BNB Chainista. Sopimusosoitteessa ajettava koodi on tavu tavulta sama koodi, joka käännetään BscScanissa julkaistusta lähdekoodista (Solidity 0.8.19, optimizer 200, EVM paris), eikä siinä koodissa ole yhtään tokeneita luovaa funktiota. Kaikki 100 000 000 XLNFT:tä luotiin, kun sopimus otettiin käyttöön {d} (lohko {blk}); kokonaismäärä voi vain pienentyä, burnilla tai burnFromilla — tähän mennessä poltettu: {burn} XLNFT. Omistaja ({own}) voi vain siirtää omistajuuden tai luopua siitä ja palauttaa sopimusosoitteeseen vahingossa lähetetyt tokenit: koodissa ei ole maksua, mustaa listaa, taukoa eikä pakotettua siirtoa. Omistajan lompakossa on {op} % tarjonnasta. {lp} % PancakeSwap-poolin likviditeettitokeneista on lukittu PinkLockiin {u} asti.","Kun kaikki {n} siirtoa käyttöönotosta toistetaan, XLNFT:tä on {h} lompakossa, niiden saldot ovat yhteensä täsmälleen kokonaistarjonta, eikä yhtään tokenia luotu käyttöönoton jälkeen.","Sopimus, likviditeetti ja aktiivisuus","Hinta poolissa","Poltto-osoite"],"he":["חוזה","הקוד זהה לקוד המקור שפורסם","הקוד שונה מקוד המקור שפורסם","בעלים","הבעלות בוטלה","טוקנים שנוצרו אחרי הפריסה","נשרפו","נזילות","מאגר PancakeSwap","טוקני נזילות נעולים ב-PinkLock","נפתח ב-{d}","פעילות","ארנקים שמחזיקים XLNFT","העברות היום (UTC)","העברות · 7 ימים","העברות · 30 ימים","העברות מאז הפריסה","קורא את היסטוריית ההעברות… {p}%","הארנקים הגדולים","חלק מההיצע הכולל · {h} ארנקים","ארנק הבעלים","חוזה הטוקן","קבוע בחוזה","נקרא ישירות מ-BNB Chain: חוזה הטוקן, מאגר PancakeSwap ונעילת PinkLock. מתעדכן כל 20 דקות.","מחזיקים","טופ 10: {p}%","בכל בדיקה אנו קוראים את הטוקן ישירות מ-BNB Chain. הקוד שרץ בכתובת החוזה זהה, בייט אחר בייט, לקוד שמקומפל מקוד המקור שפורסם ב-BscScan ‏(Solidity 0.8.19, optimizer 200, EVM paris), ובקוד הזה אין שום פונקציה שיוצרת טוקנים. כל 100,000,000 ה-XLNFT נוצרו בפריסת החוזה ב-{d} (בלוק {blk}); הסך הכולל יכול רק לרדת, דרך burn או burnFrom — נשרפו עד כה: {burn} XLNFT. הבעלים ({own}) יכול רק להעביר את הבעלות או לוותר עליה ולהשיב טוקנים שנשלחו בטעות לכתובת החוזה: בקוד אין עמלה, רשימה שחורה, השהיה או העברה כפויה. ארנק הבעלים מחזיק {op}% מההיצע. ‏{lp}% מטוקני הנזילות של מאגר PancakeSwap נעולים ב-PinkLock עד {u}.","בשחזור כל {n} ההעברות מאז הפריסה, {h} ארנקים מחזיקים XLNFT, סכום היתרות שלהם שווה בדיוק להיצע הכולל ולא נוצר אף טוקן אחרי הפריסה.","חוזה, נזילות ופעילות","מחיר במאגר","כתובת שריפה"],"hi":["कॉन्ट्रैक्ट","कोड प्रकाशित सोर्स कोड जैसा ही है","कोड प्रकाशित सोर्स कोड से अलग है","मालिक","स्वामित्व छोड़ दिया गया","डिप्लॉयमेंट के बाद बने टोकन","बर्न किए गए","लिक्विडिटी","PancakeSwap पूल","PinkLock पर लॉक लिक्विडिटी टोकन","{d} को अनलॉक","गतिविधि","XLNFT रखने वाले वॉलेट","आज के ट्रांसफ़र (UTC)","ट्रांसफ़र · 7 दिन","ट्रांसफ़र · 30 दिन","डिप्लॉयमेंट से अब तक ट्रांसफ़र","ट्रांसफ़र इतिहास पढ़ा जा रहा है… {p}%","सबसे बड़े वॉलेट","कुल सप्लाई में हिस्सा · {h} वॉलेट","मालिक का वॉलेट","टोकन कॉन्ट्रैक्ट","कॉन्ट्रैक्ट में तय","सीधे BNB Chain से पढ़ा गया: टोकन कॉन्ट्रैक्ट, PancakeSwap पूल और PinkLock लॉक। हर 20 मिनट में अपडेट।","धारक","टॉप 10: {p}%","हर जाँच में टोकन सीधे BNB Chain से पढ़ा जाता है। कॉन्ट्रैक्ट पते पर चल रहा कोड बाइट-दर-बाइट वही है जो BscScan पर प्रकाशित सोर्स कोड से कंपाइल होता है (Solidity 0.8.19, optimizer 200, EVM paris), और उस कोड में टोकन बनाने वाला कोई फ़ंक्शन नहीं है। सभी 100,000,000 XLNFT {d} (ब्लॉक {blk}) को कॉन्ट्रैक्ट डिप्लॉय होते समय बने थे; कुल संख्या केवल burn या burnFrom से घट सकती है — अब तक बर्न: {burn} XLNFT। मालिक ({own}) केवल स्वामित्व ट्रांसफ़र कर सकता है या छोड़ सकता है और गलती से कॉन्ट्रैक्ट पते पर भेजे गए टोकन वापस ला सकता है: कोड में कोई शुल्क, ब्लैकलिस्ट, विराम या ज़बरदस्ती ट्रांसफ़र नहीं है। मालिक के वॉलेट में सप्लाई का {op}% है। PancakeSwap पूल के {lp}% लिक्विडिटी टोकन {u} तक PinkLock पर लॉक हैं।","डिप्लॉयमेंट से अब तक के सभी {n} ट्रांसफ़र दोबारा चलाने पर {h} वॉलेट में XLNFT है, उनके बैलेंस का योग ठीक कुल सप्लाई के बराबर है और डिप्लॉयमेंट के बाद कोई टोकन नहीं बना।","कॉन्ट्रैक्ट, लिक्विडिटी और गतिविधि","पूल में कीमत","बर्न पता"],"hr":["Ugovor","Kod je istovjetan objavljenom izvornom kodu","Kod se razlikuje od objavljenog izvornog koda","Vlasnik","Vlasništvo odbačeno","Tokeni stvoreni nakon implementacije","Spaljeno","Likvidnost","PancakeSwap pool","Tokeni likvidnosti zaključani na PinkLocku","Otključavanje {d}","Aktivnost","Novčanici s XLNFT-om","Prijenosi danas (UTC)","Prijenosi · 7 dana","Prijenosi · 30 dana","Prijenosi od implementacije","Čitanje povijesti prijenosa… {p}%","Najveći novčanici","Udio u ukupnoj ponudi · {h} novčanika","Novčanik vlasnika","Ugovor tokena","fiksno u ugovoru","Čita se izravno s BNB Chaina: ugovor tokena, PancakeSwap pool i PinkLock zaključavanje. Ažurira se svakih 20 minuta.","Vlasnici","Top 10: {p}%","Svaka provjera čita token izravno s BNB Chaina. Kod na adresi ugovora bajt po bajt je kod preveden iz izvornog koda objavljenog na BscScanu (Solidity 0.8.19, optimizer 200, EVM paris), a taj kod nema nijednu funkciju koja stvara tokene. Svih 100.000.000 XLNFT stvoreno je pri implementaciji ugovora {d} (blok {blk}); ukupna količina može samo padati, putem burn ili burnFrom — dosad spaljeno: {burn} XLNFT. Vlasnik ({own}) može samo prenijeti vlasništvo ili ga se odreći i vratiti tokene greškom poslane na adresu ugovora: kod nema naknadu, crnu listu, pauzu ni prisilni prijenos. Novčanik vlasnika drži {op} % ponude. {lp} % tokena likvidnosti PancakeSwap poola zaključano je na PinkLocku do {u}.","Ponavljanjem svih {n} prijenosa od implementacije, {h} novčanika drži XLNFT, njihova stanja zbrojena daju točno ukupnu ponudu i nijedan token nije stvoren nakon implementacije.","Ugovor, likvidnost i aktivnost","Cijena u poolu","Adresa za spaljivanje"],"hu":["Szerződés","A kód megegyezik a közzétett forráskóddal","A kód eltér a közzétett forráskódtól","Tulajdonos","Tulajdonjogról lemondva","Telepítés után létrehozott tokenek","Elégetett","Likviditás","PancakeSwap pool","PinkLockon zárolt likviditási tokenek","Feloldás: {d}","Aktivitás","XLNFT-t tartó tárcák","Mai átutalások (UTC)","Átutalások · 7 nap","Átutalások · 30 nap","Átutalások a telepítés óta","Az átutalási előzmények beolvasása… {p}%","Legnagyobb tárcák","Részesedés a teljes kínálatból · {h} tárca","Tulajdonos tárcája","Token szerződés","a szerződésben rögzítve","Közvetlenül a BNB Chainről olvasva: a token szerződése, a PancakeSwap pool és a PinkLock zár. 20 percenként frissül.","Tulajdonosok","Top 10: {p}%","Minden ellenőrzés közvetlenül a BNB Chainről olvassa a tokent. A szerződés címén futó kód bájtról bájtra az a kód, amely a BscScanen közzétett forráskódból fordul (Solidity 0.8.19, optimizer 200, EVM paris), és ebben a kódban nincs tokent létrehozó függvény. Mind a 100 000 000 XLNFT a szerződés telepítésekor jött létre {d}-n ({blk}. blokk); az összmennyiség csak csökkenhet, burn vagy burnFrom révén — eddig elégetve: {burn} XLNFT. A tulajdonos ({own}) csak átruházhatja vagy feladhatja a tulajdonjogot, és visszaszerezheti a szerződés címére tévedésből küldött tokeneket: a kódban nincs díj, feketelista, szüneteltetés vagy kényszerített átutalás. A tulajdonos tárcája a kínálat {op}%-át tartja. A PancakeSwap pool likviditási tokenjeinek {lp}%-a {u}-ig zárolva van a PinkLockon.","A telepítés óta történt mind a(z) {n} átutalást visszajátszva {h} tárca tart XLNFT-t, egyenlegük összege pontosan a teljes kínálat, és a telepítés után egyetlen token sem jött létre.","Szerződés, likviditás és aktivitás","Ár a poolban","Égetési cím"],"id":["Kontrak","Kode identik dengan kode sumber yang dipublikasikan","Kode berbeda dari kode sumber yang dipublikasikan","Pemilik","Kepemilikan dilepaskan","Token yang dibuat setelah deployment","Dibakar","Likuiditas","Pool PancakeSwap","Token likuiditas dikunci di PinkLock","Terbuka pada {d}","Aktivitas","Dompet yang memegang XLNFT","Transfer hari ini (UTC)","Transfer · 7 hari","Transfer · 30 hari","Transfer sejak deployment","Membaca riwayat transfer… {p}%","Dompet terbesar","Porsi dari total pasokan · {h} dompet","Dompet pemilik","Kontrak token","tetap di dalam kontrak","Dibaca langsung dari BNB Chain: kontrak token, pool PancakeSwap, dan kunci PinkLock. Diperbarui setiap 20 menit.","Pemegang","Top 10: {p}%","Setiap pemeriksaan membaca token langsung dari BNB Chain. Kode yang berjalan di alamat kontrak sama persis, byte demi byte, dengan kode hasil kompilasi dari kode sumber yang dipublikasikan di BscScan (Solidity 0.8.19, optimizer 200, EVM paris), dan kode itu tidak memiliki fungsi yang membuat token. Seluruh 100.000.000 XLNFT dibuat saat kontrak di-deploy pada {d} (blok {blk}); totalnya hanya bisa berkurang, lewat burn atau burnFrom — dibakar sejauh ini: {burn} XLNFT. Pemilik ({own}) hanya dapat mengalihkan atau melepaskan kepemilikan dan memulihkan token yang terkirim ke alamat kontrak karena salah: kode tidak memiliki biaya, daftar hitam, jeda, atau transfer paksa. Dompet pemilik memegang {op}% pasokan. {lp}% token likuiditas pool PancakeSwap dikunci di PinkLock hingga {u}.","Dengan memutar ulang seluruh {n} transfer sejak deployment, {h} dompet memegang XLNFT, jumlah saldonya tepat sama dengan total pasokan, dan tidak ada token yang dibuat setelah deployment.","Kontrak, likuiditas, dan aktivitas","Harga di pool","Alamat pembakaran"],"it":["Contratto","Codice identico al codice sorgente pubblicato","Il codice differisce dal codice sorgente pubblicato","Proprietario","Proprietà rinunciata","Token creati dopo il deploy","Bruciati","Liquidità","Pool PancakeSwap","Token di liquidità bloccati su PinkLock","Si sblocca il {d}","Attività","Wallet che detengono XLNFT","Trasferimenti di oggi (UTC)","Trasferimenti · 7 giorni","Trasferimenti · 30 giorni","Trasferimenti dal deploy","Lettura dello storico dei trasferimenti… {p}%","Wallet più grandi","Quota dell’offerta totale · {h} wallet","Wallet del proprietario","Contratto del token","fissato nel contratto","Letto direttamente da BNB Chain: il contratto del token, il pool PancakeSwap e il blocco PinkLock. Aggiornato ogni 20 minuti.","Detentori","Top 10: {p}%","Ogni controllo legge il token direttamente da BNB Chain. Il codice in esecuzione all’indirizzo del contratto è, byte per byte, il codice compilato dal sorgente pubblicato su BscScan (Solidity 0.8.19, optimizer 200, EVM paris), e quel codice non ha alcuna funzione che crei token. Tutti i 100.000.000 di XLNFT sono stati creati al deploy del contratto il {d} (blocco {blk}); il totale può solo diminuire, tramite burn o burnFrom — bruciati finora: {burn} XLNFT. Il proprietario ({own}) può solo trasferire o rinunciare alla proprietà e recuperare token inviati per errore all’indirizzo del contratto: il codice non ha commissioni, blacklist, pausa né trasferimenti forzati. Il wallet del proprietario detiene il {op}% dell’offerta. Il {lp}% dei token di liquidità del pool PancakeSwap è bloccato su PinkLock fino al {u}.","Ripercorrendo tutti i {n} trasferimenti dal deploy, {h} wallet detengono XLNFT, i loro saldi sommano esattamente l’offerta totale e nessun token è stato creato dopo il deploy.","Contratto, liquidità e attività","Prezzo nel pool","Indirizzo di burn"],"ja":["コントラクト","公開ソースコードと同一のコード","公開ソースコードと異なるコード","オーナー","オーナー権放棄済み","デプロイ後に作成されたトークン","バーン済み","流動性","PancakeSwap プール","PinkLock でロックされた流動性トークン","{d} にロック解除","アクティビティ","XLNFT を保有するウォレット","本日の送金（UTC）","送金 · 7日","送金 · 30日","デプロイ以降の送金","送金履歴を読み込み中… {p}%","最大のウォレット","総供給量に占める割合 · {h} ウォレット","オーナーのウォレット","トークンコントラクト","コントラクトで固定","BNB Chain から直接読み取り：トークンコントラクト、PancakeSwap プール、PinkLock のロック。20分ごとに更新。","保有者","トップ10：{p}%","毎回のチェックでトークンを BNB Chain から直接読み取ります。コントラクトアドレスで動作しているコードは、BscScan で公開されたソースコード（Solidity 0.8.19、optimizer 200、EVM paris）からコンパイルしたコードとバイト単位で一致し、そのコードにはトークンを作成する関数がありません。100,000,000 XLNFT はすべて {d}（ブロック {blk}）のコントラクトのデプロイ時に作成されました。総量は burn または burnFrom によって減ることしかありません — これまでのバーン量：{burn} XLNFT。オーナー（{own}）にできるのは、オーナー権の譲渡または放棄と、誤ってコントラクトアドレスに送られたトークンの回収だけです。コードには手数料、ブラックリスト、一時停止、強制送金はありません。オーナーのウォレットは供給量の {op}% を保有しています。PancakeSwap プールの流動性トークンの {lp}% は {u} まで PinkLock でロックされています。","デプロイ以降の {n} 件の送金をすべて再現すると、XLNFT を保有するウォレットは {h} 個で、残高の合計は総供給量と完全に一致し、デプロイ後に作成されたトークンはありません。","コントラクト・流動性・アクティビティ","プール内の価格","バーンアドレス"],"ko":["컨트랙트","공개된 소스 코드와 동일한 코드","공개된 소스 코드와 다른 코드","소유자","소유권 포기됨","배포 이후 생성된 토큰","소각됨","유동성","PancakeSwap 풀","PinkLock에 잠긴 유동성 토큰","{d} 잠금 해제","활동","XLNFT 보유 지갑","오늘의 전송 (UTC)","전송 · 7일","전송 · 30일","배포 이후 전송","전송 내역을 읽는 중… {p}%","가장 큰 지갑","총 공급량 대비 비중 · 지갑 {h}개","소유자 지갑","토큰 컨트랙트","컨트랙트에 고정","BNB Chain에서 직접 읽음: 토큰 컨트랙트, PancakeSwap 풀, PinkLock 잠금. 20분마다 업데이트됩니다.","보유자","상위 10: {p}%","매 점검마다 토큰을 BNB Chain에서 직접 읽습니다. 컨트랙트 주소에서 실행되는 코드는 BscScan에 공개된 소스 코드(Solidity 0.8.19, optimizer 200, EVM paris)로 컴파일한 코드와 바이트 단위로 동일하며, 그 코드에는 토큰을 생성하는 함수가 없습니다. 100,000,000 XLNFT는 모두 {d}(블록 {blk}) 컨트랙트 배포 시 생성되었고, 총량은 burn 또는 burnFrom으로만 줄어들 수 있습니다 — 지금까지 소각량: {burn} XLNFT. 소유자({own})는 소유권 이전 또는 포기와 실수로 컨트랙트 주소에 보낸 토큰의 회수만 할 수 있습니다: 코드에는 수수료, 블랙리스트, 일시 정지, 강제 전송이 없습니다. 소유자 지갑은 공급량의 {op}%를 보유하고 있습니다. PancakeSwap 풀 유동성 토큰의 {lp}%가 {u}까지 PinkLock에 잠겨 있습니다.","배포 이후의 전송 {n}건을 모두 재현하면 XLNFT를 보유한 지갑은 {h}개이고, 잔액의 합은 총 공급량과 정확히 같으며, 배포 이후 생성된 토큰은 없습니다.","컨트랙트, 유동성 및 활동","풀 내 가격","소각 주소"],"lt":["Sutartis","Kodas sutampa su paskelbtu šaltiniu","Kodas skiriasi nuo paskelbto šaltinio","Savininkas","Atsisakyta nuosavybės","Po diegimo sukurti žetonai","Sudeginta","Likvidumas","PancakeSwap fondas","Likvidumo žetonai užrakinti PinkLock","Atrakinama {d}","Aktyvumas","Piniginės su XLNFT","Pervedimai šiandien (UTC)","Pervedimai · 7 dienos","Pervedimai · 30 dienų","Pervedimai nuo diegimo","Skaitoma pervedimų istorija… {p}%","Didžiausios piniginės","Dalis bendros pasiūlos · {h} piniginės","Savininko piniginė","Žetono sutartis","nustatyta sutartyje","Skaitoma tiesiai iš BNB Chain: žetono sutartis, PancakeSwap fondas ir PinkLock užraktas. Atnaujinama kas 20 minučių.","Turėtojai","Top 10: {p}%","Kiekvieno patikrinimo metu žetonas skaitomas tiesiai iš BNB Chain. Sutarties adresu veikiantis kodas baitas į baitą sutampa su kodu, sukompiliuotu iš BscScan paskelbto šaltinio (Solidity 0.8.19, optimizer 200, EVM paris), ir tame kode nėra jokios žetonus kuriančios funkcijos. Visi 100 000 000 XLNFT sukurti diegiant sutartį {d} (blokas {blk}); bendras kiekis gali tik mažėti, per burn arba burnFrom – iki šiol sudeginta: {burn} XLNFT. Savininkas ({own}) gali tik perduoti nuosavybę arba jos atsisakyti ir susigrąžinti per klaidą sutarties adresu išsiųstus žetonus: kode nėra mokesčio, juodojo sąrašo, pauzės ar priverstinio pervedimo. Savininko piniginėje yra {op} % pasiūlos. {lp} % PancakeSwap fondo likvidumo žetonų užrakinta PinkLock iki {u}.","Atkartojus visus {n} pervedimus nuo diegimo, XLNFT turi {h} piniginės, jų likučių suma tiksliai lygi bendrai pasiūlai ir po diegimo nesukurtas nė vienas žetonas.","Sutartis, likvidumas ir aktyvumas","Kaina fonde","Deginimo adresas"],"nl":["Contract","Code identiek aan de gepubliceerde broncode","Code wijkt af van de gepubliceerde broncode","Eigenaar","Eigendom opgegeven","Tokens aangemaakt na de deployment","Verbrand","Liquiditeit","PancakeSwap-pool","Liquiditeitstokens vergrendeld op PinkLock","Ontgrendeld op {d}","Activiteit","Wallets met XLNFT","Transfers vandaag (UTC)","Transfers · 7 dagen","Transfers · 30 dagen","Transfers sinds de deployment","Transfergeschiedenis wordt gelezen… {p}%","Grootste wallets","Aandeel in het totale aanbod · {h} wallets","Wallet van de eigenaar","Tokencontract","vastgelegd in het contract","Rechtstreeks gelezen van BNB Chain: het tokencontract, de PancakeSwap-pool en de PinkLock-vergrendeling. Wordt elke 20 minuten bijgewerkt.","Houders","Top 10: {p}%","Bij elke controle wordt de token rechtstreeks van BNB Chain gelezen. De code op het contractadres is byte voor byte de code die wordt gecompileerd uit de broncode die op BscScan is gepubliceerd (Solidity 0.8.19, optimizer 200, EVM paris), en die code heeft geen functie die tokens aanmaakt. Alle 100.000.000 XLNFT zijn aangemaakt bij de deployment van het contract op {d} (blok {blk}); het totaal kan alleen dalen, via burn of burnFrom — tot nu toe verbrand: {burn} XLNFT. De eigenaar ({own}) kan alleen het eigendom overdragen of opgeven en tokens terughalen die per ongeluk naar het contractadres zijn gestuurd: de code heeft geen vergoeding, blacklist, pauze of gedwongen transfer. De wallet van de eigenaar houdt {op}% van het aanbod. {lp}% van de liquiditeitstokens van de PancakeSwap-pool is tot {u} vergrendeld op PinkLock.","Als alle {n} transfers sinds de deployment opnieuw worden afgespeeld, houden {h} wallets XLNFT, tellen hun saldi precies op tot het totale aanbod en is er na de deployment geen enkele token aangemaakt.","Contract, liquiditeit en activiteit","Prijs in de pool","Burn-adres"],"no":["Kontrakt","Koden er identisk med den publiserte kildekoden","Koden avviker fra den publiserte kildekoden","Eier","Eierskap gitt opp","Tokens opprettet etter utrullingen","Brent","Likviditet","PancakeSwap-pool","Likviditetstokens låst på PinkLock","Låses opp {d}","Aktivitet","Lommebøker med XLNFT","Overføringer i dag (UTC)","Overføringer · 7 dager","Overføringer · 30 dager","Overføringer siden utrullingen","Leser overføringshistorikken… {p}%","Største lommebøker","Andel av totalt tilbud · {h} lommebøker","Eierens lommebok","Tokenkontrakt","fastsatt i kontrakten","Lest direkte fra BNB Chain: tokenkontrakten, PancakeSwap-poolen og PinkLock-låsen. Oppdateres hvert 20. minutt.","Innehavere","Topp 10: {p}%","Hver kontroll leser tokenet direkte fra BNB Chain. Koden på kontraktadressen er byte for byte koden som kompileres fra kildekoden publisert på BscScan (Solidity 0.8.19, optimizer 200, EVM paris), og den koden har ingen funksjon som oppretter tokens. Alle 100 000 000 XLNFT ble opprettet da kontrakten ble rullet ut {d} (blokk {blk}); totalen kan bare synke, via burn eller burnFrom — brent så langt: {burn} XLNFT. Eieren ({own}) kan bare overdra eller gi opp eierskapet og hente tokens som ved en feil er sendt til kontraktadressen: koden har ingen avgift, svarteliste, pause eller tvungen overføring. Eierens lommebok har {op} % av tilbudet. {lp} % av likviditetstokenene i PancakeSwap-poolen er låst på PinkLock til {u}.","Når alle {n} overføringer siden utrullingen spilles av på nytt, har {h} lommebøker XLNFT, saldoene deres summerer seg nøyaktig til totalt tilbud og ingen token ble opprettet etter utrullingen.","Kontrakt, likviditet og aktivitet","Pris i poolen","Brenneadresse"],"ro":["Contract","Cod identic cu codul sursă publicat","Codul diferă de codul sursă publicat","Proprietar","Proprietate renunțată","Tokenuri create după implementare","Arse","Lichiditate","Pool PancakeSwap","Tokenuri de lichiditate blocate pe PinkLock","Se deblochează pe {d}","Activitate","Portofele care dețin XLNFT","Transferuri azi (UTC)","Transferuri · 7 zile","Transferuri · 30 de zile","Transferuri de la implementare","Se citește istoricul transferurilor… {p}%","Cele mai mari portofele","Cotă din oferta totală · {h} portofele","Portofelul proprietarului","Contractul tokenului","fixat în contract","Citit direct de pe BNB Chain: contractul tokenului, pool-ul PancakeSwap și blocarea PinkLock. Se actualizează la fiecare 20 de minute.","Deținători","Top 10: {p}%","La fiecare verificare citim tokenul direct de pe BNB Chain. Codul care rulează la adresa contractului este, octet cu octet, codul compilat din sursa publicată pe BscScan (Solidity 0.8.19, optimizer 200, EVM paris), iar acel cod nu are nicio funcție care să creeze tokenuri. Toți cei 100.000.000 XLNFT au fost creați la implementarea contractului pe {d} (blocul {blk}); totalul poate doar să scadă, prin burn sau burnFrom — arse până acum: {burn} XLNFT. Proprietarul ({own}) poate doar să transfere sau să renunțe la proprietate și să recupereze tokenuri trimise din greșeală la adresa contractului: codul nu are comision, listă neagră, pauză sau transfer forțat. Portofelul proprietarului deține {op}% din ofertă. {lp}% din tokenurile de lichiditate ale pool-ului PancakeSwap sunt blocate pe PinkLock până pe {u}.","Refăcând toate cele {n} transferuri de la implementare, {h} portofele dețin XLNFT, soldurile lor însumează exact oferta totală și niciun token nu a fost creat după implementare.","Contract, lichiditate și activitate","Preț în pool","Adresa de ardere"],"sk":["Kontrakt","Kód zhodný so zverejneným zdrojovým kódom","Kód sa líši od zverejneného zdrojového kódu","Vlastník","Vlastníctva sa vzdal","Tokeny vytvorené po nasadení","Spálené","Likvidita","Pool PancakeSwap","Tokeny likvidity uzamknuté v PinkLock","Odomknutie {d}","Aktivita","Peňaženky s XLNFT","Prevody dnes (UTC)","Prevody · 7 dní","Prevody · 30 dní","Prevody od nasadenia","Načítava sa história prevodov… {p}%","Najväčšie peňaženky","Podiel na celkovej ponuke · {h} peňaženiek","Peňaženka vlastníka","Kontrakt tokenu","pevne dané v kontrakte","Čítané priamo z BNB Chain: kontrakt tokenu, pool PancakeSwap a zámok PinkLock. Aktualizuje sa každých 20 minút.","Držitelia","Top 10: {p}%","Každá kontrola číta token priamo z BNB Chain. Kód bežiaci na adrese kontraktu je bajt po bajte kód skompilovaný zo zdrojového kódu zverejneného na BscScan (Solidity 0.8.19, optimizer 200, EVM paris) a tento kód nemá žiadnu funkciu, ktorá vytvára tokeny. Všetkých 100 000 000 XLNFT vzniklo pri nasadení kontraktu {d} (blok {blk}); celkové množstvo môže len klesať, cez burn alebo burnFrom — doteraz spálené: {burn} XLNFT. Vlastník ({own}) môže len previesť vlastníctvo alebo sa ho vzdať a vrátiť tokeny omylom poslané na adresu kontraktu: kód nemá poplatok, čiernu listinu, pauzu ani vynútený prevod. Peňaženka vlastníka drží {op} % ponuky. {lp} % tokenov likvidity poolu PancakeSwap je uzamknutých v PinkLock do {u}.","Po prehratí všetkých {n} prevodov od nasadenia drží XLNFT {h} peňaženiek, ich zostatky dávajú presne celkovú ponuku a po nasadení nevznikol žiadny token.","Kontrakt, likvidita a aktivita","Cena v poole","Adresa na pálenie"],"sl":["Pogodba","Koda je enaka objavljeni izvorni kodi","Koda se razlikuje od objavljene izvorne kode","Lastnik","Lastništvu se je odpovedal","Žetoni, ustvarjeni po namestitvi","Sežgano","Likvidnost","Bazen PancakeSwap","Žetoni likvidnosti, zaklenjeni na PinkLock","Odklep {d}","Dejavnost","Denarnice z XLNFT","Prenosi danes (UTC)","Prenosi · 7 dni","Prenosi · 30 dni","Prenosi od namestitve","Branje zgodovine prenosov… {p}%","Največje denarnice","Delež skupne ponudbe · {h} denarnic","Lastnikova denarnica","Pogodba žetona","določeno v pogodbi","Prebrano neposredno z BNB Chain: pogodba žetona, bazen PancakeSwap in zaklep PinkLock. Posodablja se vsakih 20 minut.","Imetniki","Top 10: {p}%","Vsako preverjanje prebere žeton neposredno z BNB Chain. Koda na naslovu pogodbe je bajt za bajtom koda, prevedena iz izvorne kode, objavljene na BscScan (Solidity 0.8.19, optimizer 200, EVM paris), in ta koda nima nobene funkcije, ki bi ustvarjala žetone. Vseh 100.000.000 XLNFT je nastalo ob namestitvi pogodbe {d} (blok {blk}); skupna količina se lahko le zmanjšuje, prek burn ali burnFrom — doslej sežgano: {burn} XLNFT. Lastnik ({own}) lahko le prenese lastništvo ali se mu odpove in vrne žetone, ki so bili pomotoma poslani na naslov pogodbe: koda nima provizije, črnega seznama, premora ali prisilnega prenosa. Lastnikova denarnica hrani {op} % ponudbe. {lp} % žetonov likvidnosti bazena PancakeSwap je do {u} zaklenjenih na PinkLock.","Ob ponovitvi vseh {n} prenosov od namestitve ima XLNFT {h} denarnic, vsota njihovih stanj je natanko skupna ponudba in po namestitvi ni nastal noben žeton.","Pogodba, likvidnost in dejavnost","Cena v bazenu","Naslov za sežiganje"],"sv":["Kontrakt","Koden är identisk med den publicerade källkoden","Koden skiljer sig från den publicerade källkoden","Ägare","Ägarskap avsagt","Tokens skapade efter driftsättningen","Brända","Likviditet","PancakeSwap-pool","Likviditetstokens låsta på PinkLock","Låses upp {d}","Aktivitet","Plånböcker med XLNFT","Överföringar i dag (UTC)","Överföringar · 7 dagar","Överföringar · 30 dagar","Överföringar sedan driftsättningen","Läser överföringshistoriken… {p}%","Största plånböckerna","Andel av totalt utbud · {h} plånböcker","Ägarens plånbok","Tokenkontrakt","fastställt i kontraktet","Läst direkt från BNB Chain: tokenkontraktet, PancakeSwap-poolen och PinkLock-låset. Uppdateras var 20:e minut.","Innehavare","Topp 10: {p}%","Varje kontroll läser token direkt från BNB Chain. Koden på kontraktsadressen är byte för byte den kod som kompileras från källkoden publicerad på BscScan (Solidity 0.8.19, optimizer 200, EVM paris), och den koden har ingen funktion som skapar tokens. Alla 100 000 000 XLNFT skapades när kontraktet driftsattes {d} (block {blk}); totalen kan bara minska, via burn eller burnFrom — bränt hittills: {burn} XLNFT. Ägaren ({own}) kan bara överlåta eller avsäga sig ägarskapet och hämta tokens som av misstag skickats till kontraktsadressen: koden har ingen avgift, svartlista, paus eller tvingad överföring. Ägarens plånbok har {op} % av utbudet. {lp} % av likviditetstokens i PancakeSwap-poolen är låsta på PinkLock till {u}.","När alla {n} överföringar sedan driftsättningen spelas upp igen har {h} plånböcker XLNFT, deras saldon summerar exakt till det totala utbudet och ingen token skapades efter driftsättningen.","Kontrakt, likviditet och aktivitet","Pris i poolen","Bränningsadress"],"th":["สัญญา","โค้ดตรงกับซอร์สโค้ดที่เผยแพร่","โค้ดไม่ตรงกับซอร์สโค้ดที่เผยแพร่","เจ้าของ","สละความเป็นเจ้าของแล้ว","โทเค็นที่สร้างหลังการ deploy","เผาแล้ว","สภาพคล่อง","พูล PancakeSwap","โทเค็นสภาพคล่องที่ล็อกบน PinkLock","ปลดล็อกวันที่ {d}","กิจกรรม","กระเป๋าที่ถือ XLNFT","การโอนวันนี้ (UTC)","การโอน · 7 วัน","การโอน · 30 วัน","การโอนตั้งแต่ deploy","กำลังอ่านประวัติการโอน… {p}%","กระเป๋าที่ใหญ่ที่สุด","สัดส่วนของอุปทานทั้งหมด · {h} กระเป๋า","กระเป๋าของเจ้าของ","สัญญาโทเค็น","กำหนดไว้ในสัญญา","อ่านโดยตรงจาก BNB Chain: สัญญาโทเค็น พูล PancakeSwap และการล็อกของ PinkLock อัปเดตทุก 20 นาที","ผู้ถือ","10 อันดับแรก: {p}%","ทุกการตรวจสอบเราอ่านโทเค็นโดยตรงจาก BNB Chain โค้ดที่ทำงานอยู่ที่ที่อยู่สัญญาตรงกันทุกไบต์กับโค้ดที่คอมไพล์จากซอร์สโค้ดที่เผยแพร่บน BscScan (Solidity 0.8.19, optimizer 200, EVM paris) และโค้ดนั้นไม่มีฟังก์ชันใดที่สร้างโทเค็น XLNFT ทั้ง 100,000,000 ถูกสร้างขึ้นตอน deploy สัญญาเมื่อ {d} (บล็อก {blk}) ยอดรวมทำได้เพียงลดลงผ่าน burn หรือ burnFrom — เผาไปแล้ว: {burn} XLNFT เจ้าของ ({own}) ทำได้เพียงโอนหรือสละความเป็นเจ้าของ และกู้คืนโทเค็นที่ถูกส่งมาที่ที่อยู่สัญญาโดยผิดพลาด: โค้ดไม่มีค่าธรรมเนียม บัญชีดำ การหยุดชั่วคราว หรือการโอนโดยบังคับ กระเป๋าของเจ้าของถือ {op}% ของอุปทาน โทเค็นสภาพคล่องของพูล PancakeSwap {lp}% ถูกล็อกบน PinkLock จนถึง {u}","เมื่อเล่นซ้ำการโอนทั้งหมด {n} ครั้งตั้งแต่ deploy มีกระเป๋า {h} ใบที่ถือ XLNFT ยอดคงเหลือรวมกันเท่ากับอุปทานทั้งหมดพอดี และไม่มีโทเค็นใดถูกสร้างหลังการ deploy","สัญญา สภาพคล่อง และกิจกรรม","ราคาในพูล","ที่อยู่เผาเหรียญ"],"tr":["Sözleşme","Kod, yayımlanan kaynak kodla aynı","Kod, yayımlanan kaynak koddan farklı","Sahip","Sahiplikten vazgeçildi","Dağıtımdan sonra oluşturulan tokenler","Yakılan","Likidite","PancakeSwap havuzu","PinkLock’ta kilitli likidite tokenleri","{d} tarihinde kilit açılır","Etkinlik","XLNFT tutan cüzdanlar","Bugünkü transferler (UTC)","Transferler · 7 gün","Transferler · 30 gün","Dağıtımdan bu yana transferler","Transfer geçmişi okunuyor… {p}%","En büyük cüzdanlar","Toplam arzdaki pay · {h} cüzdan","Sahibin cüzdanı","Token sözleşmesi","sözleşmede sabit","Doğrudan BNB Chain’den okunur: token sözleşmesi, PancakeSwap havuzu ve PinkLock kilidi. 20 dakikada bir güncellenir.","Sahipler","İlk 10: %{p}","Her kontrolde token doğrudan BNB Chain’den okunur. Sözleşme adresinde çalışan kod, BscScan’de yayımlanan kaynak koddan derlenen kodla bayt bayt aynıdır (Solidity 0.8.19, optimizer 200, EVM paris) ve bu kodda token oluşturan hiçbir fonksiyon yoktur. 100.000.000 XLNFT’nin tamamı sözleşme {d} tarihinde (blok {blk}) dağıtılırken oluşturuldu; toplam yalnızca burn veya burnFrom ile azalabilir — şimdiye kadar yakılan: {burn} XLNFT. Sahip ({own}) yalnızca sahipliği devredebilir veya bırakabilir ve sözleşme adresine yanlışlıkla gönderilen tokenleri geri alabilir: kodda ücret, kara liste, duraklatma veya zorla transfer yoktur. Sahibin cüzdanı arzın %{op}’ini tutuyor. PancakeSwap havuzunun likidite tokenlerinin %{lp}’i {u} tarihine kadar PinkLock’ta kilitli.","Dağıtımdan bu yana yapılan {n} transferin tamamı yeniden oynatıldığında XLNFT tutan {h} cüzdan var, bakiyelerinin toplamı tam olarak toplam arza eşit ve dağıtımdan sonra hiçbir token oluşturulmadı.","Sözleşme, likidite ve etkinlik","Havuzdaki fiyat","Yakma adresi"],"uk":["Контракт","Код ідентичний опублікованому вихідному коду","Код відрізняється від опублікованого вихідного коду","Власник","Від володіння відмовилися","Токени, створені після розгортання","Спалено","Ліквідність","Пул PancakeSwap","Токени ліквідності заблоковано в PinkLock","Розблокування {d}","Активність","Гаманці з XLNFT","Перекази сьогодні (UTC)","Перекази · 7 днів","Перекази · 30 днів","Перекази від розгортання","Читання історії переказів… {p}%","Найбільші гаманці","Частка загальної пропозиції · {h} гаманців","Гаманець власника","Контракт токена","зафіксовано в контракті","Зчитується безпосередньо з BNB Chain: контракт токена, пул PancakeSwap і блокування PinkLock. Оновлюється кожні 20 хвилин.","Власники","Топ-10: {p}%","Під час кожної перевірки токен зчитується безпосередньо з BNB Chain. Код за адресою контракту байт у байт збігається з кодом, скомпільованим із вихідного коду, опублікованого на BscScan (Solidity 0.8.19, optimizer 200, EVM paris), і в цьому коді немає жодної функції, що створює токени. Усі 100 000 000 XLNFT було створено під час розгортання контракту {d} (блок {blk}); загальна кількість може лише зменшуватися через burn або burnFrom — спалено на сьогодні: {burn} XLNFT. Власник ({own}) може лише передати володіння або відмовитися від нього та повернути токени, помилково надіслані на адресу контракту: у коді немає комісії, чорного списку, паузи чи примусового переказу. Гаманець власника тримає {op}% пропозиції. {lp}% токенів ліквідності пулу PancakeSwap заблоковано в PinkLock до {u}.","Якщо відтворити всі {n} переказів від розгортання, XLNFT тримають {h} гаманців, сума їхніх балансів точно дорівнює загальній пропозиції, і жоден токен не було створено після розгортання.","Контракт, ліквідність і активність","Ціна в пулі","Адреса спалювання"],"zh":["合约","代码与公开的源代码一致","代码与公开的源代码不一致","所有者","已放弃所有权","部署后创建的代币","已销毁","流动性","PancakeSwap 资金池","锁定在 PinkLock 的流动性代币","{d} 解锁","活动","持有 XLNFT 的钱包","今日转账（UTC）","转账 · 7 天","转账 · 30 天","部署以来的转账","正在读取转账历史… {p}%","最大的钱包","占总供应量比例 · {h} 个钱包","所有者钱包","代币合约","固定在合约中","直接从 BNB Chain 读取：代币合约、PancakeSwap 资金池和 PinkLock 锁仓。每 20 分钟更新一次。","持有者","前 10：{p}%","每次检查都直接从 BNB Chain 读取代币。合约地址上运行的代码与 BscScan 上公开的源代码（Solidity 0.8.19，optimizer 200，EVM paris）编译出的代码逐字节一致，且该代码没有任何创建代币的函数。全部 100,000,000 XLNFT 均在 {d}（区块 {blk}）部署合约时创建；总量只能通过 burn 或 burnFrom 减少——目前已销毁：{burn} XLNFT。所有者（{own}）只能转让或放弃所有权，以及取回误发到合约地址的代币：代码中没有手续费、黑名单、暂停或强制转账。所有者钱包持有供应量的 {op}%。PancakeSwap 资金池 {lp}% 的流动性代币锁定在 PinkLock，直到 {u}。","重放部署以来的全部 {n} 笔转账，共有 {h} 个钱包持有 XLNFT，余额之和与总供应量完全一致，部署后没有创建任何代币。","合约、流动性与活动","资金池价格","销毁地址"],"zh-TW":["合約","程式碼與公開的原始碼一致","程式碼與公開的原始碼不一致","擁有者","已放棄擁有權","部署後建立的代幣","已銷毀","流動性","PancakeSwap 資金池","鎖定在 PinkLock 的流動性代幣","{d} 解鎖","活動","持有 XLNFT 的錢包","今日轉帳（UTC）","轉帳 · 7 天","轉帳 · 30 天","部署以來的轉帳","正在讀取轉帳紀錄… {p}%","最大的錢包","占總供應量比例 · {h} 個錢包","擁有者錢包","代幣合約","固定在合約中","直接從 BNB Chain 讀取：代幣合約、PancakeSwap 資金池和 PinkLock 鎖倉。每 20 分鐘更新一次。","持有者","前 10：{p}%","每次檢查都直接從 BNB Chain 讀取代幣。合約地址上執行的程式碼與 BscScan 上公開的原始碼（Solidity 0.8.19，optimizer 200，EVM paris）編譯出的程式碼逐位元組一致，且該程式碼沒有任何建立代幣的函式。全部 100,000,000 XLNFT 均在 {d}（區塊 {blk}）部署合約時建立；總量只能透過 burn 或 burnFrom 減少——目前已銷毀：{burn} XLNFT。擁有者（{own}）只能轉讓或放棄擁有權，以及取回誤送到合約地址的代幣：程式碼中沒有手續費、黑名單、暫停或強制轉帳。擁有者錢包持有供應量的 {op}%。PancakeSwap 資金池 {lp}% 的流動性代幣鎖定在 PinkLock，直到 {u}。","重播部署以來的全部 {n} 筆轉帳，共有 {h} 個錢包持有 XLNFT，餘額總和與總供應量完全一致，部署後沒有建立任何代幣。","合約、流動性與活動","資金池價格","銷毀地址"]};
(function(){ for(var i = 0; i < TK_I18N.en.length; i++){ I18N['tk' + i] = {}; Object.keys(TK_I18N).forEach(function(l){ I18N['tk' + i][l] = TK_I18N[l][i]; }); } })();
function tkT(lang, i){ return (TK_I18N[lang] || TK_I18N.en)[i]; }
function tkShort(a){ return a ? a.slice(0, 6) + '…' + a.slice(-4) : '—'; }
function tkAddr(a){ return '<a href="https://bscscan.com/address/' + escHtml(a) + '" target=_blank rel=noopener>' + escHtml(tkShort(a)) + '</a>'; }
function renderAuditTokenCard(cfg, r, lang){
  var grid = document.getElementById('auditRewardsGrid');
  if(!grid) return;
  setText('.auditRewardsTitleEl', tkT(lang, 28));
  setText('.auditRewardsUpdatedEl', expT('rwUpdated', lang, { t: relTime(new Date(r.ts).getTime(), lang) }));
  setText('.auditRewardsNoteEl', tkT(lang, 23));
  var amt = function(v, d){ return Number(v).toLocaleString('en-US', { maximumFractionDigits: d == null ? 2 : d }); };
  var row = function(label, value){ return '<div class=rwPerMn><span>' + escHtml(label) + '</span><b>' + value + '</b></div>'; };
  var bar = function(pct, colors){ return '<div class=rwBar><i style="width:' + Math.max(0, Math.min(100, pct)) + '%;background:linear-gradient(90deg,' + colors + ')"></i></div>'; };
  var date = function(iso){ return iso ? new Date(iso).toLocaleDateString(lang) : '—'; };
  var p = r.pool || {}, g = r.ledger || {};
  var contractCol = '<div class=rwCol>' +
    '<div class=rwHead><b>' + escHtml(tkT(lang, 0)) + '</b><span style="color:' + (r.codeMatches ? 'var(--green)' : 'var(--red)') + '">' + (r.codeMatches ? '✓ ' : '✗ ') + escHtml(tkT(lang, r.codeMatches ? 1 : 2)) + '</span></div>' +
    '<div class=rwTotal>' + amt(r.supply, 0) + ' ' + cfg.unit + '</div><div class=rwTotalLabel>' + escHtml(pick(I18N.kpiTotalSupply, lang)) + ' · ' + escHtml(tkT(lang, 22)) + '</div>' +
    row(tkT(lang, 3), r.ownerRenounced ? escHtml(tkT(lang, 4)) : tkAddr(r.owner)) +
    '<div class=rwRow><div class=rwRowHead><span>' + escHtml(tkT(lang, 20)) + '</span><b>' + amt(r.ownerBalance, 0) + ' ' + cfg.unit + ' · ' + Number(r.ownerPct).toFixed(2) + '%</b></div>' + bar(r.ownerPct, 'var(--amber),var(--red)') + '</div>' +
    row(tkT(lang, 5), g.complete ? String(g.mintsAfterDeploy) : '—') +
    row(tkT(lang, 6), amt(r.burned) + ' ' + cfg.unit) +
    '</div>';
  var liquidityCol = '<div class=rwCol>' +
    '<div class=rwHead><b>' + escHtml(tkT(lang, 7)) + '</b><span>' + escHtml(p.dex || '') + '</span></div>' +
    '<div class=rwTotal>' + (p.priceUsdt != null ? amt(p.priceUsdt, 6) + ' USDT' : '—') + '</div><div class=rwTotalLabel>' + escHtml(tkT(lang, 29)) + (p.address ? ' · ' + amt(p.usdtReserve) + ' USDT + ' + amt(p.tokenReserve, 0) + ' ' + cfg.unit : '') + '</div>' +
    row(tkT(lang, 8), p.address ? tkAddr(p.address) : '—') +
    '<div class=rwRow><div class=rwRowHead><span>' + escHtml(tkT(lang, 9)) + '</span><b>' + Number(p.lpLockedPct || 0).toFixed(2) + '%</b></div>' + bar(p.lpLockedPct || 0, 'var(--green),var(--cyan)') + '</div>' +
    row(p.locks && p.locks.length ? 'PinkLock #' + p.locks.map(function(x){ return x.id; }).join(', #') : 'PinkLock', escHtml(tkT(lang, 10).replace('{d}', date(p.unlocksAt)))) +
    '</div>';
  var activityCol = '<div class=rwCol>' +
    '<div class=rwHead><b>' + escHtml(tkT(lang, 11)) + '</b><span>' + (g.complete ? '' : escHtml(tkT(lang, 17).replace('{p}', Math.floor(g.progressPct || 0)))) + '</span></div>' +
    '<div class=rwTotal>' + (g.complete ? amt(g.holders, 0) : '—') + '</div><div class=rwTotalLabel>' + escHtml(tkT(lang, 12)) + '</div>' +
    row(tkT(lang, 13), g.transfersToday != null ? amt(g.transfersToday, 0) : '—') +
    row(tkT(lang, 14), g.transfers7d != null ? amt(g.transfers7d, 0) : '—') +
    row(tkT(lang, 15), g.transfers30d != null ? amt(g.transfers30d, 0) : '—') +
    row(tkT(lang, 16), g.complete ? amt(g.transfers, 0) : '—') +
    '</div>';
  grid.innerHTML = contractCol + liquidityCol + activityCol;
}
// The "core versions" card of a token audit: its largest wallets, as a share of the total supply.
function renderAuditHolders(cfg, r, lang){
  var g = r.ledger || {};
  setText('.auditVersionsTitleEl', tkT(lang, 18));
  setText('.auditVersionsNoteEl', '');
  var el = document.querySelector('.auditVersionsList');
  if(!g.complete || !g.top){
    setText('.auditVersionsDescEl', tkT(lang, 17).replace('{p}', Math.floor(g.progressPct || 0)));
    if(el) el.innerHTML = '';
    return;
  }
  setText('.auditVersionsDescEl', tkT(lang, 19).replace('{h}', Number(g.holders).toLocaleString('en-US')));
  var names = { owner: tkT(lang, 20), pool: tkT(lang, 8), contract: tkT(lang, 21), burn: tkT(lang, 30) };
  if(el) el.innerHTML = g.top.map(function(h, i){
    var color = h.label === 'owner' ? 'var(--amber)' : h.label === 'pool' ? 'var(--green)' : i === 0 ? 'var(--cyan)' : 'var(--violet)';
    var name = (h.label ? escHtml(names[h.label]) + ' · ' : '') + tkAddr(h.address);
    return '<div><i class=dot style="background:' + color + '"></i><span>' + name + '<br><b>' + Number(h.balance).toLocaleString('en-US', { maximumFractionDigits: 2 }) + ' ' + cfg.unit + '</b></span><span>' + (h.pct < 0.01 ? '<0.01' : Number(h.pct).toFixed(2)) + '%</span></div>';
  }).join('');
}

// ---- List of audited coins, grouped by kind inside the same Auditoria tab: masternode, mining,
// stake and token. A coin sits in every group whose tab lists it (XLN, PIVX and MoneyByte are both
// masternode and stake coins), so the groups always agree with the coin tabs. The group names are
// the tab names of the side menu, already translated.
var AUDIT_GROUPS = [ { view:'moedasView', nav:2 }, { view:'mineracaoView', nav:3 }, { view:'stakeView', nav:4 }, { view:'tokensView', nav:5 } ];
var AUDIT_EMPTY_I18N = {"en":"No audit published yet","ru":"Аудитов пока нет","de":"Noch kein Audit veröffentlicht","pl":"Brak opublikowanych audytów","es":"Aún no hay auditorías publicadas","vi":"Chưa có kiểm toán nào được công bố","fr":"Aucun audit publié pour l’instant","pt-BR":"Nenhuma auditoria publicada ainda","ar":"لا توجد تدقيقات منشورة بعد","bg":"Все още няма публикуван одит","cs":"Zatím nebyl zveřejněn žádný audit","da":"Ingen revision offentliggjort endnu","el":"Δεν έχει δημοσιευτεί ακόμη έλεγχος","fi":"Auditointeja ei ole vielä julkaistu","he":"עדיין לא פורסמה ביקורת","hi":"अभी तक कोई ऑडिट प्रकाशित नहीं हुआ","hr":"Još nema objavljene revizije","hu":"Még nincs közzétett audit","id":"Belum ada audit yang diterbitkan","it":"Nessun audit pubblicato per ora","ja":"公開済みの監査はまだありません","ko":"아직 공개된 감사가 없습니다","lt":"Auditų dar nepaskelbta","nl":"Nog geen audit gepubliceerd","no":"Ingen revisjon publisert ennå","ro":"Niciun audit publicat încă","sk":"Zatiaľ nebol zverejnený žiadny audit","sl":"Objavljene revizije še ni","sv":"Ingen granskning publicerad ännu","th":"ยังไม่มีการตรวจสอบที่เผยแพร่","tr":"Henüz yayımlanmış denetim yok","uk":"Аудитів поки немає","zh":"暂无已发布的审计","zh-TW":"尚無已發布的稽核"};
function auditInGroup(coinId, viewId){
  if(SITE_COIN_TABS[coinId]) return SITE_COIN_TABS[coinId].indexOf(viewId) >= 0;
  return !!document.querySelector('#' + viewId + ' tbody tr.coinRow[data-coin="' + coinId + '"]');
}
function renderAuditList(lang){
  setText('.auditListTitle', auditNavLabel());
  setText('.auditListHint', pick(I18N.auditPickHint, lang));
  var head = document.getElementById('auditListHead');
  var body = document.getElementById('auditListBody');
  if(!head || !body) return;
  head.innerHTML = '<tr><th>#</th><th>' + pick(I18N.exColCoin, lang) + '</th><th class=exNum>' + pick(I18N.blockHeight, lang) + '</th><th class="exNum exHideSm">' + pick(I18N.kpiCirculatingSupply, lang) + '</th><th class=exNum>' + pick(I18N.kpiMasternodes, lang) + '</th><th class=exNum>' + pick(I18N.rwTitle, lang) + ' · 24h</th></tr>';
  var navButtons = document.querySelectorAll('.nav button:not(#rankingBtn)');
  body.innerHTML = AUDIT_GROUPS.map(function(g){
    var ids = AUDIT_ORDER.filter(function(id){ return auditInGroup(AUDIT_COINS[id].coin, g.view); });
    var navSpan = navButtons[g.nav] && navButtons[g.nav].querySelector('span');
    var title = escHtml(auditNavLabel()) + ' · ' + escHtml(navSpan ? navSpan.textContent : g.view);
    var rows = ids.map(function(id, i){
      var coin = COINS[AUDIT_COINS[id].coin];
      // a masternode + stake coin listed under stake opens its stake-only audit
      var stakeOnly = g.view === 'stakeView' && AUDIT_COINS[id].rewards && auditInGroup(AUDIT_COINS[id].coin, 'moedasView');
      return '<tr class="coinRow exRankRow" data-audit=' + id + (stakeOnly ? ' data-kind=stake' : '') + '><td>' + (i + 1) + '</td><td><span class=platform><img class=coinIcon src="' + coin.icon + '" alt="' + coin.ticker + '">' + coin.name + '</span></td><td class=exNum data-f=height>…</td><td class="exNum exHideSm" data-f=supply>…</td><td class=exNum data-f=mn>…</td><td class="exNum exStrong" data-f=rewards>…</td></tr>';
    }).join('');
    if(!rows) rows = '<tr class=auditGroupEmpty><td colspan=6>' + escHtml(pick(AUDIT_EMPTY_I18N, lang)) + '</td></tr>';
    return '<tr class=auditGroupRow><td colspan=6>' + title + '<span class=pill>' + ids.length + '</span></td></tr>' + rows;
  }).join('');
  Array.prototype.forEach.call(body.querySelectorAll('tr[data-audit]'), function(row){
    row.onclick = function(){ openAudit(row.getAttribute('data-audit'), row.getAttribute('data-kind')); };
  });
  AUDIT_ORDER.forEach(function(id){
    var cfg = AUDIT_COINS[id];
    // a coin can be listed in more than one group: every one of its rows gets the figures
    // (stakeText: what the coin's row in the stake group shows instead, when it differs)
    var put = function(f, text, stakeText){
      Array.prototype.forEach.call(body.querySelectorAll('tr[data-audit=' + id + '] [data-f=' + f + ']'), function(c){
        c.textContent = stakeText != null && c.parentNode.getAttribute('data-kind') === 'stake' ? stakeText : text;
      });
    };
    fetch(PROXY_BASE + cfg.audit).then(function(r){ return r.json(); }).then(function(d){
      if(!d || !d.ok || !d.reading) throw new Error('no reading');
      var r = d.reading;
      put('height', r.height.toLocaleString('en-US'));
      put('supply', fmtCoinAmt(Math.round(r.circulating != null ? r.circulating : r.actualSupply != null ? r.actualSupply : r.supply), cfg.unit)); // circulating: Nodestats' burned coins left out
      put('mn', r.masternodesOnline != null ? r.masternodesOnline.toLocaleString('en-US') : '—', '—');
      if(cfg.miningCard && r.mining && r.mining.d1) put('rewards', fmtCoinAmt(r.mining.d1.minted, cfg.unit));
    }).catch(function(){ ['height', 'supply', 'mn'].forEach(function(f){ put(f, '—'); }); });
    if(!cfg.rewards){ put('rewards', '—'); return; }
    fetch(PROXY_BASE + cfg.rewards).then(function(r){ return r.json(); }).then(function(d){
      // stake group: the stakers' part of the last 24h, not the whole block rewards
      put('rewards', d && d.ok ? fmtCoinAmt(d.d1.total, cfg.unit) : '—', d && d.ok ? fmtCoinAmt(d.d1.stake, cfg.unit) : '—');
    }).catch(function(){ put('rewards', '—'); });
  });
}

// ---- One coin's audit
function applyAuditLayout(cfg){
  var supplyCard = document.querySelector('.auditChartSvg').closest('article');
  var diffCard = document.querySelector('.auditDifficultySvg').closest('article');
  var explainCard = document.querySelector('.auditExplainTitleEl').closest('article');
  var tabs = document.getElementById('auditRangeTabs');
  supplyCard.style.display = cfg.supplyAudit ? '' : 'none';
  explainCard.style.display = cfg.supplyAudit ? '' : 'none';
  var pill = document.querySelector('.auditoriaStatusPill');
  if(pill) pill.style.display = cfg.supplyAudit ? '' : 'none';
  var rewardsCard = document.getElementById('auditRewardsGrid').closest('article');
  var versionsCard = document.querySelector('.auditVersionsTitleEl').closest('article');
  rewardsCard.style.display = (cfg.rewards || cfg.stakeCard || cfg.miningCard || cfg.tokenCard) ? '' : 'none';
  versionsCard.style.display = cfg.noVersions ? 'none' : '';
  diffCard.style.display = cfg.noDifficulty ? 'none' : '';
  // The period tabs drive both charts; they sit on the first visible chart card.
  var ruleLink = document.querySelector('.auditExplainLinkEl');
  if(ruleLink && cfg.ruleUrl) ruleLink.href = cfg.ruleUrl;
  var host = (cfg.supplyAudit ? supplyCard : diffCard).querySelector('.section');
  if(tabs && host && tabs.previousElementSibling !== host) host.insertAdjacentElement('afterend', tabs);
}

function renderAuditDetail(lang){
  var cfg = AUDIT_COINS[auditCoin];
  var coin = COINS[cfg.coin];
  setText('.auditoriaViewTitle', auditNavLabel());
  setText('#auditBack', auditNavLabel());
  var stakeNav = document.querySelectorAll('.nav button:not(#rankingBtn)')[4];
  var stakeNavSpan = stakeNav && stakeNav.querySelector('span');
  setText('.auditCrumbCoin', coin.name + (auditKind === 'stake' && stakeNavSpan ? ' · ' + stakeNavSpan.textContent : ''));
  setText('.auditCoinLabel', cfg.tokenCard ? 'Token BEP-20' : pick(I18N.auditCoinLabel, lang));
  setText('.auditCoinName', coin.name);
  var icon = document.querySelector('.auditCoinIcon');
  if(icon){ icon.src = coin.icon; icon.alt = coin.ticker; }
  applyAuditLayout(cfg);

  fetch(PROXY_BASE + cfg.audit).then(function(r){ return r.json(); }).then(function(data){
    if(auditCoin !== cfg.coin) return;
    if(!data || !data.ok || !data.reading){ if(cfg.rewards) renderAuditRewards(cfg, lang); return; }
    var r = data.reading;
    auditLiveMasternodes = r.masternodesOnline;
    if(cfg.rewards) renderAuditRewards(cfg, lang);
    if(cfg.stakeCard) renderAuditStakeCard(cfg, r, lang);
    if(cfg.miningCard) renderAuditMiningCard(cfg, r, lang);
    if(cfg.tokenCard) renderAuditTokenCard(cfg, r, lang);

    if(cfg.supplyAudit){
      var statusPill = document.querySelector('.auditoriaStatusPill');
      if(statusPill){
        statusPill.textContent = r.withinRule ? pick(I18N.auditStatusOk, lang) : pick(I18N.auditStatusOff, lang);
        statusPill.style.color = r.withinRule ? 'var(--green)' : 'var(--red)';
        statusPill.style.background = r.withinRule ? 'rgba(32,223,132,.12)' : 'rgba(255,91,91,.12)';
        statusPill.style.borderColor = r.withinRule ? 'rgba(32,223,132,.18)' : 'rgba(255,91,91,.3)';
      }
    }

    setText('.auditKpiBlockLabel', pick(I18N.blockHeight, lang));
    setText('.auditKpiBlock', r.height.toLocaleString('en-US'));
    setText('.auditKpiSupplyLabel', pick(I18N[cfg.supplyLabel || 'kpiCirculatingSupply'], lang));
    setText('.auditKpiSupply', Math.round(cfg.supplyAudit ? r.actualSupply : r.supply).toLocaleString('en-US'));
    setText('.auditKpiSupplySub', cfg.unit);
    if(cfg.supplyAudit){
      setText('.auditKpiCapLabel', pick(I18N.kpiEmissionCap, lang));
      setText('.auditKpiCap', Math.round(r.expectedSupply).toLocaleString('en-US'));
      setText('.auditKpiCapSub', r.treasuryMax != null
        ? pick(I18N[cfg.capSub || 'pivxCapSub'], lang).replace('{b}', fmtMillions2(r.blockEmission)).replace('{t}', fmtMillions2(r.treasuryMax))
        : (cfg.tokenCard ? tkT(lang, 22) : pick(I18N.kpiEmissionCapSub, lang)));
    }else{
      setText('.auditKpiCapLabel', pick(I18N.pivxLockedLabel, lang));
      setText('.auditKpiCap', r.lockedPct != null ? r.lockedPct.toFixed(2) + '%' : '—');
      setText('.auditKpiCapSub', pick(I18N.pivxMnCollateral, lang));
    }
    if(cfg.kpi4 === 'hashrate'){
      // Bitcoin: network hash rate; below it, the block subsidy now and after the next halving block
      setText('.auditKpiMnLabel', pick(I18N.kpiHashrate, lang));
      setText('.auditKpiMn', r.hashrate ? fmtHashrate(r.hashrate) : '—');
      setText('.auditKpiMnSub', r.blockSubsidy == null ? '—' : r.nextHalvingHeight != null
        ? r.blockSubsidy + ' ' + cfg.unit + ' → ' + r.nextSubsidy + ' ' + cfg.unit + ' · #' + Number(r.nextHalvingHeight).toLocaleString('en-US')
        : pick(I18N.auditPerBlock, lang).replace('{v}', Number(r.blockSubsidy).toLocaleString('en-US') + ' ' + cfg.unit));
    }else if(cfg.kpi4 === 'inflation'){
      setText('.auditKpiMnLabel', pick(I18N.auditInflationLabel, lang));
      setText('.auditKpiMn', r.inflationRate != null ? (r.inflationRate * 100).toFixed(2) + '%' : '—');
      setText('.auditKpiMnSub', r.epoch != null ? pick(I18N.auditEpochSub, lang).replace('{n}', Number(r.epoch).toLocaleString('en-US'))
        : (r.bnb ? pick(I18N.auditValidatorsLabel, lang) + ': ' + Number(r.bnb.validators).toLocaleString('en-US') : '—'));
    }else if(cfg.kpi4 === 'holders'){
      // token: wallets holding it (from the replay of every transfer) and the share of the ten largest
      var tg = r.ledger || {};
      setText('.auditKpiMnLabel', tkT(lang, 24));
      setText('.auditKpiMn', tg.complete ? Number(tg.holders).toLocaleString('en-US') : '—');
      setText('.auditKpiMnSub', tg.complete ? tkT(lang, 25).replace('{p}', Number(tg.top10Pct).toFixed(2)) : tkT(lang, 17).replace('{p}', Math.floor(tg.progressPct || 0)));
    }else if(auditKind === 'stake'){
      // stake-only view: the fourth figure is what stakers earned in the last 24h (filled by renderAuditRewards)
      setText('.auditKpiMnLabel', pick(I18N.rwStake, lang));
      setText('.auditKpiMnSub', pick(I18N.rwLast24h, lang));
    }else{
      setText('.auditKpiMnLabel', pick(I18N.kpiMasternodes, lang));
      setText('.auditKpiMn', r.masternodesOnline.toLocaleString('en-US'));
      setText('.auditKpiMnSub', pick(I18N.auditOfflineTemplate, lang).replace('{n}', r.masternodesOffline));
    }

    if(cfg.supplyAudit){
      setText('.auditChartTitleEl', pick(I18N.auditChartTitle, lang));
      setText('.auditChartDescEl', pick(I18N.auditChartDesc, lang));
      var chartLegendEl = document.querySelector('.auditChartLegend');
      if(chartLegendEl){
        var legendItem = function(color, radius, label){
          return '<span style="display:inline-flex;align-items:center;gap:7px;color:var(--text2);font-size:13px"><i style="width:11px;height:11px;border-radius:' + radius + ';background:' + color + ';display:inline-block;flex:none"></i>' + label + '</span>';
        };
        chartLegendEl.innerHTML = legendItem('var(--cyan)', '50%', pick(I18N[cfg.supplyLabel || 'kpiCirculatingSupply'], lang)) + legendItem('var(--amber)', '3px', pick(I18N.kpiEmissionCap, lang));
      }
    }

    setText('.auditDifficultyTitleEl', pick(I18N.auditDifficultyChartTitle, lang));
    setText('.auditDifficultyDescEl', pick(I18N.auditDifficultyChartDesc, lang));
    var difficultyLegendEl = document.querySelector('.auditDifficultyLegend');
    if(difficultyLegendEl){
      difficultyLegendEl.innerHTML = '<span style="display:inline-flex;align-items:center;gap:7px;color:var(--text2);font-size:13px"><i style="width:11px;height:11px;border-radius:50%;background:var(--violet);display:inline-block;flex:none"></i>' + pick(I18N.auditDifficultyLabel, lang) + '</span>';
    }

    if(cfg.tokenCard){
      versionsCardEl().style.display = '';
      renderAuditHolders(cfg, r, lang);
    }else if(cfg.miningCard){
      var poolMap = r.mining && r.mining.pools;
      versionsCardEl().style.display = poolMap ? '' : 'none';
      setText('.auditVersionsTitleEl', pick(I18N.miningPools, lang));
      setText('.auditVersionsDescEl', poolMap ? expT('rwBlocks', lang, { n: Number(r.mining.poolsBlocks).toLocaleString('en-US') }) : '');
      setText('.auditVersionsNoteEl', '');
      var poolShown = null;
      if(poolMap){ poolShown = {}; Object.keys(poolMap).forEach(function(k){ poolShown[k === 'Unknown' ? (POOL_UNKNOWN_I18N[lang] || POOL_UNKNOWN_I18N.en) : k] = poolMap[k]; }); }
      renderAuditVersions(poolShown, lang, '');
    }else if(!cfg.noVersions){
      setText('.auditVersionsTitleEl', pick(I18N.auditVersionsTitle, lang));
      setText('.auditVersionsDescEl', pick(I18N.auditVersionsDesc, lang).replace('{n}', r.peerCount));
      setText('.auditVersionsNoteEl', pick(I18N.auditVersionsNote, lang).split('lunariumcoind').join(cfg.daemon));
      renderAuditVersions(r.peerVersions, lang);
    }

    if(cfg.supplyAudit){
      setText('.auditExplainTitleEl', pick(I18N.auditExplainTitle, lang));
      var explain = pick(I18N[cfg.explain], lang);
      if(r.treasuryMax != null){
        explain = explain.replace('{b}', fmtPlain(r.blockEmission)).replace('{t}', fmtPlain(r.treasuryMax))
          .replace('{g}', fmtPlain(Math.max(0, r.expectedSupply - r.actualSupply)));
      }
      // texts written with {g} / {d} (Bitcoin, Solana): the gap to the cap and the day the audit started
      if(cfg.gapDecimals != null){
        explain = explain.replace('{g}', Math.max(0, r.expectedSupply - r.actualSupply).toLocaleString('en-US', { maximumFractionDigits: cfg.gapDecimals }))
          .replace('{d}', r.anchorTs ? new Date(r.anchorTs).toLocaleDateString(lang) : '—')
          .replace('{e}', r.earlyEra ? Number(r.earlyEra.total).toLocaleString('en-US', { maximumFractionDigits: 0 }) : '—');
      }
      // Nodestats: coins at the burn address, circulating supply and the official explorer's own counter
      if(r.burned != null){
        var amt = function(v){ return Number(v).toLocaleString('en-US', { maximumFractionDigits: 2 }); };
        explain = explain.replace('{burn}', amt(r.burned)).replace('{circ}', amt(r.circulating));
        if(cfg.officialNote && r.officialSupply != null && r.officialOffset >= 0.01){
          explain += ' ' + pick(I18N[cfg.officialNote], lang).replace('{ofc}', amt(r.officialSupply)).replace('{o}', amt(r.officialOffset));
        }
      }
      // token: deployment, burns, owner and its share, liquidity lock; the transfer replay once complete
      if(cfg.tokenCard){
        var tp = r.pool || {}, tl = r.ledger || {};
        explain = explain.replace('{d}', new Date(r.deployedAt).toLocaleDateString(lang)).replace('{blk}', Number(r.deployBlock).toLocaleString('en-US'))
          .replace('{burn}', Number(r.burned).toLocaleString('en-US', { maximumFractionDigits: 2 })).replace('{own}', r.ownerRenounced ? '—' : tkShort(r.owner))
          .replace('{op}', Number(r.ownerPct).toFixed(2)).replace('{lp}', Number(Number(tp.lpLockedPct || 0).toFixed(2)).toString())
          .replace('{u}', tp.unlocksAt ? new Date(tp.unlocksAt).toLocaleDateString(lang) : '—');
        if(tl.complete && tl.sumMatches && tl.mintsAfterDeploy === 0){
          explain += ' ' + tkT(lang, 27).replace('{n}', Number(tl.transfers).toLocaleString('en-US')).replace('{h}', Number(tl.holders).toLocaleString('en-US'));
        }
      }
      setText('.auditExplainTextEl', explain);
      setText('.auditExplainLinkEl', pick(I18N.auditExplainLink, lang));
    }

    var footerEl = document.querySelector('.auditFooterEl');
    if(footerEl){
      var lastCheck = new Date(r.ts).toLocaleString(lang);
      var src = cfg.sources ? (pick(I18N.sourcePrefix, lang) + ' ' + cfg.sources + '.') : pick(I18N.auditFooterText, lang);
      footerEl.innerHTML = src + ' ' + pick(I18N.auditFooterRefresh, lang) + '<br>' + pick(I18N.auditLastCheckPrefix, lang) + ' ' + lastCheck;
    }

    auditFullHistory = data.history;
    wireAuditRangeTabs();
    renderAuditChartsForSelectedRange();
  }).catch(function(){});
}

function showAuditPane(detail){
  var list = document.getElementById('auditListPane');
  var det = document.getElementById('auditDetailPane');
  if(list) list.style.display = detail ? 'none' : '';
  if(det) det.style.display = detail ? '' : 'none';
}

function renderAuditoria(){
  var lang = currentLang();
  if(auditCoin) renderAuditDetail(lang); else renderAuditList(lang);
}

function startAuditRefresh(){
  if(auditIntervalId) clearInterval(auditIntervalId);
  renderAuditoria();
  auditIntervalId = setInterval(renderAuditoria, 60000);
}

function showAuditList(){
  auditCoin = null;
  auditKind = null;
  auditLiveMasternodes = null;
  showAuditPane(false);
  initConverterForCoin(false);
  setAuditUrl(null);
  startAuditRefresh();
}

function openAudit(id, kind){
  if(!Object.prototype.hasOwnProperty.call(AUDIT_COINS, id)) return;
  auditCoin = id;
  // only a coin with the masternode / stake rewards split has a stake-only view
  auditKind = kind === 'stake' && AUDIT_COINS[id].rewards ? 'stake' : null;
  auditLiveMasternodes = null;
  auditFullHistory = null;
  ['.auditKpiBlock', '.auditKpiSupply', '.auditKpiCap', '.auditKpiMn', '.auditKpiMnSub'].forEach(function(s){ setText(s, '—'); });
  var grid = document.getElementById('auditRewardsGrid');
  if(grid) grid.innerHTML = '<p class=mini>' + pick(I18N.rwPending, currentLang()) + '</p>';
  showAuditPane(true);
  initConverterForCoin(false);
  var back = document.getElementById('auditBack');
  if(back) back.onclick = showAuditList;
  setAuditUrl(id, auditKind);
  var view = document.getElementById('auditoriaView');
  if(view) view.scrollIntoView({ behavior:'smooth', block:'start' });
  startAuditRefresh();
}

window.GalaxiaRenderAuditoria = showAuditList;
window.GalaxiaOpenAudit = openAudit;

// ---- Documentação / Aviso Legal: static disclaimer page, no live data. Explains that this
// aggregator is not a trading venue, is not financial advice, and disclaims liability. Full text
// per language lives here (not in language-final.js) to keep it next to the render function.
var DISCLAIMER = {
  "pt-BR": {title:"Aviso Legal e Termos de Uso", h:["1. O que é o GaláxiaLunarium","2. Não somos uma exchange ou corretora","3. Não é aconselhamento financeiro","4. Precisão dos dados","5. Isenção de responsabilidade","6. Links e serviços de terceiros","7. Riscos dos ativos digitais","8. Aceitação dos termos"], p:["O GaláxiaLunarium é um agregador de dados públicos sobre a LunariumCoin (XLN) e outros ativos digitais relacionados ao seu ecossistema. Ele reúne e exibe informações provenientes de exploradores de blockchain, exchanges parceiras e APIs públicas de terceiros, com finalidade exclusivamente informativa.","O GaláxiaLunarium não executa ordens, não custodia fundos, não realiza negociações e não atua como intermediário em nenhuma transação. Toda negociação mencionada ou exibida ocorre em plataformas de terceiros, sob responsabilidade exclusiva dessas plataformas.","Nada neste site constitui recomendação de compra, venda ou manutenção de qualquer ativo. As informações são apresentadas apenas para fins informativos e não devem ser interpretadas como aconselhamento de investimento, financeiro, jurídico ou tributário.","Os dados exibidos são obtidos de fontes públicas de terceiros (exploradores de blockchain, exchanges, APIs de mercado) e podem estar desatualizados, incompletos ou incorretos devido a atrasos de rede, instabilidade das fontes ou falhas técnicas. Não garantimos a exatidão, integridade ou disponibilidade contínua dessas informações.","O uso deste site é de inteira responsabilidade do usuário. O GaláxiaLunarium, seus operadores, colaboradores e afiliados não se responsabilizam por perdas financeiras, danos diretos ou indiretos, ou quaisquer consequências decorrentes do uso das informações aqui disponibilizadas ou de decisões tomadas com base nelas.","Este site pode conter links para exchanges, carteiras ou outros serviços de terceiros. Não temos controle sobre essas plataformas e não somos responsáveis por seu conteúdo, segurança, disponibilidade ou práticas. O uso de qualquer serviço de terceiros está sujeito aos termos e políticas dessa própria plataforma.","Ativos digitais são altamente voláteis e envolvem risco significativo, incluindo a possibilidade de perda total do capital investido. Antes de tomar qualquer decisão financeira, procure orientação profissional independente e faça sua própria pesquisa (DYOR).","Ao acessar e utilizar o GaláxiaLunarium, você reconhece que leu, compreendeu e concorda com este Aviso Legal em sua totalidade."]},
  en: {title:"Legal Disclaimer & Terms of Use", h:["1. What GaláxiaLunarium is","2. We are not an exchange or broker","3. This is not financial advice","4. Data accuracy","5. Disclaimer of liability","6. Third-party links and services","7. Digital asset risks","8. Acceptance of terms"], p:["GaláxiaLunarium is a public-data aggregator for LunariumCoin (XLN) and other digital assets related to its ecosystem. It collects and displays information from blockchain explorers, partner exchanges, and public third-party APIs, for informational purposes only.","GaláxiaLunarium does not execute orders, does not hold funds, does not carry out trades, and does not act as an intermediary in any transaction. Any trading mentioned or displayed takes place on third-party platforms, under those platforms' exclusive responsibility.","Nothing on this site constitutes a recommendation to buy, sell, or hold any asset. The information is presented for informational purposes only and should not be interpreted as investment, financial, legal, or tax advice.","The data shown is obtained from public third-party sources (blockchain explorers, exchanges, market APIs) and may be outdated, incomplete, or incorrect due to network delays, source instability, or technical failures. We do not guarantee the accuracy, completeness, or continuous availability of this information.","Use of this site is entirely at the user's own risk. GaláxiaLunarium, its operators, contributors, and affiliates are not liable for any financial loss, direct or indirect damages, or any consequence arising from the use of the information made available here or from decisions made based on it.","This site may contain links to exchanges, wallets, or other third-party services. We have no control over these platforms and are not responsible for their content, security, availability, or practices. Use of any third-party service is subject to that platform's own terms and policies.","Digital assets are highly volatile and carry significant risk, including the possibility of total loss of invested capital. Before making any financial decision, seek independent professional guidance and do your own research (DYOR).","By accessing and using GaláxiaLunarium, you acknowledge that you have read, understood, and agree to this Legal Disclaimer in its entirety."]},
  ru: {title:"Юридическое уведомление и условия использования", h:["1. Что такое GaláxiaLunarium","2. Мы не являемся биржей или брокером","3. Это не финансовый совет","4. Точность данных","5. Отказ от ответственности","6. Ссылки и сервисы третьих сторон","7. Риски цифровых активов","8. Принятие условий"], p:["GaláxiaLunarium — это агрегатор публичных данных о LunariumCoin (XLN) и других цифровых активах, связанных с её экосистемой. Он собирает и отображает информацию из блокчейн-обозревателей, партнёрских бирж и публичных API третьих сторон исключительно в информационных целях.","GaláxiaLunarium не исполняет ордера, не хранит средства, не проводит сделки и не выступает посредником ни в одной транзакции. Любая упомянутая или отображаемая торговля происходит на платформах третьих сторон под их исключительную ответственность.","Ничто на этом сайте не является рекомендацией покупать, продавать или держать какой-либо актив. Информация предоставляется исключительно в информационных целях и не должна расцениваться как инвестиционная, финансовая, юридическая или налоговая консультация.","Отображаемые данные получены из публичных источников третьих сторон (блокчейн-обозреватели, биржи, рыночные API) и могут быть устаревшими, неполными или неверными из-за задержек сети, нестабильности источников или технических сбоев. Мы не гарантируем точность, полноту или постоянную доступность этой информации.","Использование этого сайта осуществляется исключительно на риск пользователя. GaláxiaLunarium, его операторы, сотрудники и аффилированные лица не несут ответственности за какие-либо финансовые потери, прямой или косвенный ущерб, а также любые последствия использования представленной здесь информации или решений, принятых на её основе.","Этот сайт может содержать ссылки на биржи, кошельки или другие сервисы третьих сторон. Мы не контролируем эти платформы и не несём ответственности за их содержание, безопасность, доступность или практики. Использование любого стороннего сервиса регулируется собственными условиями и политиками этой платформы.","Цифровые активы отличаются высокой волатильностью и сопряжены со значительным риском, включая возможность полной потери вложенного капитала. Прежде чем принимать какое-либо финансовое решение, обратитесь за независимой профессиональной консультацией и проведите собственное исследование (DYOR).","Заходя на сайт GaláxiaLunarium и используя его, вы подтверждаете, что прочитали, поняли и полностью согласны с настоящим Юридическим уведомлением."]},
  de: {title:"Rechtlicher Hinweis und Nutzungsbedingungen", h:["1. Was GaláxiaLunarium ist","2. Wir sind keine Börse oder Broker","3. Dies ist keine Finanzberatung","4. Genauigkeit der Daten","5. Haftungsausschluss","6. Links und Dienste Dritter","7. Risiken digitaler Assets","8. Annahme der Bedingungen"], p:["GaláxiaLunarium ist ein Aggregator öffentlicher Daten zu LunariumCoin (XLN) und anderen digitalen Assets seines Ökosystems. Die Plattform sammelt und zeigt Informationen aus Blockchain-Explorern, Partnerbörsen und öffentlichen Drittanbieter-APIs ausschließlich zu Informationszwecken.","GaláxiaLunarium führt keine Orders aus, verwahrt keine Gelder, wickelt keine Trades ab und tritt bei keiner Transaktion als Vermittler auf. Jeglicher erwähnte oder angezeigte Handel findet auf Plattformen Dritter statt, die dafür allein verantwortlich sind.","Nichts auf dieser Website stellt eine Empfehlung zum Kauf, Verkauf oder Halten eines Assets dar. Die Informationen dienen ausschließlich Informationszwecken und sind nicht als Anlage-, Finanz-, Rechts- oder Steuerberatung zu verstehen.","Die angezeigten Daten stammen aus öffentlichen Quellen Dritter (Blockchain-Explorer, Börsen, Markt-APIs) und können aufgrund von Netzwerkverzögerungen, Instabilität der Quellen oder technischen Störungen veraltet, unvollständig oder falsch sein. Wir garantieren weder die Richtigkeit, Vollständigkeit noch die durchgehende Verfügbarkeit dieser Informationen.","Die Nutzung dieser Website erfolgt vollständig auf eigenes Risiko des Nutzers. GaláxiaLunarium, seine Betreiber, Mitwirkenden und verbundenen Unternehmen haften nicht für finanzielle Verluste, direkte oder indirekte Schäden oder sonstige Folgen, die sich aus der Nutzung der hier bereitgestellten Informationen oder aus darauf basierenden Entscheidungen ergeben.","Diese Website kann Links zu Börsen, Wallets oder anderen Diensten Dritter enthalten. Wir haben keine Kontrolle über diese Plattformen und sind nicht verantwortlich für deren Inhalt, Sicherheit, Verfügbarkeit oder Praktiken. Die Nutzung jedes Drittanbieterdienstes unterliegt dessen eigenen Bedingungen und Richtlinien.","Digitale Assets sind sehr volatil und bergen erhebliche Risiken, einschließlich des möglichen Totalverlusts des investierten Kapitals. Holen Sie vor jeder Finanzentscheidung unabhängigen fachlichen Rat ein und führen Sie eigene Recherchen durch (DYOR).","Durch den Zugriff auf GaláxiaLunarium und dessen Nutzung bestätigen Sie, dass Sie diesen rechtlichen Hinweis vollständig gelesen, verstanden und akzeptiert haben."]},
  pl: {title:"Informacja prawna i warunki korzystania", h:["1. Czym jest GaláxiaLunarium","2. Nie jesteśmy giełdą ani brokerem","3. To nie jest porada finansowa","4. Dokładność danych","5. Wyłączenie odpowiedzialności","6. Linki i usługi stron trzecich","7. Ryzyko aktywów cyfrowych","8. Akceptacja warunków"], p:["GaláxiaLunarium to agregator publicznych danych dotyczących LunariumCoin (XLN) i innych aktywów cyfrowych związanych z jej ekosystemem. Zbiera i wyświetla informacje pochodzące z eksploratorów blockchain, giełd partnerskich oraz publicznych API stron trzecich, wyłącznie w celach informacyjnych.","GaláxiaLunarium nie realizuje zleceń, nie przechowuje środków, nie przeprowadza transakcji ani nie działa jako pośrednik w żadnej transakcji. Każdy wspomniany lub wyświetlany handel odbywa się na platformach stron trzecich, na ich wyłączną odpowiedzialność.","Nic na tej stronie nie stanowi rekomendacji kupna, sprzedaży ani utrzymywania jakiegokolwiek aktywa. Informacje mają charakter wyłącznie informacyjny i nie powinny być interpretowane jako doradztwo inwestycyjne, finansowe, prawne ani podatkowe.","Wyświetlane dane pochodzą z publicznych źródeł stron trzecich (eksploratorów blockchain, giełd, API rynkowych) i mogą być nieaktualne, niekompletne lub błędne z powodu opóźnień sieciowych, niestabilności źródeł lub awarii technicznych. Nie gwarantujemy dokładności, kompletności ani ciągłej dostępności tych informacji.","Korzystanie z tej strony odbywa się na wyłączne ryzyko użytkownika. GaláxiaLunarium, jego operatorzy, współpracownicy i podmioty powiązane nie ponoszą odpowiedzialności za jakiekolwiek straty finansowe, szkody bezpośrednie lub pośrednie, ani żadne konsekwencje wynikające z korzystania z udostępnionych tu informacji lub z decyzji podjętych na ich podstawie.","Ta strona może zawierać linki do giełd, portfeli lub innych usług stron trzecich. Nie mamy kontroli nad tymi platformami i nie odpowiadamy za ich treść, bezpieczeństwo, dostępność ani praktyki. Korzystanie z jakiejkolwiek usługi strony trzeciej podlega własnym warunkom i zasadom tej platformy.","Aktywa cyfrowe charakteryzują się wysoką zmiennością i wiążą się ze znacznym ryzykiem, w tym możliwością całkowitej utraty zainwestowanego kapitału. Przed podjęciem jakiejkolwiek decyzji finansowej zasięgnij niezależnej porady profesjonalnej i przeprowadź własne badania (DYOR).","Uzyskując dostęp do GaláxiaLunarium i korzystając z niego, potwierdzasz, że przeczytałeś, zrozumiałeś i w pełni akceptujesz niniejszą Informację prawną."]},
  es: {title:"Aviso Legal y Términos de Uso", h:["1. Qué es GaláxiaLunarium","2. No somos un exchange ni un bróker","3. Esto no es asesoramiento financiero","4. Precisión de los datos","5. Exención de responsabilidad","6. Enlaces y servicios de terceros","7. Riesgos de los activos digitales","8. Aceptación de los términos"], p:["GaláxiaLunarium es un agregador de datos públicos sobre LunariumCoin (XLN) y otros activos digitales relacionados con su ecosistema. Recopila y muestra información procedente de exploradores de blockchain, exchanges asociados y APIs públicas de terceros, con fines exclusivamente informativos.","GaláxiaLunarium no ejecuta órdenes, no custodia fondos, no realiza operaciones y no actúa como intermediario en ninguna transacción. Cualquier operación mencionada o mostrada ocurre en plataformas de terceros, bajo la responsabilidad exclusiva de esas plataformas.","Nada en este sitio constituye una recomendación de compra, venta o mantenimiento de ningún activo. La información se presenta únicamente con fines informativos y no debe interpretarse como asesoramiento de inversión, financiero, legal o fiscal.","Los datos mostrados se obtienen de fuentes públicas de terceros (exploradores de blockchain, exchanges, APIs de mercado) y pueden estar desactualizados, incompletos o ser incorrectos debido a retrasos de red, inestabilidad de las fuentes o fallos técnicos. No garantizamos la exactitud, integridad ni disponibilidad continua de esta información.","El uso de este sitio es responsabilidad exclusiva del usuario. GaláxiaLunarium, sus operadores, colaboradores y afiliados no se responsabilizan de pérdidas financieras, daños directos o indirectos, ni de ninguna consecuencia derivada del uso de la información aquí disponible o de decisiones tomadas con base en ella.","Este sitio puede contener enlaces a exchanges, billeteras u otros servicios de terceros. No tenemos control sobre estas plataformas y no somos responsables de su contenido, seguridad, disponibilidad o prácticas. El uso de cualquier servicio de terceros está sujeto a los propios términos y políticas de esa plataforma.","Los activos digitales son altamente volátiles e implican un riesgo significativo, incluida la posibilidad de pérdida total del capital invertido. Antes de tomar cualquier decisión financiera, busque asesoramiento profesional independiente y realice su propia investigación (DYOR).","Al acceder y utilizar GaláxiaLunarium, usted reconoce haber leído, comprendido y aceptado este Aviso Legal en su totalidad."]},
  vi: {title:"Tuyên bố Pháp lý và Điều khoản Sử dụng", h:["1. GaláxiaLunarium là gì","2. Chúng tôi không phải là sàn giao dịch hay nhà môi giới","3. Đây không phải là lời khuyên tài chính","4. Độ chính xác của dữ liệu","5. Miễn trừ trách nhiệm","6. Liên kết và dịch vụ của bên thứ ba","7. Rủi ro của tài sản kỹ thuật số","8. Chấp nhận điều khoản"], p:["GaláxiaLunarium là nền tảng tổng hợp dữ liệu công khai về LunariumCoin (XLN) và các tài sản kỹ thuật số khác liên quan đến hệ sinh thái của nó. Nền tảng thu thập và hiển thị thông tin từ các trình khám phá blockchain, sàn giao dịch đối tác và API công khai của bên thứ ba, chỉ nhằm mục đích cung cấp thông tin.","GaláxiaLunarium không thực hiện lệnh, không giữ tiền, không thực hiện giao dịch và không đóng vai trò trung gian trong bất kỳ giao dịch nào. Mọi giao dịch được đề cập hoặc hiển thị đều diễn ra trên các nền tảng của bên thứ ba, thuộc trách nhiệm riêng của các nền tảng đó.","Không có nội dung nào trên trang này cấu thành khuyến nghị mua, bán hoặc nắm giữ bất kỳ tài sản nào. Thông tin được trình bày chỉ nhằm mục đích cung cấp thông tin và không nên được hiểu là lời khuyên đầu tư, tài chính, pháp lý hoặc thuế.","Dữ liệu hiển thị được lấy từ các nguồn công khai của bên thứ ba (trình khám phá blockchain, sàn giao dịch, API thị trường) và có thể lỗi thời, không đầy đủ hoặc không chính xác do độ trễ mạng, sự không ổn định của nguồn hoặc sự cố kỹ thuật. Chúng tôi không đảm bảo tính chính xác, đầy đủ hoặc tính khả dụng liên tục của thông tin này.","Việc sử dụng trang này hoàn toàn do người dùng tự chịu rủi ro. GaláxiaLunarium, các nhà vận hành, cộng tác viên và các bên liên kết không chịu trách nhiệm về bất kỳ tổn thất tài chính, thiệt hại trực tiếp hoặc gián tiếp, hoặc bất kỳ hậu quả nào phát sinh từ việc sử dụng thông tin được cung cấp tại đây hoặc từ các quyết định dựa trên đó.","Trang này có thể chứa liên kết đến các sàn giao dịch, ví hoặc dịch vụ khác của bên thứ ba. Chúng tôi không kiểm soát các nền tảng này và không chịu trách nhiệm về nội dung, bảo mật, tính khả dụng hoặc cách thức hoạt động của chúng. Việc sử dụng bất kỳ dịch vụ bên thứ ba nào đều tuân theo các điều khoản và chính sách riêng của nền tảng đó.","Tài sản kỹ thuật số có tính biến động cao và tiềm ẩn rủi ro đáng kể, bao gồm khả năng mất toàn bộ vốn đầu tư. Trước khi đưa ra bất kỳ quyết định tài chính nào, hãy tìm kiếm lời khuyên chuyên môn độc lập và tự nghiên cứu (DYOR).","Khi truy cập và sử dụng GaláxiaLunarium, bạn xác nhận đã đọc, hiểu và đồng ý hoàn toàn với Tuyên bố Pháp lý này."]},
  fr: {title:"Avis Juridique et Conditions d'Utilisation", h:["1. Qu'est-ce que GaláxiaLunarium","2. Nous ne sommes pas un exchange ni un courtier","3. Ceci n'est pas un conseil financier","4. Exactitude des données","5. Exclusion de responsabilité","6. Liens et services tiers","7. Risques liés aux actifs numériques","8. Acceptation des conditions"], p:["GaláxiaLunarium est un agrégateur de données publiques sur LunariumCoin (XLN) et d'autres actifs numériques liés à son écosystème. Il collecte et affiche des informations provenant d'explorateurs de blockchain, d'exchanges partenaires et d'API publiques de tiers, à des fins purement informatives.","GaláxiaLunarium n'exécute aucun ordre, ne conserve aucun fonds, n'effectue aucune transaction et n'agit comme intermédiaire dans aucune opération. Toute transaction mentionnée ou affichée a lieu sur des plateformes tierces, sous leur seule responsabilité.","Rien sur ce site ne constitue une recommandation d'achat, de vente ou de conservation d'un actif. Les informations sont présentées à titre purement informatif et ne doivent pas être interprétées comme un conseil en investissement, financier, juridique ou fiscal.","Les données affichées proviennent de sources publiques tierces (explorateurs de blockchain, exchanges, API de marché) et peuvent être obsolètes, incomplètes ou incorrectes en raison de retards réseau, d'instabilité des sources ou de défaillances techniques. Nous ne garantissons ni l'exactitude, ni l'exhaustivité, ni la disponibilité continue de ces informations.","L'utilisation de ce site se fait entièrement aux risques de l'utilisateur. GaláxiaLunarium, ses opérateurs, contributeurs et affiliés déclinent toute responsabilité pour toute perte financière, dommage direct ou indirect, ou toute conséquence résultant de l'utilisation des informations mises à disposition ici ou de décisions prises sur cette base.","Ce site peut contenir des liens vers des exchanges, portefeuilles ou autres services tiers. Nous n'avons aucun contrôle sur ces plateformes et ne sommes pas responsables de leur contenu, de leur sécurité, de leur disponibilité ou de leurs pratiques. L'utilisation de tout service tiers est soumise aux propres conditions et politiques de cette plateforme.","Les actifs numériques sont hautement volatils et comportent un risque important, y compris la possibilité d'une perte totale du capital investi. Avant de prendre toute décision financière, demandez conseil à un professionnel indépendant et menez vos propres recherches (DYOR).","En accédant à GaláxiaLunarium et en l'utilisant, vous reconnaissez avoir lu, compris et accepté cet Avis Juridique dans son intégralité."]},
  ar: {title:"إخلاء المسؤولية القانونية وشروط الاستخدام", h:["1. ما هو GaláxiaLunarium","2. لسنا منصة تداول أو وسيطًا","3. هذا ليس نصيحة مالية","4. دقة البيانات","5. إخلاء المسؤولية","6. الروابط وخدمات الجهات الخارجية","7. مخاطر الأصول الرقمية","8. قبول الشروط"], p:["GaláxiaLunarium هو مجمّع بيانات عامة حول LunariumCoin (XLN) والأصول الرقمية الأخرى المرتبطة بنظامها البيئي. يقوم بجمع وعرض معلومات من مستكشفات البلوك تشين، والمنصات الشريكة، وواجهات برمجة تطبيقات عامة تابعة لجهات خارجية، وذلك لأغراض إعلامية فقط.","لا يقوم GaláxiaLunarium بتنفيذ الأوامر، ولا يحتفظ بالأموال، ولا يجري أي صفقات، ولا يعمل كوسيط في أي معاملة. أي تداول مذكور أو معروض يتم على منصات تابعة لجهات خارجية، تحت مسؤوليتها الحصرية.","لا يشكل أي شيء في هذا الموقع توصية بشراء أو بيع أو الاحتفاظ بأي أصل. تُقدَّم المعلومات لأغراض إعلامية فقط ولا ينبغي تفسيرها كنصيحة استثمارية أو مالية أو قانونية أو ضريبية.","يتم الحصول على البيانات المعروضة من مصادر عامة تابعة لجهات خارجية (مستكشفات البلوك تشين، المنصات، واجهات برمجة تطبيقات السوق) وقد تكون قديمة أو غير مكتملة أو غير صحيحة بسبب تأخيرات الشبكة أو عدم استقرار المصادر أو الأعطال التقنية. نحن لا نضمن دقة هذه المعلومات أو اكتمالها أو توفرها المستمر.","استخدام هذا الموقع يقع بالكامل على مسؤولية المستخدم. لا يتحمل GaláxiaLunarium ومشغّلوه والمساهمون فيه والشركات التابعة له أي مسؤولية عن أي خسارة مالية أو أضرار مباشرة أو غير مباشرة، أو أي عواقب ناتجة عن استخدام المعلومات المتاحة هنا أو عن قرارات اتُخذت بناءً عليها.","قد يحتوي هذا الموقع على روابط لمنصات أو محافظ أو خدمات أخرى تابعة لجهات خارجية. ليس لدينا أي سيطرة على هذه المنصات ولسنا مسؤولين عن محتواها أو أمانها أو توفرها أو ممارساتها. يخضع استخدام أي خدمة تابعة لجهة خارجية لشروط وسياسات تلك المنصة الخاصة بها.","تتميز الأصول الرقمية بتقلب شديد وتنطوي على مخاطر كبيرة، بما في ذلك احتمال خسارة كامل رأس المال المستثمر. قبل اتخاذ أي قرار مالي، اطلب استشارة مهنية مستقلة وقم بإجراء بحثك الخاص (DYOR).","من خلال الوصول إلى GaláxiaLunarium واستخدامه، فإنك تقر بأنك قرأت وفهمت ووافقت على هذا الإخلاء القانوني بالكامل."]},
  bg: {title:"Правно уведомление и Условия за ползване", h:["1. Какво е GaláxiaLunarium","2. Не сме борса или брокер","3. Това не е финансов съвет","4. Точност на данните","5. Отказ от отговорност","6. Връзки и услуги на трети страни","7. Рискове на цифровите активи","8. Приемане на условията"], p:["GaláxiaLunarium е агрегатор на публични данни за LunariumCoin (XLN) и други цифрови активи, свързани с нейната екосистема. Той събира и показва информация от блокчейн експлорери, партньорски борси и публични API на трети страни, единствено с информационна цел.","GaláxiaLunarium не изпълнява поръчки, не съхранява средства, не извършва сделки и не действа като посредник в никаква транзакция. Всяка спомената или показана търговия се извършва на платформи на трети страни, под тяхна изключителна отговорност.","Нищо на този сайт не представлява препоръка за покупка, продажба или задържане на какъвто и да е актив. Информацията се предоставя единствено с информационна цел и не трябва да се тълкува като инвестиционен, финансов, правен или данъчен съвет.","Показаните данни са получени от публични източници на трети страни (блокчейн експлорери, борси, пазарни API) и може да са остарели, непълни или неточни поради мрежови забавяния, нестабилност на източниците или технически повреди. Ние не гарантираме точността, пълнотата или непрекъснатата достъпност на тази информация.","Използването на този сайт е изцяло на риск на потребителя. GaláxiaLunarium, неговите оператори, сътрудници и свързани лица не носят отговорност за каквито и да е финансови загуби, преки или косвени щети, или каквито и да е последици, произтичащи от използването на предоставената тук информация или от решения, взети въз основа на нея.","Този сайт може да съдържа връзки към борси, портфейли или други услуги на трети страни. Нямаме контрол върху тези платформи и не носим отговорност за тяхното съдържание, сигурност, наличност или практики. Използването на всяка услуга на трета страна се урежда от собствените условия и политики на тази платформа.","Цифровите активи са силно волатилни и носят значителен риск, включително възможността за пълна загуба на инвестирания капитал. Преди да вземете каквото и да е финансово решение, потърсете независим професионален съвет и направете собствено проучване (DYOR).","С достъпа до GaláxiaLunarium и използването му, вие потвърждавате, че сте прочели, разбрали и приемате изцяло настоящото Правно уведомление."]},
  cs: {title:"Právní upozornění a podmínky použití", h:["1. Co je GaláxiaLunarium","2. Nejsme burza ani makléř","3. Toto není finanční poradenství","4. Přesnost dat","5. Vyloučení odpovědnosti","6. Odkazy a služby třetích stran","7. Rizika digitálních aktiv","8. Přijetí podmínek"], p:["GaláxiaLunarium je agregátor veřejných dat o LunariumCoin (XLN) a dalších digitálních aktivech souvisejících s jejím ekosystémem. Shromažďuje a zobrazuje informace z blockchain exploreru, partnerských burz a veřejných API třetích stran, výhradně pro informační účely.","GaláxiaLunarium neprovádí žádné pokyny, neuchovává žádné prostředky, neprovádí žádné obchody a nevystupuje jako zprostředkovatel v žádné transakci. Veškeré zmíněné nebo zobrazené obchodování probíhá na platformách třetích stran, na jejich výhradní odpovědnost.","Nic na tomto webu nepředstavuje doporučení ke koupi, prodeji nebo držení jakéhokoli aktiva. Informace jsou uváděny výhradně pro informační účely a neměly by být vykládány jako investiční, finanční, právní nebo daňové poradenství.","Zobrazená data pocházejí z veřejných zdrojů třetích stran (blockchain explorery, burzy, tržní API) a mohou být zastaralá, neúplná nebo nesprávná kvůli síťovým zpožděním, nestabilitě zdrojů nebo technickým poruchám. Nezaručujeme přesnost, úplnost ani nepřetržitou dostupnost těchto informací.","Používání tohoto webu je zcela na riziko uživatele. GaláxiaLunarium, jeho provozovatelé, přispěvatelé a přidružené subjekty nenesou odpovědnost za jakoukoli finanční ztrátu, přímé či nepřímé škody nebo jakékoli důsledky vyplývající z použití zde poskytnutých informací nebo z rozhodnutí na jejich základě.","Tento web může obsahovat odkazy na burzy, peněženky nebo jiné služby třetích stran. Nemáme žádnou kontrolu nad těmito platformami a nejsme odpovědní za jejich obsah, bezpečnost, dostupnost ani praktiky. Používání jakékoli služby třetí strany podléhá vlastním podmínkám a zásadám dané platformy.","Digitální aktiva jsou vysoce volatilní a nesou značné riziko, včetně možnosti úplné ztráty investovaného kapitálu. Před jakýmkoli finančním rozhodnutím vyhledejte nezávislé odborné poradenství a proveďte si vlastní průzkum (DYOR).","Přístupem na GaláxiaLunarium a jeho používáním potvrzujete, že jste si přečetli, porozuměli a plně souhlasíte s tímto Právním upozorněním."]},
  da: {title:"Juridisk Meddelelse og Brugsbetingelser", h:["1. Hvad GaláxiaLunarium er","2. Vi er ikke en børs eller mægler","3. Dette er ikke finansiel rådgivning","4. Datanøjagtighed","5. Ansvarsfraskrivelse","6. Links og tredjepartstjenester","7. Risici ved digitale aktiver","8. Accept af betingelserne"], p:["GaláxiaLunarium er en aggregator af offentlige data om LunariumCoin (XLN) og andre digitale aktiver relateret til dets økosystem. Den indsamler og viser information fra blockchain-explorere, partnerbørser og offentlige tredjeparts-API'er udelukkende til informationsformål.","GaláxiaLunarium udfører ikke ordrer, opbevarer ikke midler, foretager ikke handler og fungerer ikke som mellemmand i nogen transaktion. Enhver nævnt eller vist handel finder sted på tredjepartsplatforme under disse platformes eget ansvar.","Intet på dette site udgør en anbefaling om at købe, sælge eller beholde noget aktiv. Oplysningerne præsenteres udelukkende til informationsformål og bør ikke fortolkes som investerings-, finansiel, juridisk eller skattemæssig rådgivning.","De viste data indhentes fra offentlige tredjepartskilder (blockchain-explorere, børser, markeds-API'er) og kan være forældede, ufuldstændige eller forkerte på grund af netværksforsinkelser, ustabile kilder eller tekniske fejl. Vi garanterer hverken nøjagtigheden, fuldstændigheden eller den kontinuerlige tilgængelighed af disse oplysninger.","Brugen af dette site sker udelukkende på brugerens egen risiko. GaláxiaLunarium, dets operatører, bidragydere og tilknyttede parter er ikke ansvarlige for økonomisk tab, direkte eller indirekte skader eller nogen konsekvens som følge af brugen af de her tilgængelige oplysninger eller af beslutninger truffet på dette grundlag.","Dette site kan indeholde links til børser, wallets eller andre tredjepartstjenester. Vi har ingen kontrol over disse platforme og er ikke ansvarlige for deres indhold, sikkerhed, tilgængelighed eller praksis. Brug af enhver tredjepartstjeneste er underlagt den pågældende platforms egne betingelser og politikker.","Digitale aktiver er meget volatile og indebærer betydelig risiko, herunder muligheden for totalt tab af investeret kapital. Søg uafhængig professionel rådgivning og lav din egen research (DYOR), inden du træffer nogen finansiel beslutning.","Ved at tilgå og bruge GaláxiaLunarium anerkender du, at du har læst, forstået og accepteret denne Juridiske Meddelelse i sin helhed."]},
  el: {title:"Νομική Ανακοίνωση και Όροι Χρήσης", h:["1. Τι είναι το GaláxiaLunarium","2. Δεν είμαστε ανταλλακτήριο ή χρηματομεσίτης","3. Αυτό δεν είναι επενδυτική συμβουλή","4. Ακρίβεια δεδομένων","5. Αποποίηση ευθύνης","6. Σύνδεσμοι και υπηρεσίες τρίτων","7. Κίνδυνοι ψηφιακών περιουσιακών στοιχείων","8. Αποδοχή όρων"], p:["Το GaláxiaLunarium είναι ένας συγκεντρωτής δημόσιων δεδομένων για το LunariumCoin (XLN) και άλλα ψηφιακά περιουσιακά στοιχεία που σχετίζονται με το οικοσύστημά του. Συλλέγει και εμφανίζει πληροφορίες από εξερευνητές blockchain, συνεργαζόμενα ανταλλακτήρια και δημόσια API τρίτων, αποκλειστικά για ενημερωτικούς σκοπούς.","Το GaláxiaLunarium δεν εκτελεί εντολές, δεν κατέχει κεφάλαια, δεν πραγματοποιεί συναλλαγές και δεν λειτουργεί ως μεσάζων σε καμία συναλλαγή. Οποιαδήποτε αναφερόμενη ή εμφανιζόμενη συναλλαγή πραγματοποιείται σε πλατφόρμες τρίτων, υπό την αποκλειστική τους ευθύνη.","Τίποτα σε αυτόν τον ιστότοπο δεν αποτελεί σύσταση αγοράς, πώλησης ή διακράτησης οποιουδήποτε περιουσιακού στοιχείου. Οι πληροφορίες παρουσιάζονται αποκλειστικά για ενημερωτικούς σκοπούς και δεν πρέπει να ερμηνεύονται ως επενδυτική, οικονομική, νομική ή φορολογική συμβουλή.","Τα εμφανιζόμενα δεδομένα λαμβάνονται από δημόσιες πηγές τρίτων (εξερευνητές blockchain, ανταλλακτήρια, API αγοράς) και ενδέχεται να είναι ξεπερασμένα, ελλιπή ή εσφαλμένα λόγω καθυστερήσεων δικτύου, αστάθειας πηγών ή τεχνικών βλαβών. Δεν εγγυόμαστε την ακρίβεια, την πληρότητα ή τη συνεχή διαθεσιμότητα αυτών των πληροφοριών.","Η χρήση αυτού του ιστότοπου γίνεται αποκλειστικά με ευθύνη του χρήστη. Το GaláxiaLunarium, οι διαχειριστές του, οι συνεργάτες και οι συνδεδεμένες οντότητες δεν φέρουν καμία ευθύνη για οποιαδήποτε οικονομική απώλεια, άμεση ή έμμεση ζημία, ή οποιαδήποτε συνέπεια που προκύπτει από τη χρήση των πληροφοριών που διατίθενται εδώ ή από αποφάσεις που λαμβάνονται με βάση αυτές.","Αυτός ο ιστότοπος ενδέχεται να περιέχει συνδέσμους προς ανταλλακτήρια, πορτοφόλια ή άλλες υπηρεσίες τρίτων. Δεν έχουμε κανέναν έλεγχο σε αυτές τις πλατφόρμες και δεν είμαστε υπεύθυνοι για το περιεχόμενο, την ασφάλεια, τη διαθεσιμότητα ή τις πρακτικές τους. Η χρήση οποιασδήποτε υπηρεσίας τρίτου υπόκειται στους δικούς της όρους και πολιτικές αυτής της πλατφόρμας.","Τα ψηφιακά περιουσιακά στοιχεία είναι εξαιρετικά ασταθή και ενέχουν σημαντικό κίνδυνο, συμπεριλαμβανομένης της πιθανότητας ολικής απώλειας του επενδυμένου κεφαλαίου. Πριν λάβετε οποιαδήποτε οικονομική απόφαση, αναζητήστε ανεξάρτητη επαγγελματική καθοδήγηση και κάντε τη δική σας έρευνα (DYOR).","Με την πρόσβαση και τη χρήση του GaláxiaLunarium, αναγνωρίζετε ότι έχετε διαβάσει, κατανοήσει και αποδεχτεί πλήρως αυτήν τη Νομική Ανακοίνωση."]},
  fi: {title:"Oikeudellinen huomautus ja käyttöehdot", h:["1. Mikä GaláxiaLunarium on","2. Emme ole pörssi tai välittäjä","3. Tämä ei ole sijoitusneuvontaa","4. Tietojen tarkkuus","5. Vastuuvapauslauseke","6. Kolmansien osapuolten linkit ja palvelut","7. Digitaalisten omaisuuserien riskit","8. Ehtojen hyväksyminen"], p:["GaláxiaLunarium on julkisen datan koontipalvelu LunariumCoinista (XLN) ja muista sen ekosysteemiin liittyvistä digitaalisista omaisuuseristä. Se kerää ja näyttää tietoa lohkoketjuselaimista, kumppanipörsseistä ja julkisista kolmansien osapuolten rajapinnoista pelkästään tiedotustarkoituksessa.","GaláxiaLunarium ei toteuta toimeksiantoja, ei säilytä varoja, ei suorita kauppoja eikä toimi välittäjänä missään liiketoimessa. Kaikki mainittu tai näytetty kaupankäynti tapahtuu kolmansien osapuolten alustoilla, niiden omalla vastuulla.","Mikään tällä sivustolla ei ole suositus ostaa, myydä tai pitää mitään omaisuuserää. Tiedot esitetään pelkästään tiedotustarkoituksessa, eikä niitä tule tulkita sijoitus-, talous-, oikeudelliseksi tai veroneuvonnaksi.","Näytetyt tiedot on hankittu julkisista kolmansien osapuolten lähteistä (lohkoketjuselaimet, pörssit, markkinarajapinnat) ja ne voivat olla vanhentuneita, puutteellisia tai virheellisiä verkon viiveiden, lähteiden epävakauden tai teknisten häiriöiden vuoksi. Emme takaa näiden tietojen tarkkuutta, täydellisyyttä tai jatkuvaa saatavuutta.","Tämän sivuston käyttö tapahtuu täysin käyttäjän omalla vastuulla. GaláxiaLunarium, sen ylläpitäjät, avustajat ja yhteistyökumppanit eivät vastaa mistään taloudellisesta menetyksestä, suorasta tai epäsuorasta vahingosta tai muusta seurauksesta, joka aiheutuu täällä saatavilla olevien tietojen käytöstä tai niiden perusteella tehdyistä päätöksistä.","Tämä sivusto voi sisältää linkkejä pörsseihin, lompakoihin tai muihin kolmansien osapuolten palveluihin. Meillä ei ole hallintaa näihin alustoihin, emmekä vastaa niiden sisällöstä, turvallisuudesta, saatavuudesta tai käytännöistä. Minkä tahansa kolmannen osapuolen palvelun käyttöä koskevat kyseisen alustan omat ehdot ja käytännöt.","Digitaaliset omaisuuserät ovat erittäin volatiileja ja niihin liittyy merkittävä riski, mukaan lukien mahdollisuus menettää sijoitettu pääoma kokonaan. Hanki riippumatonta ammattilaisneuvontaa ja tee oma tutkimuksesi (DYOR) ennen minkään taloudellisen päätöksen tekemistä.","Käyttämällä GaláxiaLunariumia vahvistat lukeneesi, ymmärtäneesi ja hyväksyväsi tämän oikeudellisen huomautuksen kokonaisuudessaan."]},
  he: {title:"הצהרה משפטית ותנאי שימוש", h:["1. מהו GaláxiaLunarium","2. אנחנו לא בורסה או מתווך","3. זו אינה ייעוץ פיננסי","4. דיוק הנתונים","5. כתב ויתור על אחריות","6. קישורים ושירותי צד שלישי","7. סיכוני נכסים דיגיטליים","8. קבלת התנאים"], p:["GaláxiaLunarium הוא מצבר נתונים ציבוריים עבור LunariumCoin (XLN) ונכסים דיגיטליים נוספים הקשורים למערכת האקולוגית שלו. הוא אוסף ומציג מידע מסייר בלוקצ'יין, בורסות שותפות וממשקי API ציבוריים של צד שלישי, למטרות מידע בלבד.","GaláxiaLunarium אינו מבצע פקודות, אינו מחזיק כספים, אינו מבצע עסקאות ואינו פועל כמתווך בשום עסקה. כל מסחר המוזכר או המוצג מתבצע בפלטפורמות של צד שלישי, באחריותן הבלעדית.","שום דבר באתר זה אינו מהווה המלצה לקנות, למכור או להחזיק בכל נכס. המידע מוצג למטרות מידע בלבד ואין לפרש אותו כייעוץ השקעות, פיננסי, משפטי או מס.","הנתונים המוצגים מתקבלים ממקורות ציבוריים של צד שלישי (סייר בלוקצ'יין, בורסות, ממשקי API של שוק) ועשויים להיות מיושנים, חלקיים או שגויים עקב עיכובי רשת, חוסר יציבות של המקורות או תקלות טכניות. איננו מבטיחים את הדיוק, השלמות או הזמינות הרציפה של מידע זה.","השימוש באתר זה הוא באחריותו הבלעדית של המשתמש. GaláxiaLunarium, המפעילים, התורמים והגורמים המסונפים שלו אינם אחראים לכל הפסד כספי, נזק ישיר או עקיף, או כל תוצאה הנובעת משימוש במידע הזמין כאן או מהחלטות שהתקבלו על בסיסו.","אתר זה עשוי להכיל קישורים לבורסות, ארנקים או שירותי צד שלישי אחרים. אין לנו שליטה על פלטפורמות אלו ואיננו אחראים לתוכן, לאבטחה, לזמינות או לנהלים שלהן. השימוש בכל שירות צד שלישי כפוף לתנאים ולמדיניות של אותה פלטפורמה.","נכסים דיגיטליים הם תנודתיים מאוד וכרוכים בסיכון משמעותי, כולל האפשרות לאובדן מלא של ההון המושקע. לפני קבלת כל החלטה פיננסית, פנה לייעוץ מקצועי בלתי תלוי וערוך מחקר עצמאי משלך (DYOR).","בגישה ל-GaláxiaLunarium ובשימוש בו, אתה מאשר שקראת, הבנת ומסכים במלואו להצהרה המשפטית הזו."]},
  hi: {title:"कानूनी अस्वीकरण और उपयोग की शर्तें", h:["1. GaláxiaLunarium क्या है","2. हम एक एक्सचेंज या ब्रोकर नहीं हैं","3. यह वित्तीय सलाह नहीं है","4. डेटा की सटीकता","5. उत्तरदायित्व से इनकार","6. तृतीय-पक्ष लिंक और सेवाएं","7. डिजिटल एसेट्स के जोखिम","8. शर्तों की स्वीकृति"], p:["GaláxiaLunarium, LunariumCoin (XLN) और उसके इकोसिस्टम से संबंधित अन्य डिजिटल एसेट्स के बारे में सार्वजनिक डेटा का एक एग्रीगेटर है। यह ब्लॉकचेन एक्सप्लोरर, पार्टनर एक्सचेंज और सार्वजनिक तृतीय-पक्ष एपीआई से जानकारी एकत्र करता है और दिखाता है, केवल सूचनात्मक उद्देश्यों के लिए।","GaláxiaLunarium ऑर्डर निष्पादित नहीं करता, फंड नहीं रखता, ट्रेड नहीं करता और किसी भी लेनदेन में मध्यस्थ के रूप में कार्य नहीं करता। कोई भी उल्लिखित या प्रदर्शित ट्रेडिंग तृतीय-पक्ष प्लेटफ़ॉर्म पर होती है, जो उनकी अपनी विशेष जिम्मेदारी है।","इस साइट पर कुछ भी किसी एसेट को खरीदने, बेचने या रखने की सिफारिश नहीं है। जानकारी केवल सूचनात्मक उद्देश्यों के लिए प्रस्तुत की जाती है और इसे निवेश, वित्तीय, कानूनी या कर संबंधी सलाह के रूप में नहीं समझा जाना चाहिए।","प्रदर्शित डेटा सार्वजनिक तृतीय-पक्ष स्रोतों (ब्लॉकचेन एक्सप्लोरर, एक्सचेंज, मार्केट एपीआई) से प्राप्त किया जाता है और नेटवर्क देरी, स्रोतों की अस्थिरता या तकनीकी खराबी के कारण पुराना, अधूरा या गलत हो सकता है। हम इस जानकारी की सटीकता, पूर्णता या निरंतर उपलब्धता की गारंटी नहीं देते।","इस साइट का उपयोग पूरी तरह से उपयोगकर्ता के अपने जोखिम पर है। GaláxiaLunarium, इसके संचालक, योगदानकर्ता और सहयोगी किसी भी वित्तीय हानि, प्रत्यक्ष या अप्रत्यक्ष नुकसान, या यहां उपलब्ध जानकारी के उपयोग या उसके आधार पर लिए गए निर्णयों से उत्पन्न किसी भी परिणाम के लिए उत्तरदायी नहीं हैं।","इस साइट में एक्सचेंज, वॉलेट या अन्य तृतीय-पक्ष सेवाओं के लिंक हो सकते हैं। हमारा इन प्लेटफ़ॉर्म पर कोई नियंत्रण नहीं है और हम उनकी सामग्री, सुरक्षा, उपलब्धता या प्रथाओं के लिए जिम्मेदार नहीं हैं। किसी भी तृतीय-पक्ष सेवा का उपयोग उस प्लेटफ़ॉर्म की अपनी शर्तों और नीतियों के अधीन है।","डिजिटल एसेट्स अत्यधिक अस्थिर होते हैं और इसमें निवेशित पूंजी के पूर्ण नुकसान की संभावना सहित महत्वपूर्ण जोखिम शामिल है। कोई भी वित्तीय निर्णय लेने से पहले, स्वतंत्र पेशेवर सलाह लें और अपना खुद का शोध करें (DYOR)।","GaláxiaLunarium तक पहुंच बनाकर और इसका उपयोग करके, आप स्वीकार करते हैं कि आपने इस कानूनी अस्वीकरण को पूरी तरह से पढ़ा, समझा और सहमति दी है।"]},
  hr: {title:"Pravna napomena i uvjeti korištenja", h:["1. Što je GaláxiaLunarium","2. Nismo burza ni broker","3. Ovo nije financijski savjet","4. Točnost podataka","5. Odricanje od odgovornosti","6. Poveznice i usluge trećih strana","7. Rizici digitalne imovine","8. Prihvaćanje uvjeta"], p:["GaláxiaLunarium je agregator javnih podataka o LunariumCoinu (XLN) i drugoj digitalnoj imovini povezanoj s njegovim ekosustavom. Prikuplja i prikazuje informacije iz blockchain preglednika, partnerskih burzi i javnih API-ja trećih strana, isključivo u informativne svrhe.","GaláxiaLunarium ne izvršava naloge, ne čuva sredstva, ne provodi trgovanje i ne djeluje kao posrednik ni u jednoj transakciji. Svako spomenuto ili prikazano trgovanje odvija se na platformama trećih strana, pod njihovom isključivom odgovornošću.","Ništa na ovoj stranici ne predstavlja preporuku za kupnju, prodaju ili zadržavanje bilo koje imovine. Informacije se prikazuju isključivo u informativne svrhe i ne smiju se tumačiti kao investicijski, financijski, pravni ili porezni savjet.","Prikazani podaci dobiveni su iz javnih izvora trećih strana (blockchain preglednici, burze, tržišni API-ji) i mogu biti zastarjeli, nepotpuni ili netočni zbog kašnjenja mreže, nestabilnosti izvora ili tehničkih kvarova. Ne jamčimo točnost, potpunost ni kontinuiranu dostupnost ovih informacija.","Korištenje ove stranice u potpunosti je na vlastiti rizik korisnika. GaláxiaLunarium, njegovi operatori, suradnici i povezana društva ne snose odgovornost za bilo kakav financijski gubitak, izravnu ili neizravnu štetu, niti bilo kakvu posljedicu proizašlu iz korištenja ovdje dostupnih informacija ili odluka donesenih na temelju njih.","Ova stranica može sadržavati poveznice na burze, novčanike ili druge usluge trećih strana. Nemamo kontrolu nad tim platformama i nismo odgovorni za njihov sadržaj, sigurnost, dostupnost ili prakse. Korištenje bilo koje usluge treće strane podliježe vlastitim uvjetima i politikama te platforme.","Digitalna imovina izrazito je nestabilna i nosi značajan rizik, uključujući mogućnost potpunog gubitka uloženog kapitala. Prije donošenja bilo kakve financijske odluke, potražite neovisan stručni savjet i provedite vlastito istraživanje (DYOR).","Pristupanjem i korištenjem GaláxiaLunariuma potvrđujete da ste pročitali, razumjeli i u potpunosti prihvaćate ovu Pravnu napomenu."]},
  hu: {title:"Jogi nyilatkozat és felhasználási feltételek", h:["1. Mi a GaláxiaLunarium","2. Nem vagyunk tőzsde vagy bróker","3. Ez nem pénzügyi tanácsadás","4. Az adatok pontossága","5. Felelősség kizárása","6. Harmadik felek linkjei és szolgáltatásai","7. Digitális eszközök kockázatai","8. A feltételek elfogadása"], p:["A GaláxiaLunarium a LunariumCoinra (XLN) és az ökoszisztémájához kapcsolódó egyéb digitális eszközökre vonatkozó nyilvános adatok aggregátora. Blokklánc-exploreröktől, partnertőzsdéktől és nyilvános külső API-któl gyűjt és jelenít meg információkat, kizárólag tájékoztatási céllal.","A GaláxiaLunarium nem hajt végre megbízásokat, nem tart pénzeszközöket, nem bonyolít le kereskedést, és semmilyen tranzakcióban nem jár el közvetítőként. Minden említett vagy megjelenített kereskedés harmadik fél platformjain zajlik, azok kizárólagos felelőssége mellett.","Ezen az oldalon semmi sem minősül ajánlásnak bármely eszköz megvásárlására, eladására vagy tartására. Az információk kizárólag tájékoztatási céllal jelennek meg, és nem értelmezhetők befektetési, pénzügyi, jogi vagy adótanácsadásként.","A megjelenített adatok nyilvános külső forrásokból (blokklánc-exploreröktől, tőzsdéktől, piaci API-któl) származnak, és hálózati késések, a források instabilitása vagy technikai hibák miatt elavultak, hiányosak vagy pontatlanok lehetnek. Nem garantáljuk ezen információk pontosságát, teljességét vagy folyamatos elérhetőségét.","Az oldal használata kizárólag a felhasználó saját kockázatára történik. A GaláxiaLunarium, üzemeltetői, közreműködői és kapcsolt vállalkozásai nem vállalnak felelősséget semmilyen pénzügyi veszteségért, közvetlen vagy közvetett kárért, vagy az itt elérhető információk felhasználásából, illetve az azok alapján hozott döntésekből eredő bármely következményért.","Ez az oldal tartalmazhat linkeket tőzsdékhez, tárcákhoz vagy más harmadik féltől származó szolgáltatásokhoz. Nincs ráhatásunk ezekre a platformokra, és nem vagyunk felelősek azok tartalmáért, biztonságáért, elérhetőségéért vagy gyakorlatáért. Bármely harmadik féltől származó szolgáltatás használatára az adott platform saját feltételei és irányelvei vonatkoznak.","A digitális eszközök rendkívül volatilisek, és jelentős kockázatot hordoznak, beleértve a befektetett tőke teljes elvesztésének lehetőségét is. Bármilyen pénzügyi döntés meghozatala előtt kérjen független szakmai tanácsot, és végezze el saját kutatását (DYOR).","A GaláxiaLunarium elérésével és használatával elismeri, hogy elolvasta, megértette és teljes egészében elfogadja ezt a Jogi nyilatkozatot."]},
  id: {title:"Penyangkalan Hukum dan Ketentuan Penggunaan", h:["1. Apa itu GaláxiaLunarium","2. Kami bukan exchange atau broker","3. Ini bukan nasihat keuangan","4. Akurasi data","5. Penyangkalan tanggung jawab","6. Tautan dan layanan pihak ketiga","7. Risiko aset digital","8. Penerimaan ketentuan"], p:["GaláxiaLunarium adalah agregator data publik tentang LunariumCoin (XLN) dan aset digital lain yang terkait dengan ekosistemnya. Platform ini mengumpulkan dan menampilkan informasi dari explorer blockchain, exchange mitra, dan API publik pihak ketiga, semata-mata untuk tujuan informasi.","GaláxiaLunarium tidak mengeksekusi order, tidak menyimpan dana, tidak melakukan perdagangan, dan tidak bertindak sebagai perantara dalam transaksi apa pun. Setiap perdagangan yang disebutkan atau ditampilkan terjadi di platform pihak ketiga, di bawah tanggung jawab eksklusif platform tersebut.","Tidak ada yang ada di situs ini merupakan rekomendasi untuk membeli, menjual, atau menahan aset apa pun. Informasi disajikan semata-mata untuk tujuan informasi dan tidak boleh ditafsirkan sebagai nasihat investasi, keuangan, hukum, atau pajak.","Data yang ditampilkan diperoleh dari sumber publik pihak ketiga (explorer blockchain, exchange, API pasar) dan mungkin sudah usang, tidak lengkap, atau tidak akurat karena keterlambatan jaringan, ketidakstabilan sumber, atau kegagalan teknis. Kami tidak menjamin keakuratan, kelengkapan, atau ketersediaan berkelanjutan dari informasi ini.","Penggunaan situs ini sepenuhnya menjadi risiko pengguna sendiri. GaláxiaLunarium, operatornya, kontributor, dan afiliasinya tidak bertanggung jawab atas kerugian finansial, kerusakan langsung atau tidak langsung, atau konsekuensi apa pun yang timbul dari penggunaan informasi yang tersedia di sini atau dari keputusan yang dibuat berdasarkan informasi tersebut.","Situs ini mungkin berisi tautan ke exchange, wallet, atau layanan pihak ketiga lainnya. Kami tidak memiliki kendali atas platform ini dan tidak bertanggung jawab atas konten, keamanan, ketersediaan, atau praktiknya. Penggunaan layanan pihak ketiga mana pun tunduk pada ketentuan dan kebijakan platform tersebut sendiri.","Aset digital sangat volatil dan membawa risiko signifikan, termasuk kemungkinan kehilangan total modal yang diinvestasikan. Sebelum membuat keputusan keuangan apa pun, carilah panduan profesional independen dan lakukan riset Anda sendiri (DYOR).","Dengan mengakses dan menggunakan GaláxiaLunarium, Anda mengakui bahwa Anda telah membaca, memahami, dan menyetujui Penyangkalan Hukum ini secara keseluruhan."]},
  it: {title:"Avviso Legale e Termini di Utilizzo", h:["1. Cos'è GaláxiaLunarium","2. Non siamo un exchange né un broker","3. Questo non è consulenza finanziaria","4. Accuratezza dei dati","5. Esclusione di responsabilità","6. Link e servizi di terze parti","7. Rischi degli asset digitali","8. Accettazione dei termini"], p:["GaláxiaLunarium è un aggregatore di dati pubblici su LunariumCoin (XLN) e altri asset digitali correlati al suo ecosistema. Raccoglie e mostra informazioni provenienti da explorer blockchain, exchange partner e API pubbliche di terze parti, esclusivamente a scopo informativo.","GaláxiaLunarium non esegue ordini, non custodisce fondi, non effettua operazioni e non agisce come intermediario in alcuna transazione. Qualsiasi trading menzionato o mostrato avviene su piattaforme di terze parti, sotto la loro esclusiva responsabilità.","Nulla su questo sito costituisce una raccomandazione di acquisto, vendita o detenzione di alcun asset. Le informazioni sono presentate esclusivamente a scopo informativo e non devono essere interpretate come consulenza di investimento, finanziaria, legale o fiscale.","I dati mostrati provengono da fonti pubbliche di terze parti (explorer blockchain, exchange, API di mercato) e potrebbero essere obsoleti, incompleti o errati a causa di ritardi di rete, instabilità delle fonti o guasti tecnici. Non garantiamo l'accuratezza, la completezza o la disponibilità continua di queste informazioni.","L'utilizzo di questo sito è interamente a rischio dell'utente. GaláxiaLunarium, i suoi operatori, collaboratori e affiliati non sono responsabili per eventuali perdite finanziarie, danni diretti o indiretti, o qualsiasi conseguenza derivante dall'uso delle informazioni qui disponibili o da decisioni prese sulla loro base.","Questo sito potrebbe contenere link a exchange, wallet o altri servizi di terze parti. Non abbiamo alcun controllo su queste piattaforme e non siamo responsabili per il loro contenuto, sicurezza, disponibilità o pratiche. L'uso di qualsiasi servizio di terze parti è soggetto ai termini e alle politiche proprie di quella piattaforma.","Gli asset digitali sono altamente volatili e comportano un rischio significativo, inclusa la possibilità di perdita totale del capitale investito. Prima di prendere qualsiasi decisione finanziaria, cerca una consulenza professionale indipendente e conduci le tue ricerche (DYOR).","Accedendo e utilizzando GaláxiaLunarium, riconosci di aver letto, compreso e accettato integralmente questo Avviso Legale."]},
  ja: {title:"法的免責事項および利用規約", h:["1. GaláxiaLunariumとは","2. 当社は取引所やブローカーではありません","3. これは投資助言ではありません","4. データの正確性","5. 免責事項","6. 第三者へのリンクとサービス","7. デジタル資産のリスク","8. 規約の承諾"], p:["GaláxiaLunariumは、LunariumCoin（XLN）およびそのエコシステムに関連するその他のデジタル資産に関する公開データを集約するプラットフォームです。ブロックチェーンエクスプローラー、パートナー取引所、公開されている第三者のAPIから情報を収集・表示しており、情報提供のみを目的としています。","GaláxiaLunariumは注文の執行、資金の保管、取引の実行を行わず、いかなる取引においても仲介者として機能しません。言及または表示される取引はすべて第三者のプラットフォーム上で行われ、それらのプラットフォームの単独の責任のもとで行われます。","このサイト上のいかなる内容も、資産の購入、売却、保有を推奨するものではありません。情報は情報提供のみを目的として提示されており、投資、財務、法律、税務に関する助言として解釈されるべきではありません。","表示されるデータは第三者の公開ソース（ブロックチェーンエクスプローラー、取引所、市場API）から取得されており、ネットワークの遅延、ソースの不安定性、技術的な障害により、古くなっていたり、不完全であったり、誤りがある場合があります。当社はこれらの情報の正確性、完全性、継続的な利用可能性を保証しません。","このサイトの利用はすべて利用者自身の責任において行われます。GaláxiaLunarium、その運営者、貢献者、関連会社は、ここで提供される情報の利用またはそれに基づく決定から生じるいかなる財務的損失、直接的または間接的な損害、あるいはその他の結果についても責任を負いません。","本サイトには取引所、ウォレット、その他の第三者サービスへのリンクが含まれる場合があります。当社はこれらのプラットフォームを管理しておらず、その内容、セキュリティ、可用性、運営方法について責任を負いません。第三者サービスの利用は、そのプラットフォーム独自の規約およびポリシーに従うものとします。","デジタル資産は非常に変動性が高く、投資した資本の全損失の可能性を含む重大なリスクを伴います。財務上の決定を行う前に、独立した専門家の助言を求め、ご自身で調査を行ってください（DYOR）。","GaláxiaLunariumにアクセスし利用することにより、この法的免責事項の全文を読み、理解し、同意したことを認めるものとします。"]},
  ko: {title:"법적 고지 및 이용 약관", h:["1. GaláxiaLunarium이란","2. 당사는 거래소나 브로커가 아닙니다","3. 이는 재정적 조언이 아닙니다","4. 데이터 정확성","5. 책임의 면제","6. 제3자 링크 및 서비스","7. 디지털 자산의 위험","8. 약관 동의"], p:["GaláxiaLunarium은 LunariumCoin(XLN) 및 그 생태계와 관련된 기타 디지털 자산에 대한 공개 데이터 집계 플랫폼입니다. 블록체인 탐색기, 파트너 거래소, 공개된 제3자 API로부터 정보를 수집하여 표시하며, 이는 오직 정보 제공 목적입니다.","GaláxiaLunarium은 주문을 실행하지 않고, 자금을 보관하지 않으며, 거래를 수행하지 않고, 어떠한 거래에서도 중개자로 활동하지 않습니다. 언급되거나 표시된 모든 거래는 제3자 플랫폼에서 이루어지며, 이는 해당 플랫폼의 독점적 책임입니다.","이 사이트의 어떠한 내용도 자산의 매수, 매도 또는 보유를 권장하지 않습니다. 정보는 오직 정보 제공 목적으로만 제시되며, 투자, 재정, 법률 또는 세무 자문으로 해석되어서는 안 됩니다.","표시된 데이터는 제3자 공개 소스(블록체인 탐색기, 거래소, 시장 API)에서 얻어지며, 네트워크 지연, 소스의 불안정성 또는 기술적 오류로 인해 오래되었거나, 불완전하거나, 부정확할 수 있습니다. 당사는 이 정보의 정확성, 완전성 또는 지속적인 가용성을 보장하지 않습니다.","이 사이트의 이용은 전적으로 이용자 본인의 책임입니다. GaláxiaLunarium과 그 운영자, 기여자, 계열사는 여기서 제공되는 정보의 사용 또는 이에 기반한 결정으로 인해 발생하는 어떠한 재정적 손실, 직접적 또는 간접적 손해, 또는 그 밖의 결과에 대해서도 책임을 지지 않습니다.","이 사이트에는 거래소, 지갑 또는 기타 제3자 서비스로의 링크가 포함될 수 있습니다. 당사는 이러한 플랫폼을 통제하지 않으며, 그 콘텐츠, 보안, 가용성 또는 관행에 대해 책임지지 않습니다. 제3자 서비스의 이용은 해당 플랫폼 자체의 약관 및 정책을 따릅니다.","디지털 자산은 변동성이 매우 크며, 투자한 자본의 전액 손실 가능성을 포함한 상당한 위험을 수반합니다. 어떠한 재정적 결정을 내리기 전에 독립적인 전문가의 조언을 구하고 스스로 조사하시기 바랍니다(DYOR).","GaláxiaLunarium에 접속하여 이용함으로써, 귀하는 본 법적 고지를 전부 읽고 이해했으며 이에 동의함을 인정합니다."]},
  lt: {title:"Teisinis pranešimas ir naudojimo sąlygos", h:["1. Kas yra GaláxiaLunarium","2. Mes nesame birža ar brokeris","3. Tai nėra finansinė konsultacija","4. Duomenų tikslumas","5. Atsakomybės atsisakymas","6. Trečiųjų šalių nuorodos ir paslaugos","7. Skaitmeninio turto rizika","8. Sąlygų priėmimas"], p:["GaláxiaLunarium yra viešų duomenų apie LunariumCoin (XLN) ir kitą su jos ekosistema susijusį skaitmeninį turtą agregatorius. Jis renka ir rodo informaciją iš blokų grandinės naršyklių, partnerių biržų ir viešų trečiųjų šalių API tik informaciniais tikslais.","GaláxiaLunarium nevykdo pavedimų, nesaugo lėšų, nevykdo sandorių ir neveikia kaip tarpininkas jokioje operacijoje. Bet koks minimas ar rodomas prekybos procesas vyksta trečiųjų šalių platformose, kurių išskirtinė atsakomybė yra už tai.","Niekas šioje svetainėje nėra rekomendacija pirkti, parduoti ar laikyti bet kokį turtą. Informacija pateikiama tik informaciniais tikslais ir neturėtų būti aiškinama kaip investavimo, finansų, teisės ar mokesčių konsultacija.","Rodomi duomenys gaunami iš viešų trečiųjų šalių šaltinių (blokų grandinės naršyklių, biržų, rinkos API) ir gali būti pasenę, neišsamūs ar neteisingi dėl tinklo vėlavimų, šaltinių nestabilumo ar techninių gedimų. Negarantuojame šios informacijos tikslumo, išsamumo ar nuolatinio prieinamumo.","Šios svetainės naudojimas yra visiškai vartotojo paties rizika. GaláxiaLunarium, jos operatoriai, bendradarbiai ir susijusios šalys neatsako už jokius finansinius nuostolius, tiesioginę ar netiesioginę žalą, ar bet kokias pasekmes, kylančias iš čia pateiktos informacijos naudojimo ar jos pagrindu priimtų sprendimų.","Šioje svetainėje gali būti nuorodų į biržas, pinigines ar kitas trečiųjų šalių paslaugas. Neturime jokios kontrolės šioms platformoms ir neatsakome už jų turinį, saugumą, prieinamumą ar praktiką. Bet kokios trečiosios šalies paslaugos naudojimui taikomos tos platformos pačios sąlygos ir politika.","Skaitmeninis turtas yra labai nepastovus ir kelia didelę riziką, įskaitant galimybę visiškai prarasti investuotą kapitalą. Prieš priimdami bet kokį finansinį sprendimą, kreipkitės į nepriklausomą profesionalų konsultantą ir atlikite savo tyrimą (DYOR).","Prieigą prie GaláxiaLunarium ir jos naudojimą jūs patvirtinate, kad perskaitėte, supratote ir visiškai sutinkate su šiuo Teisiniu pranešimu."]},
  nl: {title:"Juridische Kennisgeving en Gebruiksvoorwaarden", h:["1. Wat is GaláxiaLunarium","2. Wij zijn geen exchange of broker","3. Dit is geen financieel advies","4. Nauwkeurigheid van gegevens","5. Aansprakelijkheidsuitsluiting","6. Links en diensten van derden","7. Risico's van digitale activa","8. Aanvaarding van de voorwaarden"], p:["GaláxiaLunarium is een aggregator van openbare gegevens over LunariumCoin (XLN) en andere digitale activa die verband houden met het ecosysteem ervan. Het verzamelt en toont informatie van blockchain-explorers, partnerexchanges en openbare API's van derden, uitsluitend voor informatieve doeleinden.","GaláxiaLunarium voert geen orders uit, bewaart geen tegoeden, voert geen transacties uit en treedt niet op als tussenpersoon bij enige transactie. Elke genoemde of getoonde handel vindt plaats op platforms van derden, onder hun eigen exclusieve verantwoordelijkheid.","Niets op deze site vormt een aanbeveling om enig actief te kopen, verkopen of aan te houden. De informatie wordt uitsluitend ter informatie gepresenteerd en mag niet worden opgevat als beleggings-, financieel, juridisch of fiscaal advies.","De getoonde gegevens zijn afkomstig van openbare bronnen van derden (blockchain-explorers, exchanges, markt-API's) en kunnen verouderd, onvolledig of onjuist zijn als gevolg van netwerkvertragingen, instabiliteit van bronnen of technische storingen. Wij garanderen niet de nauwkeurigheid, volledigheid of continue beschikbaarheid van deze informatie.","Het gebruik van deze site is volledig op eigen risico van de gebruiker. GaláxiaLunarium, de exploitanten, medewerkers en gelieerde partijen zijn niet aansprakelijk voor financieel verlies, directe of indirecte schade, of enig gevolg voortvloeiend uit het gebruik van de hier beschikbare informatie of uit beslissingen die daarop zijn gebaseerd.","Deze site kan links bevatten naar exchanges, wallets of andere diensten van derden. Wij hebben geen controle over deze platforms en zijn niet verantwoordelijk voor hun inhoud, beveiliging, beschikbaarheid of praktijken. Het gebruik van diensten van derden is onderworpen aan de eigen voorwaarden en het beleid van dat platform.","Digitale activa zijn zeer volatiel en brengen aanzienlijke risico's met zich mee, waaronder de mogelijkheid van volledig verlies van geïnvesteerd kapitaal. Zoek onafhankelijk professioneel advies en doe uw eigen onderzoek (DYOR) voordat u een financiële beslissing neemt.","Door toegang te krijgen tot en gebruik te maken van GaláxiaLunarium, erkent u dat u deze Juridische Kennisgeving volledig hebt gelezen, begrepen en aanvaard."]},
  no: {title:"Juridisk Merknad og Bruksvilkår", h:["1. Hva GaláxiaLunarium er","2. Vi er ikke en børs eller megler","3. Dette er ikke finansiell rådgivning","4. Datanøyaktighet","5. Ansvarsfraskrivelse","6. Lenker og tredjepartstjenester","7. Risikoer ved digitale eiendeler","8. Aksept av vilkårene"], p:["GaláxiaLunarium er en aggregator for offentlige data om LunariumCoin (XLN) og andre digitale eiendeler knyttet til dets økosystem. Den samler inn og viser informasjon fra blockchain-explorere, partnerbørser og offentlige tredjeparts-API-er, utelukkende til informasjonsformål.","GaláxiaLunarium utfører ikke ordrer, oppbevarer ikke midler, gjennomfører ikke handler og opptrer ikke som mellommann i noen transaksjon. All omtalt eller vist handel finner sted på tredjepartsplattformer, under deres eget eksklusive ansvar.","Ingenting på dette nettstedet utgjør en anbefaling om å kjøpe, selge eller beholde noen eiendel. Informasjonen presenteres utelukkende til informasjonsformål og bør ikke tolkes som investerings-, finansiell, juridisk eller skatterådgivning.","De viste dataene innhentes fra offentlige tredjepartskilder (blockchain-explorere, børser, marked-API-er) og kan være utdaterte, ufullstendige eller feilaktige på grunn av nettverksforsinkelser, ustabile kilder eller tekniske feil. Vi garanterer verken nøyaktigheten, fullstendigheten eller den kontinuerlige tilgjengeligheten av denne informasjonen.","Bruken av dette nettstedet skjer utelukkende på brukerens egen risiko. GaláxiaLunarium, dets operatører, bidragsytere og tilknyttede selskaper er ikke ansvarlige for økonomisk tap, direkte eller indirekte skader, eller andre konsekvenser som følge av bruken av informasjonen som er tilgjengelig her, eller av beslutninger tatt på dette grunnlaget.","Dette nettstedet kan inneholde lenker til børser, lommebøker eller andre tredjepartstjenester. Vi har ingen kontroll over disse plattformene og er ikke ansvarlige for deres innhold, sikkerhet, tilgjengelighet eller praksis. Bruk av enhver tredjepartstjeneste er underlagt den aktuelle plattformens egne vilkår og retningslinjer.","Digitale eiendeler er svært volatile og innebærer betydelig risiko, inkludert muligheten for totalt tap av investert kapital. Søk uavhengig profesjonell rådgivning og gjør din egen research (DYOR) før du tar noen finansiell beslutning.","Ved å få tilgang til og bruke GaláxiaLunarium, bekrefter du at du har lest, forstått og godtatt denne Juridiske Merknaden i sin helhet."]},
  ro: {title:"Notă Juridică și Termeni de Utilizare", h:["1. Ce este GaláxiaLunarium","2. Nu suntem un exchange sau broker","3. Aceasta nu este consultanță financiară","4. Acuratețea datelor","5. Excluderea răspunderii","6. Linkuri și servicii ale terților","7. Riscurile activelor digitale","8. Acceptarea termenilor"], p:["GaláxiaLunarium este un agregator de date publice despre LunariumCoin (XLN) și alte active digitale asociate ecosistemului său. Acesta colectează și afișează informații de la exploratori blockchain, exchange-uri partenere și API-uri publice terțe, exclusiv în scop informativ.","GaláxiaLunarium nu execută ordine, nu deține fonduri, nu efectuează tranzacții și nu acționează ca intermediar în nicio tranzacție. Orice tranzacționare menționată sau afișată are loc pe platforme terțe, sub responsabilitatea exclusivă a acestora.","Nimic pe acest site nu constituie o recomandare de a cumpăra, vinde sau deține vreun activ. Informațiile sunt prezentate exclusiv în scop informativ și nu trebuie interpretate drept consultanță de investiții, financiară, juridică sau fiscală.","Datele afișate sunt obținute din surse publice terțe (exploratori blockchain, exchange-uri, API-uri de piață) și pot fi depășite, incomplete sau incorecte din cauza întârzierilor de rețea, instabilității surselor sau defecțiunilor tehnice. Nu garantăm acuratețea, completitudinea sau disponibilitatea continuă a acestor informații.","Utilizarea acestui site este în întregime pe riscul propriu al utilizatorului. GaláxiaLunarium, operatorii, colaboratorii și afiliații săi nu sunt responsabili pentru nicio pierdere financiară, daune directe sau indirecte, sau orice consecință rezultată din utilizarea informațiilor disponibile aici sau din decizii luate pe baza acestora.","Acest site poate conține linkuri către exchange-uri, portofele sau alte servicii ale terților. Nu avem control asupra acestor platforme și nu suntem responsabili pentru conținutul, securitatea, disponibilitatea sau practicile lor. Utilizarea oricărui serviciu terț este supusă propriilor termeni și politici ale acelei platforme.","Activele digitale sunt extrem de volatile și implică riscuri semnificative, inclusiv posibilitatea pierderii totale a capitalului investit. Înainte de a lua orice decizie financiară, solicitați consiliere profesională independentă și efectuați propria cercetare (DYOR).","Prin accesarea și utilizarea GaláxiaLunarium, recunoașteți că ați citit, înțeles și sunteți de acord în totalitate cu această Notă Juridică."]},
  sk: {title:"Právne upozornenie a podmienky používania", h:["1. Čo je GaláxiaLunarium","2. Nie sme burza ani maklér","3. Toto nie je finančné poradenstvo","4. Presnosť údajov","5. Vylúčenie zodpovednosti","6. Odkazy a služby tretích strán","7. Riziká digitálnych aktív","8. Prijatie podmienok"], p:["GaláxiaLunarium je agregátor verejných údajov o LunariumCoin (XLN) a ďalších digitálnych aktívach súvisiacich s jej ekosystémom. Zhromažďuje a zobrazuje informácie z blockchain exploreru, partnerských búrz a verejných API tretích strán, výlučne na informačné účely.","GaláxiaLunarium nevykonáva žiadne pokyny, neuchováva žiadne prostriedky, nevykonáva žiadne obchody a nevystupuje ako sprostredkovateľ v žiadnej transakcii. Akékoľvek spomenuté alebo zobrazené obchodovanie prebieha na platformách tretích strán, na ich výhradnú zodpovednosť.","Nič na tejto stránke nepredstavuje odporúčanie na kúpu, predaj alebo držanie akéhokoľvek aktíva. Informácie sú uvádzané výlučne na informačné účely a nemali by byť vykladané ako investičné, finančné, právne alebo daňové poradenstvo.","Zobrazené údaje pochádzajú z verejných zdrojov tretích strán (blockchain explorery, burzy, trhové API) a môžu byť zastarané, neúplné alebo nesprávne v dôsledku sieťových oneskorení, nestability zdrojov alebo technických porúch. Nezaručujeme presnosť, úplnosť ani nepretržitú dostupnosť týchto informácií.","Používanie tejto stránky je výlučne na riziko používateľa. GaláxiaLunarium, jeho prevádzkovatelia, prispievatelia a pridružené subjekty nenesú zodpovednosť za akúkoľvek finančnú stratu, priame či nepriame škody alebo akékoľvek dôsledky vyplývajúce z používania tu poskytnutých informácií alebo z rozhodnutí na ich základe.","Táto stránka môže obsahovať odkazy na burzy, peňaženky alebo iné služby tretích strán. Nemáme žiadnu kontrolu nad týmito platformami a nezodpovedáme za ich obsah, bezpečnosť, dostupnosť ani praktiky. Používanie akejkoľvek služby tretej strany podlieha vlastným podmienkam a zásadám danej platformy.","Digitálne aktíva sú vysoko volatilné a nesú značné riziko, vrátane možnosti úplnej straty investovaného kapitálu. Pred akýmkoľvek finančným rozhodnutím vyhľadajte nezávislé odborné poradenstvo a vykonajte vlastný prieskum (DYOR).","Prístupom na GaláxiaLunarium a jeho používaním potvrdzujete, že ste si prečítali, porozumeli a v plnom rozsahu súhlasíte s týmto Právnym upozornením."]},
  sl: {title:"Pravno obvestilo in pogoji uporabe", h:["1. Kaj je GaláxiaLunarium","2. Nismo borza ali posrednik","3. To ni finančni nasvet","4. Natančnost podatkov","5. Omejitev odgovornosti","6. Povezave in storitve tretjih oseb","7. Tveganja digitalnih sredstev","8. Sprejetje pogojev"], p:["GaláxiaLunarium je agregator javnih podatkov o LunariumCoin (XLN) in drugih digitalnih sredstvih, povezanih z njegovim ekosistemom. Zbira in prikazuje informacije iz raziskovalcev blockchaina, partnerskih borz in javnih API-jev tretjih oseb, izključno v informativne namene.","GaláxiaLunarium ne izvršuje naročil, ne hrani sredstev, ne izvaja trgovanja in ne deluje kot posrednik v nobeni transakciji. Vsako omenjeno ali prikazano trgovanje poteka na platformah tretjih oseb, pod njihovo izključno odgovornostjo.","Nič na tem spletnem mestu ne predstavlja priporočila za nakup, prodajo ali posedovanje katerega koli sredstva. Informacije so predstavljene izključno v informativne namene in jih ne smete razlagati kot investicijski, finančni, pravni ali davčni nasvet.","Prikazani podatki so pridobljeni iz javnih virov tretjih oseb (raziskovalci blockchaina, borze, tržni API-ji) in so lahko zastareli, nepopolni ali napačni zaradi zamud v omrežju, nestabilnosti virov ali tehničnih okvar. Ne jamčimo za natančnost, popolnost ali neprekinjeno razpoložljivost teh informacij.","Uporaba tega spletnega mesta je v celoti na lastno odgovornost uporabnika. GaláxiaLunarium, njegovi upravljavci, sodelavci in povezane osebe ne odgovarjajo za kakršno koli finančno izgubo, neposredno ali posredno škodo ali kakršno koli posledico, ki izhaja iz uporabe tukaj razpoložljivih informacij ali odločitev, sprejetih na njihovi podlagi.","To spletno mesto lahko vsebuje povezave do borz, denarnic ali drugih storitev tretjih oseb. Nad temi platformami nimamo nobenega nadzora in nismo odgovorni za njihovo vsebino, varnost, razpoložljivost ali prakse. Uporaba katere koli storitve tretje osebe je predmet lastnih pogojev in politik te platforme.","Digitalna sredstva so izjemno nestanovitna in vključujejo znatno tveganje, vključno z možnostjo popolne izgube vloženega kapitala. Pred sprejetjem kakršne koli finančne odločitve poiščite neodvisen strokovni nasvet in opravite lastno raziskavo (DYOR).","Z dostopom do GaláxiaLunarium in njegovo uporabo potrjujete, da ste prebrali, razumeli in v celoti sprejeli to Pravno obvestilo."]},
  sv: {title:"Juridiskt Meddelande och Användarvillkor", h:["1. Vad GaláxiaLunarium är","2. Vi är inte en börs eller mäklare","3. Detta är inte finansiell rådgivning","4. Datanoggrannhet","5. Ansvarsfriskrivning","6. Länkar och tredjepartstjänster","7. Risker med digitala tillgångar","8. Godkännande av villkoren"], p:["GaláxiaLunarium är en aggregator av offentliga data om LunariumCoin (XLN) och andra digitala tillgångar relaterade till dess ekosystem. Den samlar in och visar information från blockkedje-explorers, partnerbörser och offentliga tredjeparts-API:er, endast i informationssyfte.","GaláxiaLunarium utför inte order, förvarar inte medel, genomför inte handel och agerar inte som mellanhand i någon transaktion. All nämnd eller visad handel sker på tredjepartsplattformar, under dessa plattformars eget ansvar.","Ingenting på denna webbplats utgör en rekommendation att köpa, sälja eller behålla någon tillgång. Informationen presenteras endast i informationssyfte och ska inte tolkas som investerings-, finansiell, juridisk eller skatterådgivning.","De visade uppgifterna hämtas från offentliga tredjepartskällor (blockkedje-explorers, börser, marknads-API:er) och kan vara föråldrade, ofullständiga eller felaktiga på grund av nätverksfördröjningar, instabila källor eller tekniska fel. Vi garanterar varken riktigheten, fullständigheten eller den kontinuerliga tillgängligheten av denna information.","Användningen av denna webbplats sker helt på användarens egen risk. GaláxiaLunarium, dess operatörer, medarbetare och anknutna parter ansvarar inte för ekonomisk förlust, direkta eller indirekta skador, eller någon konsekvens som uppstår från användningen av den information som finns tillgänglig här eller från beslut som fattats på grundval av den.","Denna webbplats kan innehålla länkar till börser, plånböcker eller andra tredjepartstjänster. Vi har ingen kontroll över dessa plattformar och ansvarar inte för deras innehåll, säkerhet, tillgänglighet eller praxis. Användning av tredjepartstjänster omfattas av den plattformens egna villkor och policyer.","Digitala tillgångar är mycket volatila och innebär betydande risk, inklusive möjligheten till total förlust av investerat kapital. Sök oberoende professionell rådgivning och gör din egen research (DYOR) innan du fattar något finansiellt beslut.","Genom att gå in på och använda GaláxiaLunarium bekräftar du att du har läst, förstått och accepterat detta Juridiska Meddelande i sin helhet."]},
  th: {title:"ประกาศทางกฎหมายและข้อกำหนดการใช้งาน", h:["1. GaláxiaLunarium คืออะไร","2. เราไม่ใช่ตลาดแลกเปลี่ยนหรือโบรกเกอร์","3. นี่ไม่ใช่คำแนะนำทางการเงิน","4. ความถูกต้องของข้อมูล","5. การปฏิเสธความรับผิด","6. ลิงก์และบริการของบุคคลที่สาม","7. ความเสี่ยงของสินทรัพย์ดิจิทัล","8. การยอมรับข้อกำหนด"], p:["GaláxiaLunarium เป็นแพลตฟอร์มรวบรวมข้อมูลสาธารณะเกี่ยวกับ LunariumCoin (XLN) และสินทรัพย์ดิจิทัลอื่น ๆ ที่เกี่ยวข้องกับระบบนิเวศของมัน โดยรวบรวมและแสดงข้อมูลจากเอ็กซ์พลอเรอร์บล็อกเชน ตลาดแลกเปลี่ยนพันธมิตร และ API สาธารณะของบุคคลที่สาม เพื่อวัตถุประสงค์ในการให้ข้อมูลเท่านั้น","GaláxiaLunarium ไม่ดำเนินการคำสั่งซื้อขาย ไม่ถือครองเงินทุน ไม่ทำธุรกรรมใด ๆ และไม่ทำหน้าที่เป็นตัวกลางในการทำธุรกรรมใด ๆ การซื้อขายใด ๆ ที่กล่าวถึงหรือแสดงเกิดขึ้นบนแพลตฟอร์มของบุคคลที่สาม ซึ่งอยู่ภายใต้ความรับผิดชอบแต่เพียงผู้เดียวของแพลตฟอร์มนั้น","ไม่มีสิ่งใดในเว็บไซต์นี้ที่ถือเป็นคำแนะนำให้ซื้อ ขาย หรือถือครองสินทรัพย์ใด ๆ ข้อมูลนี้นำเสนอเพื่อวัตถุประสงค์ในการให้ข้อมูลเท่านั้น และไม่ควรตีความว่าเป็นคำแนะนำด้านการลงทุน การเงิน กฎหมาย หรือภาษี","ข้อมูลที่แสดงได้มาจากแหล่งข้อมูลสาธารณะของบุคคลที่สาม (เอ็กซ์พลอเรอร์บล็อกเชน ตลาดแลกเปลี่ยน API ตลาด) และอาจล้าสมัย ไม่สมบูรณ์ หรือไม่ถูกต้องเนื่องจากความล่าช้าของเครือข่าย ความไม่เสถียรของแหล่งข้อมูล หรือความขัดข้องทางเทคนิค เราไม่รับประกันความถูกต้อง ความสมบูรณ์ หรือความพร้อมใช้งานอย่างต่อเนื่องของข้อมูลนี้","การใช้เว็บไซต์นี้เป็นความเสี่ยงของผู้ใช้แต่เพียงผู้เดียว GaláxiaLunarium ผู้ดำเนินการ ผู้มีส่วนร่วม และบริษัทในเครือ จะไม่รับผิดชอบต่อความสูญเสียทางการเงิน ความเสียหายทางตรงหรือทางอ้อม หรือผลที่ตามมาใด ๆ ที่เกิดจากการใช้ข้อมูลที่มีอยู่ที่นี่หรือจากการตัดสินใจที่อ้างอิงจากข้อมูลดังกล่าว","เว็บไซต์นี้อาจมีลิงก์ไปยังตลาดแลกเปลี่ยน กระเป๋าเงิน หรือบริการอื่น ๆ ของบุคคลที่สาม เราไม่มีการควบคุมแพลตฟอร์มเหล่านี้และไม่รับผิดชอบต่อเนื้อหา ความปลอดภัย ความพร้อมใช้งาน หรือแนวทางปฏิบัติของแพลตฟอร์มเหล่านั้น การใช้บริการของบุคคลที่สามใด ๆ อยู่ภายใต้ข้อกำหนดและนโยบายของแพลตฟอร์มนั้นเอง","สินทรัพย์ดิจิทัลมีความผันผวนสูงและมีความเสี่ยงอย่างมาก รวมถึงความเป็นไปได้ที่จะสูญเสียเงินลงทุนทั้งหมด ก่อนตัดสินใจทางการเงินใด ๆ ควรขอคำแนะนำจากผู้เชี่ยวชาญอิสระและทำการค้นคว้าด้วยตนเอง (DYOR)","การเข้าถึงและใช้งาน GaláxiaLunarium ถือว่าคุณรับทราบว่าคุณได้อ่าน เข้าใจ และยอมรับประกาศทางกฎหมายฉบับนี้ทั้งหมดแล้ว"]},
  tr: {title:"Yasal Uyarı ve Kullanım Koşulları", h:["1. GaláxiaLunarium Nedir","2. Bir borsa veya aracı kurum değiliz","3. Bu finansal tavsiye değildir","4. Veri doğruluğu","5. Sorumluluk reddi","6. Üçüncü taraf bağlantıları ve hizmetleri","7. Dijital varlık riskleri","8. Şartların kabulü"], p:["GaláxiaLunarium, LunariumCoin (XLN) ve ekosistemiyle ilgili diğer dijital varlıklar hakkında halka açık verileri bir araya getiren bir platformdur. Blockchain gezginlerinden, ortak borsalardan ve halka açık üçüncü taraf API'lerinden bilgi toplar ve yalnızca bilgilendirme amacıyla görüntüler.","GaláxiaLunarium emir gerçekleştirmez, fon tutmaz, işlem yapmaz ve hiçbir işlemde aracı olarak hareket etmez. Bahsedilen veya görüntülenen tüm işlemler, münhasır sorumluluğu kendilerine ait olan üçüncü taraf platformlarında gerçekleşir.","Bu sitedeki hiçbir şey herhangi bir varlığı satın almak, satmak veya elde tutmak için bir öneri teşkil etmez. Bilgiler yalnızca bilgilendirme amacıyla sunulmaktadır ve yatırım, finansal, hukuki veya vergi tavsiyesi olarak yorumlanmamalıdır.","Görüntülenen veriler, kamuya açık üçüncü taraf kaynaklardan (blockchain gezginleri, borsalar, piyasa API'leri) elde edilir ve ağ gecikmeleri, kaynak istikrarsızlığı veya teknik arızalar nedeniyle güncel olmayabilir, eksik veya hatalı olabilir. Bu bilgilerin doğruluğunu, eksiksizliğini veya sürekli erişilebilirliğini garanti etmiyoruz.","Bu sitenin kullanımı tamamen kullanıcının kendi riskindedir. GaláxiaLunarium, operatörleri, katkıda bulunanları ve bağlı kuruluşları, burada sunulan bilgilerin kullanımından veya bunlara dayanarak alınan kararlardan kaynaklanan herhangi bir finansal kayıp, doğrudan veya dolaylı zarar veya herhangi bir sonuçtan sorumlu değildir.","Bu site, borsalara, cüzdanlara veya diğer üçüncü taraf hizmetlerine bağlantılar içerebilir. Bu platformlar üzerinde herhangi bir kontrolümüz yoktur ve içeriklerinden, güvenliklerinden, erişilebilirliklerinden veya uygulamalarından sorumlu değiliz. Herhangi bir üçüncü taraf hizmetinin kullanımı, o platformun kendi şartlarına ve politikalarına tabidir.","Dijital varlıklar son derece değişkendir ve yatırılan sermayenin tamamının kaybedilmesi olasılığı da dahil olmak üzere önemli risk taşır. Herhangi bir finansal karar vermeden önce bağımsız profesyonel danışmanlık alın ve kendi araştırmanızı yapın (DYOR).","GaláxiaLunarium'a erişerek ve onu kullanarak, bu Yasal Uyarıyı tamamen okuduğunuzu, anladığınızı ve kabul ettiğinizi onaylarsınız."]},
  uk: {title:"Юридичне повідомлення та умови використання", h:["1. Що таке GaláxiaLunarium","2. Ми не є біржею чи брокером","3. Це не фінансова консультація","4. Точність даних","5. Відмова від відповідальності","6. Посилання та послуги третіх сторін","7. Ризики цифрових активів","8. Прийняття умов"], p:["GaláxiaLunarium — це агрегатор публічних даних про LunariumCoin (XLN) та інші цифрові активи, пов'язані з її екосистемою. Він збирає та відображає інформацію з блокчейн-оглядачів, партнерських бірж та публічних API третіх сторін виключно з інформаційною метою.","GaláxiaLunarium не виконує ордери, не зберігає кошти, не здійснює угоди та не виступає посередником у жодній транзакції. Будь-яка згадана чи показана торгівля відбувається на платформах третіх сторін під їхню виключну відповідальність.","Ніщо на цьому сайті не є рекомендацією купувати, продавати чи утримувати будь-який актив. Інформація надається виключно з інформаційною метою і не повинна тлумачитися як інвестиційна, фінансова, юридична чи податкова консультація.","Відображені дані отримані з публічних джерел третіх сторін (блокчейн-оглядачі, біржі, ринкові API) і можуть бути застарілими, неповними або неправильними через затримки мережі, нестабільність джерел чи технічні збої. Ми не гарантуємо точність, повноту чи безперервну доступність цієї інформації.","Використання цього сайту здійснюється виключно на власний ризик користувача. GaláxiaLunarium, його оператори, співробітники та афілійовані особи не несуть відповідальності за будь-які фінансові втрати, прямі чи непрямі збитки, або будь-які наслідки, що виникають внаслідок використання наданої тут інформації чи рішень, прийнятих на її основі.","Цей сайт може містити посилання на біржі, гаманці чи інші послуги третіх сторін. Ми не контролюємо ці платформи і не несемо відповідальності за їхній вміст, безпеку, доступність чи практики. Використання будь-якої послуги третьої сторони регулюється власними умовами та політикою цієї платформи.","Цифрові активи є дуже волатильними та несуть значний ризик, включаючи можливість повної втрати інвестованого капіталу. Перш ніж приймати будь-яке фінансове рішення, зверніться за незалежною професійною консультацією та проведіть власне дослідження (DYOR).","Отримуючи доступ до GaláxiaLunarium та використовуючи його, ви підтверджуєте, що прочитали, зрозуміли та повністю погоджуєтеся з цим Юридичним повідомленням."]},
  zh: {title:"法律声明与使用条款", h:["1. GaláxiaLunarium是什么","2. 我们不是交易所或经纪商","3. 这不是财务建议","4. 数据准确性","5. 免责声明","6. 第三方链接和服务","7. 数字资产风险","8. 条款接受"], p:["GaláxiaLunarium是一个关于LunariumCoin（XLN）及其生态系统相关其他数字资产的公开数据聚合平台。它从区块链浏览器、合作交易所和第三方公开API收集并展示信息，仅供参考之用。","GaláxiaLunarium不执行订单，不托管资金，不进行交易，也不在任何交易中充当中介。任何提及或显示的交易均在第三方平台上进行，由该平台自行承担全部责任。","本网站上的任何内容均不构成购买、出售或持有任何资产的建议。所提供的信息仅供参考，不应被解释为投资、财务、法律或税务建议。","所显示的数据来自第三方公开来源（区块链浏览器、交易所、市场API），由于网络延迟、数据源不稳定或技术故障，可能已过时、不完整或不准确。我们不保证这些信息的准确性、完整性或持续可用性。","使用本网站完全由用户自行承担风险。GaláxiaLunarium及其运营者、贡献者和关联方对因使用本网站提供的信息或据此做出的决定而产生的任何财务损失、直接或间接损害或任何后果概不负责。","本网站可能包含指向交易所、钱包或其他第三方服务的链接。我们无法控制这些平台，也不对其内容、安全性、可用性或做法负责。使用任何第三方服务均受该平台自身条款和政策的约束。","数字资产波动性极高，存在重大风险，包括投入资本全部损失的可能性。在做出任何财务决定之前，请寻求独立的专业建议并自行研究（DYOR）。","访问并使用GaláxiaLunarium即表示您确认已阅读、理解并完全同意本法律声明。"]},
  "zh-TW": {title:"法律聲明與使用條款", h:["1. GaláxiaLunarium是什麼","2. 我們不是交易所或經紀商","3. 這不是財務建議","4. 資料準確性","5. 免責聲明","6. 第三方連結和服務","7. 數位資產風險","8. 條款接受"], p:["GaláxiaLunarium是一個關於LunariumCoin（XLN）及其生態系統相關其他數位資產的公開資料聚合平台。它從區塊鏈瀏覽器、合作交易所和第三方公開API收集並展示資訊，僅供參考之用。","GaláxiaLunarium不執行訂單，不託管資金，不進行交易，也不在任何交易中充當中介。任何提及或顯示的交易均在第三方平台上進行，由該平台自行承擔全部責任。","本網站上的任何內容均不構成購買、出售或持有任何資產的建議。所提供的資訊僅供參考，不應被解釋為投資、財務、法律或稅務建議。","所顯示的資料來自第三方公開來源（區塊鏈瀏覽器、交易所、市場API），由於網路延遲、資料來源不穩定或技術故障，可能已過時、不完整或不準確。我們不保證這些資訊的準確性、完整性或持續可用性。","使用本網站完全由使用者自行承擔風險。GaláxiaLunarium及其營運者、貢獻者和關聯方對因使用本網站提供的資訊或據此做出的決定而產生的任何財務損失、直接或間接損害或任何後果概不負責。","本網站可能包含指向交易所、錢包或其他第三方服務的連結。我們無法控制這些平台，也不對其內容、安全性、可用性或做法負責。使用任何第三方服務均受該平台自身條款和政策的約束。","數位資產波動性極高，存在重大風險，包括投入資本全部損失的可能性。在做出任何財務決定之前，請尋求獨立的專業建議並自行研究（DYOR）。","存取並使用GaláxiaLunarium即表示您確認已閱讀、理解並完全同意本法律聲明。"]}
};

