// ---- Public API documentation (top of the Documentação page, anchor #api). The endpoints are
// served by backend/public-api.js.
var PUBLIC_API_URL = 'https://galaxia.lunariumcoin.com/api/v1';
var API_ENDPOINTS = [
  '/coins', '/coins/{id}', '/coins/{id}/markets', '/coins/{id}/ohlcv?range=7D&exchange={exchange_id}', '/coins/{id}/network',
  '/coins/{id}/audit', '/coins/{id}/rewards', '/exchanges', '/exchanges/{id}', '/fx'
];

function renderApiDocs(lang){
  var t = API_DOC_I18N[lang] || API_DOC_I18N.en;
  var rows = API_ENDPOINTS.map(function(ep, i){
    return '<tr><td><code><b>GET</b>' + escHtml(ep) + '</code></td><td>' + escHtml(t[7 + i]) + '</td></tr>';
  }).join('');
  return '<section id=api class=apiDocs>' +
    '<h3 class=apiH>' + escHtml(t[0]) + ' <span class=pill>v1</span></h3>' +
    '<p class=mini style="line-height:1.6">' + escHtml(t[1]) + '</p>' +
    '<div class=apiFacts>' +
      '<div><label>Base URL</label><code>' + PUBLIC_API_URL + '</code></div>' +
      '<div><label>Auth</label>' + escHtml(t[2]) + '</div>' +
      '<div><label>Rate limit</label>' + escHtml(t[3]) + '</div>' +
      '<div><label>Cache</label>' + escHtml(t[4]) + '</div>' +
    '</div>' +
    '<h4>' + escHtml(t[5]) + '</h4>' +
    '<div class=tableWrap><table class=apiTable><thead><tr><th>Endpoint</th><th>' + escHtml(t[6]) + '</th></tr></thead><tbody>' + rows + '</tbody></table></div>' +
    '<h4>' + escHtml(t[17]) + '</h4>' +
    '<pre class=apiCode>curl ' + PUBLIC_API_URL + '/coins/xln</pre>' +
    '<button type=button class=btn id=apiTryBtn>' + escHtml(t[18]) + '</button>' +
    '<pre class=apiCode id=apiTryOut style=display:none></pre>' +
    '<p class=mini style="line-height:1.6;margin-top:14px">' + escHtml(t[19]) + '</p>' +
    '<p class=mini><a class=link href="/api/v1/openapi.json" target=_blank rel=noopener>' + escHtml(t[20]) + '</a> · <a class=link href="/api/v1" target=_blank rel=noopener>/api/v1</a></p>' +
  '</section>' + renderPlansSection(lang) + '<hr class=docsDivider>';
}

function wireApiDocs(){
  fillPlans(currentLang());
  wirePlanKeyBox(currentLang());
  var btn = document.getElementById('apiTryBtn');
  var out = document.getElementById('apiTryOut');
  if(!btn || !out) return;
  btn.onclick = function(){
    out.style.display = '';
    out.textContent = '…';
    fetch(PROXY_BASE + '/api/v1/coins/xln').then(function(r){ return r.json(); }).then(function(d){
      out.textContent = JSON.stringify(d, null, 2);
    }).catch(function(e){ out.textContent = String(e); });
  };
}

