// ---- API plans: the sidebar box (real plan/usage of the viewer's own API key, or the free plan)
// and the plans section of the Documentação page (#planos). Prices come from /api/v1/plans: a fixed
// USD value whose XLN amount follows the market. The key is kept only in this browser.
var PLAN_KEY_STORAGE = 'galaxia_api_key';
var FREE_PER_MINUTE = 30;
var apiAccountCache = null;

function planT(lang){ return PLAN_I18N[lang] || PLAN_I18N.en; }
function getSavedApiKey(){ try{ return localStorage.getItem(PLAN_KEY_STORAGE) || ''; }catch(e){ return ''; } }
function setSavedApiKey(k){ try{ if(k) localStorage.setItem(PLAN_KEY_STORAGE, k); else localStorage.removeItem(PLAN_KEY_STORAGE); }catch(e){} }
function fmtCompactNum(v){
  if(v >= 1e6) return (v / 1e6).toFixed(2).replace(/\.?0+$/, '') + 'M';
  if(v >= 1e3) return (v / 1e3).toFixed(1).replace(/\.0$/, '') + 'K';
  return String(v);
}
// Resolves with the account of that key, or null when the key is invalid/expired (cached 60s).
function getApiAccount(key){
  if(apiAccountCache && apiAccountCache.key === key && Date.now() - apiAccountCache.at < 60000) return Promise.resolve(apiAccountCache.data);
  return fetch(PROXY_BASE + '/api/v1/account', { headers: { 'X-API-Key': key } })
    .then(function(r){ return r.json(); })
    .then(function(d){
      var a = d && d.ok ? d.data : null;
      apiAccountCache = { key: key, data: a, at: Date.now() };
      return a;
    });
}

function openPlansDocs(){
  var d = document.getElementById('docsBtn');
  if(d) d.click();
  setTimeout(function(){ var el = document.getElementById('planos'); if(el) el.scrollIntoView({ behavior:'smooth', block:'start' }); }, 80);
}

function renderPlanBox(lang){
  lang = lang || currentLang();
  var box = document.getElementById('planBox');
  if(!box) return;
  var t = planT(lang);
  var nameEl = box.querySelector('.planBoxName'), pill = box.querySelector('.planBoxPill');
  var label = box.querySelector('.planBoxLabel'), meter = box.querySelector('.meter'), value = box.querySelector('.planBoxValue');
  var btn = box.querySelector('.planBoxBtn');
  btn.onclick = function(){ openAccount(); };
  var accNav = ACC_NAV_I18N[lang] || ACC_NAV_I18N.en;
  function showFree(note){
    nameEl.textContent = t[16];
    pill.textContent = t[20];
    label.textContent = t[22];
    meter.style.display = 'none';
    value.textContent = note || (FREE_PER_MINUTE + ' ' + t[3] + ' ' + t[18]);
    btn.textContent = accountState ? accNav : accT(lang)[0];
  }
  if(accountState){
    // signed in: the account's highest active plan
    var ks = accountState.keys.filter(function(k){ return k.state === 'active'; }).sort(function(x, y){ return (y.per_month || 0) - (x.per_month || 0); });
    if(!ks.length){ showFree(); return; }
    var k = ks[0];
    nameEl.textContent = k.plan_name;
    pill.textContent = t[20];
    label.textContent = t[14];
    meter.style.display = '';
    meter.querySelector('i').style.width = (k.per_month ? Math.min(100, k.used_this_month / k.per_month * 100) : 0).toFixed(1) + '%';
    value.textContent = fmtCompactNum(k.used_this_month) + ' / ' + (k.per_month ? fmtCompactNum(k.per_month) : '∞');
    btn.textContent = accNav;
    return;
  }
  var key = getSavedApiKey();
  if(!key){ showFree(); return; }
  showFree();
  getApiAccount(key).then(function(a){
    if(getSavedApiKey() !== key) return;
    if(!a){ showFree(t[13]); return; }
    nameEl.textContent = a.plan_name;
    pill.textContent = t[20];
    label.textContent = t[14];
    meter.style.display = '';
    meter.querySelector('i').style.width = (a.per_month ? Math.min(100, a.used_this_month / a.per_month * 100) : 0).toFixed(1) + '%';
    value.textContent = fmtCompactNum(a.used_this_month) + ' / ' + (a.per_month ? fmtCompactNum(a.per_month) : '∞');
    btn.textContent = t[21];
  }).catch(function(){});
}

function renderPlansSection(lang){
  var t = planT(lang);
  return '<section id=planos class=apiDocs>' +
    '<h3 class=apiH>' + escHtml(t[0]) + '</h3>' +
    '<p class=mini style="line-height:1.6">' + escHtml(t[1]) + '</p>' +
    '<div class=planCards id=planCards><p class=mini>…</p></div>' +
    '<p class=mini id=planPriceNote style="line-height:1.6"></p>' +
    '<p class=mini style="line-height:1.6">' + escHtml(t[41]) + ' ' + escHtml(t[8]) + '</p>' +
    '<div class=planKeyBox><label for=planKeyInput>' + escHtml(t[10]) + '</label>' +
      '<div class=planKeyRow><input id=planKeyInput type=password autocomplete=off spellcheck=false placeholder="glx_…">' +
      '<button type=button class=btn id=planKeySave>' + escHtml(t[11]) + '</button>' +
      '<button type=button class=btn id=planKeyRemove>' + escHtml(t[12]) + '</button></div>' +
      '<p class=mini id=planKeyStatus></p>' +
      '<p class=mini style="color:var(--mut)">' + escHtml(t[24]) + ' ' + escHtml(t[19]) + '</p>' +
    '</div>' +
    '<h3 class=apiH id=listagem style="margin-top:28px">' + escHtml((LISTING_I18N[lang] || LISTING_I18N.en)[0]) + '</h3>' +
    '<p class=mini style="line-height:1.6">' + escHtml((LISTING2_I18N[lang] || LISTING2_I18N.en)[6]) + '</p>' +
    '<p class=mini style="line-height:1.6">' + escHtml((LISTING_AUDIT_I18N[lang] || LISTING_AUDIT_I18N.en)[1]) + '</p>' +
    '<div class=planCards id=listingCards><p class=mini>…</p></div>' +
  '</section>';
}

