function fillPlans(lang){
  var t = planT(lang);
  var LF = LIFETIME_I18N[lang] || LIFETIME_I18N.en;
  var box = document.getElementById('planCards');
  if(!box) return;
  var nf = function(v, digits){ return Number(v).toLocaleString(lang, { minimumFractionDigits: digits || 0, maximumFractionDigits: digits || 0 }); };
  fetch(PROXY_BASE + '/api/v1/plans').then(function(r){ return r.json(); }).then(function(d){
    if(!d || !d.ok) return;
    var checkoutOn = !!(d.data.checkout && d.data.checkout.enabled);
    box.innerHTML = d.data.plans.map(function(p){
      // a plan paid once (lifetime key) shows no "/month"; the monthly ones keep it
      var usd = p.price_usd != null ? p.price_usd : p.price_usd_month, xlnAmount = p.price_xln != null ? p.price_xln : p.price_xln_month;
      var free = !usd;
      var price = free ? escHtml(t[2]) : nf(xlnAmount) + ' XLN' + (p.lifetime ? '' : '<span>' + escHtml(t[23]) + '</span>');
      var sub = free ? '&nbsp;' : '≈ US$ ' + nf(usd, 2) + (p.lifetime ? ' · ' + escHtml(LF[0]) : '');
      var limits = '<li>' + nf(p.per_minute) + ' ' + escHtml(t[3]) + (free ? ' ' + escHtml(t[18]) : '') + '</li>' +
        '<li>' + (p.per_month ? nf(p.per_month) + ' ' + escHtml(t[4]) : escHtml(t[5])) + '</li>' +
        (p.lifetime ? '<li>' + escHtml(LF[1]) + '</li>' : '') + (p.includes_coin_audit ? '<li>' + escHtml(LF[2]) + '</li>' : '');
      var cta = free ? '' : (checkoutOn
        ? '<button type=button class=btn data-subscribe="' + escHtml(p.id) + '">' + escHtml(t[25]) + '</button>'
        : '<button type=button class=btn disabled>' + escHtml(t[38]) + '</button>');
      return '<div class="planCard' + (p.id === 'basic' ? ' planCardHi' : '') + '"><div class=planName>' + escHtml(free ? t[16] : p.name) + '</div>' +
        '<div class=planPrice>' + price + '</div><div class=planSub>' + sub + '</div><ul>' + limits + '</ul>' + cta + '</div>';
    }).join('');
    var lt = LISTING_I18N[lang] || LISTING_I18N.en;
    var lbox = document.getElementById('listingCards');
    var l2 = LISTING2_I18N[lang] || LISTING2_I18N.en;
    var slaTxt = function(s){ return s === '48h' ? l2[7] : (/10 business/.test(s || '') ? l2[8] : (s || '')); };
    if(lbox) lbox.innerHTML = (d.data.listings || []).map(function(l){
      var std = l.tier === 'standard';
      var on = checkoutOn && l.available;
      var price = std ? escHtml(t[2]) : (l.available ? nf(l.price_xln) + ' XLN' : escHtml(t[38]));
      var sub = std ? escHtml(l2[2]) : (l.available ? '≈ US$ ' + nf(l.price_usd, 2) + ' · ' + escHtml(l2[3].replace('{sla}', slaTxt(l.review_deadline))) : '&nbsp;');
      return '<div class="planCard' + (std ? '' : ' planCardHi') + '"><div class=planName>' + escHtml((l.type === 'exchange' ? lt[4] : (std ? lt[3] : (LISTING_AUDIT_I18N[lang] || LISTING_AUDIT_I18N.en)[0])) + ' · ' + (std ? l2[0] : l2[1])) + '</div>' +
        '<div class=planPrice>' + price + '</div><div class=planSub>' + sub + '</div>' +
        (on ? '<button type=button class=btn data-subscribe="' + escHtml(l.id) + '">' + escHtml(std ? l2[4] : l2[5]) + '</button>' : '<button type=button class=btn disabled>' + escHtml(t[38]) + '</button>') + '</div>';
    }).join('');
    Array.prototype.forEach.call(document.querySelectorAll('#planos [data-subscribe]'), function(b){
      b.onclick = function(){ openCheckoutWindow(b.getAttribute('data-subscribe'), lang); };
    });
    var note = document.getElementById('planPriceNote');
    if(note) note.textContent = PLAN_NOTE_I18N[lang] || PLAN_NOTE_I18N.en;
  }).catch(function(){});
}

function wirePlanKeyBox(lang){
  var t = planT(lang);
  var input = document.getElementById('planKeyInput'), status = document.getElementById('planKeyStatus');
  var save = document.getElementById('planKeySave'), remove = document.getElementById('planKeyRemove');
  if(!input || !status || !save || !remove) return;
  var nf = function(v){ return Number(v).toLocaleString(lang); };
  function show(a){
    if(!a){ status.style.color = 'var(--red)'; status.textContent = t[13]; return; }
    status.style.color = 'var(--green)';
    status.textContent = a.plan_name + ' · ' + a.owner + ' · ' + t[14] + ': ' + nf(a.used_this_month) + (a.per_month ? ' / ' + nf(a.per_month) : '') +
      (a.expires_at ? ' · ' + t[15] + ' ' + new Date(a.expires_at).toLocaleDateString(lang) : (a.lifetime ? ' · ' + (LIFETIME_I18N[lang] || LIFETIME_I18N.en)[1] : ''));
  }
  var saved = getSavedApiKey();
  if(saved){ input.value = saved; getApiAccount(saved).then(show).catch(function(){}); }
  save.onclick = function(){
    var k = input.value.trim();
    if(!k) return;
    status.style.color = ''; status.textContent = '…';
    apiAccountCache = null;
    getApiAccount(k).then(function(a){
      if(a) setSavedApiKey(k);
      show(a);
      renderPlanBox(lang);
    }).catch(function(){ status.textContent = t[13]; });
  };
  remove.onclick = function(){
    setSavedApiKey('');
    apiAccountCache = null;
    input.value = '';
    status.textContent = '';
    renderPlanBox(lang);
  };
}

