// Purchases open in their own window: registration -> payment -> ticket (checkout.html).
function openCheckoutWindow(productId, lang){
  window.open('checkout.html?product=' + encodeURIComponent(productId) + '&lang=' + encodeURIComponent(lang), '_blank', 'noopener');
}

