function favT(lang){ return FAV_I18N[lang] || FAV_I18N.en; }

// ---- Favorites (★ on coins/tokens and exchanges). Kept in this browser and, when signed in, in the
// account (merged on sign-in), where each favorite coin can carry an e-mail price alert.
var FAV_KEY = 'galaxia_favs';
var favs = (function(){
  try{ var v = JSON.parse(localStorage.getItem(FAV_KEY) || 'null'); if(v && Array.isArray(v.coins) && Array.isArray(v.exchanges)) return v; }catch(e){}
  return { coins: [], exchanges: [] };
})();
var favSyncedAccount = null;
var coinSummaries = {}; // id -> public API summary (filled by refreshCoinTables)
function saveFavsLocal(){ try{ localStorage.setItem(FAV_KEY, JSON.stringify(favs)); }catch(e){} }
function isFav(kind, id){ return favs[kind].indexOf(id) >= 0; }
function uniqIds(list){ var seen = {}; return list.filter(function(x){ if(seen[x]) return false; seen[x] = 1; return true; }); }
function pushFavs(){
  if(!accountState) return Promise.resolve();
  return accApi('/favorites', { coins: favs.coins, exchanges: favs.exchanges }).then(function(d){
    if(d.ok && accountState){ accountState.favorites = d.data.favorites; accountState.alerts = d.data.alerts; }
  }).catch(function(){});
}
function syncFavsWithAccount(){
  if(!accountState){ favSyncedAccount = null; return; }
  if(favSyncedAccount === accountState.account.id) return;
  favSyncedAccount = accountState.account.id;
  var srv = accountState.favorites || { coins: [], exchanges: [] };
  var merged = { coins: uniqIds(srv.coins.concat(favs.coins)), exchanges: uniqIds(srv.exchanges.concat(favs.exchanges)) };
  var changed = merged.coins.length !== srv.coins.length || merged.exchanges.length !== srv.exchanges.length;
  favs = merged;
  saveFavsLocal();
  if(changed) pushFavs();
  refreshStars();
}
function starHtml(kind, id){
  var on = isFav(kind, id), f = favT(currentLang());
  return '<button type=button class="favStar' + (on ? ' on' : '') + '" data-fav-kind=' + kind + ' data-fav-id="' + escHtml(id) + '" title="' + escHtml(on ? f[3] : f[2]) + '" aria-label="' + escHtml(on ? f[3] : f[2]) + '" aria-pressed=' + on + '>' + (on ? '★' : '☆') + '</button>';
}
function refreshStars(){
  var f = favT(currentLang());
  Array.prototype.forEach.call(document.querySelectorAll('.favStar'), function(b){
    var on = isFav(b.getAttribute('data-fav-kind'), b.getAttribute('data-fav-id'));
    b.classList.toggle('on', on);
    b.textContent = on ? '★' : '☆';
    b.title = on ? f[3] : f[2];
    b.setAttribute('aria-label', b.title);
    b.setAttribute('aria-pressed', on);
  });
}
function toggleFav(kind, id){
  if(!favs[kind]) return;
  var i = favs[kind].indexOf(id);
  if(i >= 0) favs[kind].splice(i, 1); else favs[kind].push(id);
  saveFavsLocal();
  refreshStars();
  pushFavs().then(function(){
    var cv = document.getElementById('contaView');
    if(accountState && cv && cv.classList.contains('show')) renderAccount(currentLang());
    refreshListViews();
  });
}
// capture phase: a star inside a clickable row must not also open the row
document.addEventListener('click', function(e){
  var b = e.target && e.target.closest ? e.target.closest('.favStar') : null;
  if(!b) return;
  e.preventDefault();
  e.stopPropagation();
  toggleFav(b.getAttribute('data-fav-kind'), b.getAttribute('data-fav-id'));
}, true);
// stars on every coin row of the Moedas / Tokens / Mineração / Stake tables
function addCoinRowStars(){
  Array.prototype.forEach.call(document.querySelectorAll('.moedasView tr.coinRow[data-coin]'), function(tr){
    var cell = tr.children[1];
    if(!cell || cell.querySelector('.favStar')) return;
    (cell.querySelector('.platform') || cell).insertAdjacentHTML('afterbegin', starHtml('coins', tr.getAttribute('data-coin')));
  });
}
// star next to the coin name on the dashboard
function updateCoinHeaderStar(id){
  var asset = document.querySelector('#dashboardTop .asset');
  if(!asset) return;
  var b = asset.querySelector('.favStar');
  if(!b){ asset.querySelector('h1').insertAdjacentHTML('afterend', starHtml('coins', id)); b = asset.querySelector('.favStar'); b.classList.add('favStarBig'); }
  b.setAttribute('data-fav-id', id);
  refreshStars();
}

// exchanges list: highest 24h volume first, and a search box
function sortExchangeRows(){
  var tbody = document.getElementById('exchangesTbody');
  if(!tbody) return;
  var rows = Array.prototype.slice.call(tbody.querySelectorAll('.exRankRow'));
  rows.sort(function(a, b){ return (parseFloat(b.getAttribute('data-vol')) || -1) - (parseFloat(a.getAttribute('data-vol')) || -1); });
  rows.forEach(function(r, i){ tbody.appendChild(r); r.children[0].textContent = i + 1; });
  var empty = tbody.querySelector('.exNoResult');
  if(empty) tbody.appendChild(empty);
}
function ensureExchangeSearch(lang){
  var head = document.querySelector('#exchangesListPane .sectionAlt');
  if(!head) return;
  var f = favT(lang);
  var input = document.getElementById('exSearch');
  if(!input){
    head.insertAdjacentHTML('beforeend', '<input id=exSearch class=exSearch type=search autocomplete=off>');
    input = document.getElementById('exSearch');
    input.addEventListener('input', filterExchangeRows);
  }
  input.placeholder = f[0];
  input.setAttribute('aria-label', f[0]);
}
function filterExchangeRows(){
  var tbody = document.getElementById('exchangesTbody');
  var input = document.getElementById('exSearch');
  if(!tbody || !input) return;
  var q = input.value.trim().toLowerCase();
  var shown = 0;
  Array.prototype.forEach.call(tbody.querySelectorAll('.exRankRow'), function(r){
    var id = r.getAttribute('data-exchange');
    var name = (EXCHANGES[id] && EXCHANGES[id].name || id).toLowerCase();
    var ok = !q || name.indexOf(q) >= 0 || id.indexOf(q) >= 0;
    r.style.display = ok ? '' : 'none';
    if(ok) shown++;
  });
  var empty = tbody.querySelector('.exNoResult');
  if(!shown){
    if(!empty){ tbody.insertAdjacentHTML('beforeend', '<tr class=exNoResult><td colspan=7 class=mini></td></tr>'); empty = tbody.querySelector('.exNoResult'); }
    empty.firstChild.textContent = favT(currentLang())[1];
  }else if(empty) empty.remove();
}

// search box on the Moedas / Tokens / Mineração / Stake lists (name or symbol)
function ensureCoinSearches(lang){
  var f = favT(lang);
  ['moedasView', 'tokensView', 'mineracaoView', 'stakeView'].forEach(function(vid){
    var view = document.getElementById(vid);
    var head = view && view.querySelector('.section');
    if(!head) return;
    var input = head.querySelector('.coinSearch');
    if(!input){
      head.querySelector('h2').insertAdjacentHTML('afterend', '<input class="exSearch coinSearch" type=search autocomplete=off>');
      input = head.querySelector('.coinSearch');
      input.addEventListener('input', function(){ filterCoinRows(view, input); });
    }
    input.placeholder = f[17];
    input.setAttribute('aria-label', f[17]);
    filterCoinRows(view, input);
  });
}
function filterCoinRows(view, input){
  var tbody = view.querySelector('tbody');
  if(!tbody) return;
  var q = input.value.trim().toLowerCase();
  var shown = 0;
  Array.prototype.forEach.call(tbody.querySelectorAll('tr.coinRow[data-coin]'), function(tr){
    var id = tr.getAttribute('data-coin'), c = COINS[id] || {};
    var hay = (id + ' ' + (c.ticker || '') + ' ' + (c.name || '') + ' ' + tr.children[1].textContent).toLowerCase();
    var ok = !q || hay.indexOf(q) >= 0;
    tr.style.display = ok ? '' : 'none';
    if(ok) shown++;
  });
  var empty = tbody.querySelector('.coinNoResult');
  if(!shown && q){
    if(!empty){ tbody.insertAdjacentHTML('beforeend', '<tr class=coinNoResult><td colspan=6 class=mini></td></tr>'); empty = tbody.querySelector('.coinNoResult'); }
    empty.firstChild.textContent = favT(currentLang())[18];
  }else if(empty) empty.remove();
}

