var ACC2_I18N = {
  en: ['Confirm your e-mail', 'We sent a confirmation link to {email}. Open the message and click the button to activate your account.', 'Resend e-mail', 'Done! If the account is still waiting for confirmation, a new e-mail is on its way.', 'Confirm your e-mail before signing in. Check your inbox and the spam folder.', 'Enter your e-mail and we will send you a link to create a new password.', 'Send link', 'If this e-mail has an account, a link to reset the password is on its way. It is valid for 1 hour.', 'E-mail confirmed! Your account is active.', 'Password changed. You are signed in.', 'This link is invalid or has expired.', 'Didn’t get it? Check the spam folder.'],
  ru: ['Подтвердите e-mail', 'Мы отправили ссылку для подтверждения на {email}. Откройте письмо и нажмите кнопку, чтобы активировать аккаунт.', 'Отправить повторно', 'Готово! Если аккаунт ещё ждёт подтверждения, новое письмо уже в пути.', 'Подтвердите e-mail перед входом. Проверьте входящие и папку «Спам».', 'Введите e-mail, и мы пришлём ссылку для создания нового пароля.', 'Отправить ссылку', 'Если для этого e-mail есть аккаунт, ссылка для сброса пароля уже в пути. Она действует 1 час.', 'E-mail подтверждён! Ваш аккаунт активен.', 'Пароль изменён. Вы вошли в аккаунт.', 'Ссылка недействительна или устарела.', 'Не пришло? Проверьте папку «Спам».'],
  de: ['Bestätigen Sie Ihre E-Mail', 'Wir haben einen Bestätigungslink an {email} gesendet. Öffnen Sie die Nachricht und klicken Sie auf den Button, um Ihr Konto zu aktivieren.', 'E-Mail erneut senden', 'Erledigt! Falls das Konto noch auf Bestätigung wartet, ist eine neue E-Mail unterwegs.', 'Bestätigen Sie Ihre E-Mail vor der Anmeldung. Prüfen Sie Posteingang und Spam-Ordner.', 'Geben Sie Ihre E-Mail ein, und wir senden Ihnen einen Link für ein neues Passwort.', 'Link senden', 'Falls zu dieser E-Mail ein Konto existiert, ist ein Link zum Zurücksetzen unterwegs. Er ist 1 Stunde gültig.', 'E-Mail bestätigt! Ihr Konto ist aktiv.', 'Passwort geändert. Sie sind angemeldet.', 'Dieser Link ist ungültig oder abgelaufen.', 'Nichts erhalten? Prüfen Sie den Spam-Ordner.'],
  pl: ['Potwierdź e-mail', 'Wysłaliśmy link potwierdzający na {email}. Otwórz wiadomość i kliknij przycisk, aby aktywować konto.', 'Wyślij ponownie', 'Gotowe! Jeśli konto nadal czeka na potwierdzenie, nowy e-mail jest w drodze.', 'Potwierdź e-mail przed zalogowaniem. Sprawdź skrzynkę i folder spam.', 'Podaj e-mail, a wyślemy link do utworzenia nowego hasła.', 'Wyślij link', 'Jeśli ten e-mail ma konto, link do resetu hasła jest w drodze. Jest ważny przez 1 godzinę.', 'E-mail potwierdzony! Twoje konto jest aktywne.', 'Hasło zmienione. Jesteś zalogowany.', 'Ten link jest nieprawidłowy lub wygasł.', 'Nie dotarło? Sprawdź folder spam.'],
  es: ['Confirma tu correo', 'Enviamos un enlace de confirmación a {email}. Abre el mensaje y pulsa el botón para activar tu cuenta.', 'Reenviar correo', '¡Listo! Si la cuenta aún espera confirmación, un nuevo correo va en camino.', 'Confirma tu correo antes de iniciar sesión. Revisa la bandeja de entrada y la carpeta de spam.', 'Escribe tu correo y te enviaremos un enlace para crear una nueva contraseña.', 'Enviar enlace', 'Si este correo tiene una cuenta, un enlace para restablecer la contraseña va en camino. Es válido durante 1 hora.', '¡Correo confirmado! Tu cuenta está activa.', 'Contraseña cambiada. Has iniciado sesión.', 'Este enlace no es válido o ha caducado.', '¿No llegó? Revisa la carpeta de spam.'],
  vi: ['Xác nhận e-mail', 'Chúng tôi đã gửi liên kết xác nhận đến {email}. Mở thư và nhấn nút để kích hoạt tài khoản.', 'Gửi lại e-mail', 'Xong! Nếu tài khoản vẫn chờ xác nhận, e-mail mới đang được gửi.', 'Hãy xác nhận e-mail trước khi đăng nhập. Kiểm tra hộp thư đến và thư rác.', 'Nhập e-mail, chúng tôi sẽ gửi liên kết để tạo mật khẩu mới.', 'Gửi liên kết', 'Nếu e-mail này có tài khoản, liên kết đặt lại mật khẩu đang được gửi. Có hiệu lực 1 giờ.', 'Đã xác nhận e-mail! Tài khoản của bạn đã hoạt động.', 'Đã đổi mật khẩu. Bạn đã đăng nhập.', 'Liên kết không hợp lệ hoặc đã hết hạn.', 'Chưa nhận được? Hãy kiểm tra thư rác.'],
  fr: ['Confirmez votre e-mail', 'Nous avons envoyé un lien de confirmation à {email}. Ouvrez le message et cliquez sur le bouton pour activer votre compte.', 'Renvoyer l’e-mail', 'C’est fait ! Si le compte attend encore sa confirmation, un nouvel e-mail est en route.', 'Confirmez votre e-mail avant de vous connecter. Vérifiez la boîte de réception et les spams.', 'Saisissez votre e-mail et nous vous enverrons un lien pour créer un nouveau mot de passe.', 'Envoyer le lien', 'Si cet e-mail a un compte, un lien de réinitialisation est en route. Il est valable 1 heure.', 'E-mail confirmé ! Votre compte est actif.', 'Mot de passe modifié. Vous êtes connecté.', 'Ce lien est invalide ou a expiré.', 'Rien reçu ? Vérifiez les spams.'],
  'pt-BR': ['Confirme seu e-mail', 'Enviamos um link de confirmação para {email}. Abra a mensagem e clique no botão para ativar sua conta.', 'Reenviar e-mail', 'Pronto! Se a conta ainda estiver aguardando confirmação, um novo e-mail está a caminho.', 'Confirme seu e-mail antes de entrar. Veja a caixa de entrada e a pasta de spam.', 'Informe seu e-mail e enviaremos um link para criar uma nova senha.', 'Enviar link', 'Se este e-mail tiver uma conta, o link para redefinir a senha está a caminho. Ele vale por 1 hora.', 'E-mail confirmado! Sua conta está ativa.', 'Senha alterada. Você já está conectado.', 'Este link é inválido ou expirou.', 'Não chegou? Veja a pasta de spam.'],
  ar: ['أكّد بريدك الإلكتروني', 'أرسلنا رابط تأكيد إلى {email}. افتح الرسالة واضغط الزر لتفعيل حسابك.', 'إعادة الإرسال', 'تم! إذا كان الحساب لا يزال بانتظار التأكيد، فرسالة جديدة في الطريق.', 'أكّد بريدك الإلكتروني قبل تسجيل الدخول. تحقق من البريد الوارد ومجلد الرسائل غير المرغوبة.', 'أدخل بريدك الإلكتروني وسنرسل لك رابطًا لإنشاء كلمة مرور جديدة.', 'إرسال الرابط', 'إذا كان لهذا البريد حساب، فرابط إعادة التعيين في الطريق. وهو صالح لمدة ساعة.', 'تم تأكيد البريد! حسابك مفعّل.', 'تم تغيير كلمة المرور. أنت مسجّل الدخول.', 'هذا الرابط غير صالح أو منتهي الصلاحية.', 'لم يصلك؟ تحقق من مجلد الرسائل غير المرغوبة.'],
  bg: ['Потвърдете имейла си', 'Изпратихме връзка за потвърждение до {email}. Отворете писмото и натиснете бутона, за да активирате акаунта си.', 'Изпрати отново', 'Готово! Ако акаунтът още чака потвърждение, ново писмо е на път.', 'Потвърдете имейла си преди вход. Проверете входящата поща и папката за спам.', 'Въведете имейла си и ще ви изпратим връзка за нова парола.', 'Изпрати връзка', 'Ако този имейл има акаунт, връзката за смяна на паролата е на път. Валидна е 1 час.', 'Имейлът е потвърден! Акаунтът ви е активен.', 'Паролата е сменена. Влезли сте.', 'Тази връзка е невалидна или изтекла.', 'Не е пристигнало? Проверете папката за спам.'],
  cs: ['Potvrďte svůj e-mail', 'Poslali jsme potvrzovací odkaz na {email}. Otevřete zprávu a klikněte na tlačítko pro aktivaci účtu.', 'Poslat znovu', 'Hotovo! Pokud účet stále čeká na potvrzení, nový e-mail je na cestě.', 'Před přihlášením potvrďte e-mail. Zkontrolujte doručenou poštu i spam.', 'Zadejte e-mail a pošleme vám odkaz pro vytvoření nového hesla.', 'Poslat odkaz', 'Pokud k tomuto e-mailu existuje účet, odkaz pro obnovení hesla je na cestě. Platí 1 hodinu.', 'E-mail potvrzen! Váš účet je aktivní.', 'Heslo změněno. Jste přihlášeni.', 'Tento odkaz je neplatný nebo vypršel.', 'Nepřišlo? Zkontrolujte spam.'],
  da: ['Bekræft din e-mail', 'Vi har sendt et bekræftelseslink til {email}. Åbn beskeden og klik på knappen for at aktivere din konto.', 'Send igen', 'Klaret! Hvis kontoen stadig venter på bekræftelse, er en ny e-mail på vej.', 'Bekræft din e-mail, før du logger ind. Tjek indbakken og spam-mappen.', 'Indtast din e-mail, så sender vi et link til at oprette en ny adgangskode.', 'Send link', 'Hvis denne e-mail har en konto, er et link til nulstilling på vej. Det er gyldigt i 1 time.', 'E-mail bekræftet! Din konto er aktiv.', 'Adgangskode ændret. Du er logget ind.', 'Linket er ugyldigt eller udløbet.', 'Ikke modtaget? Tjek spam-mappen.'],
  el: ['Επιβεβαιώστε το e-mail σας', 'Στείλαμε σύνδεσμο επιβεβαίωσης στο {email}. Ανοίξτε το μήνυμα και πατήστε το κουμπί για να ενεργοποιήσετε τον λογαριασμό.', 'Επαναποστολή', 'Έγινε! Αν ο λογαριασμός περιμένει ακόμη επιβεβαίωση, ένα νέο e-mail είναι καθ’ οδόν.', 'Επιβεβαιώστε το e-mail πριν συνδεθείτε. Ελέγξτε τα εισερχόμενα και τα ανεπιθύμητα.', 'Εισαγάγετε το e-mail σας και θα σας στείλουμε σύνδεσμο για νέο κωδικό.', 'Αποστολή συνδέσμου', 'Αν αυτό το e-mail έχει λογαριασμό, ο σύνδεσμος επαναφοράς είναι καθ’ οδόν. Ισχύει 1 ώρα.', 'Το e-mail επιβεβαιώθηκε! Ο λογαριασμός σας είναι ενεργός.', 'Ο κωδικός άλλαξε. Έχετε συνδεθεί.', 'Ο σύνδεσμος δεν είναι έγκυρος ή έχει λήξει.', 'Δεν το λάβατε; Ελέγξτε τα ανεπιθύμητα.'],
  fi: ['Vahvista sähköpostisi', 'Lähetimme vahvistuslinkin osoitteeseen {email}. Avaa viesti ja aktivoi tili painikkeesta.', 'Lähetä uudelleen', 'Valmis! Jos tili odottaa yhä vahvistusta, uusi viesti on matkalla.', 'Vahvista sähköpostisi ennen kirjautumista. Tarkista saapuneet ja roskaposti.', 'Anna sähköpostisi, niin lähetämme linkin uuden salasanan luomiseen.', 'Lähetä linkki', 'Jos tällä sähköpostilla on tili, nollauslinkki on matkalla. Se on voimassa 1 tunnin.', 'Sähköposti vahvistettu! Tilisi on aktiivinen.', 'Salasana vaihdettu. Olet kirjautunut sisään.', 'Linkki on virheellinen tai vanhentunut.', 'Eikö tullut? Tarkista roskaposti.'],
  he: ['אשרו את המייל', 'שלחנו קישור אישור אל {email}. פתחו את ההודעה ולחצו על הכפתור כדי להפעיל את החשבון.', 'שליחה חוזרת', 'בוצע! אם החשבון עדיין ממתין לאישור, מייל חדש בדרך.', 'אשרו את המייל לפני הכניסה. בדקו את תיבת הדואר ואת תיקיית הספאם.', 'הזינו את המייל ונשלח קישור ליצירת סיסמה חדשה.', 'שליחת קישור', 'אם למייל הזה יש חשבון, קישור לאיפוס הסיסמה בדרך. הוא בתוקף לשעה.', 'המייל אושר! החשבון שלכם פעיל.', 'הסיסמה שונתה. אתם מחוברים.', 'הקישור אינו תקין או שפג תוקפו.', 'לא הגיע? בדקו בתיקיית הספאם.'],
  hi: ['अपना ई-मेल पुष्टि करें', 'हमने {email} पर पुष्टि लिंक भेजा है। संदेश खोलें और खाता सक्रिय करने के लिए बटन दबाएँ।', 'फिर से भेजें', 'हो गया! अगर खाता अभी भी पुष्टि की प्रतीक्षा में है, तो नया ई-मेल आ रहा है।', 'साइन इन से पहले ई-मेल की पुष्टि करें। इनबॉक्स और स्पैम फ़ोल्डर देखें।', 'अपना ई-मेल दर्ज करें, हम नया पासवर्ड बनाने का लिंक भेजेंगे।', 'लिंक भेजें', 'अगर इस ई-मेल का खाता है, तो पासवर्ड रीसेट लिंक आ रहा है। यह 1 घंटे तक मान्य है।', 'ई-मेल की पुष्टि हो गई! आपका खाता सक्रिय है।', 'पासवर्ड बदल गया। आप साइन इन हैं।', 'यह लिंक अमान्य है या समाप्त हो गया है।', 'नहीं मिला? स्पैम फ़ोल्डर देखें।'],
  hr: ['Potvrdite svoj e-mail', 'Poslali smo poveznicu za potvrdu na {email}. Otvorite poruku i kliknite gumb za aktivaciju računa.', 'Pošalji ponovno', 'Gotovo! Ako račun još čeka potvrdu, novi e-mail je na putu.', 'Potvrdite e-mail prije prijave. Provjerite ulaznu poštu i neželjenu poštu.', 'Upišite svoj e-mail i poslat ćemo vam poveznicu za novu lozinku.', 'Pošalji poveznicu', 'Ako ovaj e-mail ima račun, poveznica za novu lozinku je na putu. Vrijedi 1 sat.', 'E-mail potvrđen! Vaš račun je aktivan.', 'Lozinka promijenjena. Prijavljeni ste.', 'Ova poveznica nije valjana ili je istekla.', 'Nije stiglo? Provjerite neželjenu poštu.'],
  hu: ['Erősítse meg e-mail-címét', 'Megerősítő linket küldtünk ide: {email}. Nyissa meg az üzenetet, és a gombbal aktiválja fiókját.', 'Újraküldés', 'Kész! Ha a fiók még megerősítésre vár, új e-mail van úton.', 'Belépés előtt erősítse meg e-mail-címét. Nézze meg a beérkezett és a spam mappát.', 'Adja meg e-mail-címét, és küldünk egy linket új jelszó létrehozásához.', 'Link küldése', 'Ha ehhez az e-mailhez tartozik fiók, a visszaállító link úton van. 1 óráig érvényes.', 'E-mail megerősítve! Fiókja aktív.', 'Jelszó módosítva. Be van jelentkezve.', 'Ez a link érvénytelen vagy lejárt.', 'Nem érkezett meg? Nézze meg a spam mappát.'],
  id: ['Konfirmasi e-mail Anda', 'Kami mengirim tautan konfirmasi ke {email}. Buka pesan dan klik tombol untuk mengaktifkan akun Anda.', 'Kirim ulang', 'Selesai! Jika akun masih menunggu konfirmasi, e-mail baru sedang dikirim.', 'Konfirmasi e-mail sebelum masuk. Periksa kotak masuk dan folder spam.', 'Masukkan e-mail Anda, kami akan mengirim tautan untuk membuat kata sandi baru.', 'Kirim tautan', 'Jika e-mail ini memiliki akun, tautan atur ulang sedang dikirim. Berlaku 1 jam.', 'E-mail terkonfirmasi! Akun Anda aktif.', 'Kata sandi diubah. Anda sudah masuk.', 'Tautan ini tidak valid atau sudah kedaluwarsa.', 'Belum masuk? Periksa folder spam.'],
  it: ['Conferma la tua e-mail', 'Abbiamo inviato un link di conferma a {email}. Apri il messaggio e clicca il pulsante per attivare l’account.', 'Invia di nuovo', 'Fatto! Se l’account attende ancora la conferma, una nuova e-mail è in arrivo.', 'Conferma l’e-mail prima di accedere. Controlla la posta in arrivo e lo spam.', 'Inserisci la tua e-mail e ti invieremo un link per creare una nuova password.', 'Invia link', 'Se questa e-mail ha un account, un link per reimpostare la password è in arrivo. È valido 1 ora.', 'E-mail confermata! Il tuo account è attivo.', 'Password cambiata. Hai effettuato l’accesso.', 'Questo link non è valido o è scaduto.', 'Non è arrivata? Controlla lo spam.'],
  ja: ['メールアドレスを確認してください', '{email} に確認リンクを送信しました。メールを開き、ボタンを押してアカウントを有効化してください。', 'メールを再送信', '完了しました。アカウントが確認待ちの場合、新しいメールが届きます。', 'ログインする前にメールアドレスを確認してください。受信トレイと迷惑メールフォルダをご確認ください。', 'メールアドレスを入力すると、新しいパスワードを作成するリンクをお送りします。', 'リンクを送信', 'このメールアドレスのアカウントがある場合、再設定リンクをお送りしました。有効期限は 1 時間です。', 'メールアドレスが確認されました。アカウントは有効です。', 'パスワードを変更しました。ログイン済みです。', 'このリンクは無効か、有効期限が切れています。', '届かない場合は迷惑メールフォルダをご確認ください。'],
  ko: ['이메일을 인증하세요', '{email}(으)로 인증 링크를 보냈습니다. 메일을 열고 버튼을 눌러 계정을 활성화하세요.', '이메일 다시 보내기', '완료! 계정이 아직 인증 대기 중이라면 새 이메일이 발송됩니다.', '로그인하기 전에 이메일을 인증하세요. 받은편지함과 스팸함을 확인하세요.', '이메일을 입력하면 새 비밀번호를 만들 수 있는 링크를 보내 드립니다.', '링크 보내기', '이 이메일의 계정이 있다면 재설정 링크가 발송됩니다. 1시간 동안 유효합니다.', '이메일이 인증되었습니다! 계정이 활성화되었습니다.', '비밀번호가 변경되었습니다. 로그인되었습니다.', '이 링크는 유효하지 않거나 만료되었습니다.', '받지 못하셨나요? 스팸함을 확인하세요.'],
  lt: ['Patvirtinkite el. paštą', 'Išsiuntėme patvirtinimo nuorodą į {email}. Atidarykite laišką ir paspauskite mygtuką, kad aktyvuotumėte paskyrą.', 'Siųsti dar kartą', 'Atlikta! Jei paskyra dar laukia patvirtinimo, naujas laiškas jau keliauja.', 'Prieš prisijungdami patvirtinkite el. paštą. Patikrinkite gautus ir šlamšto aplanką.', 'Įveskite el. paštą ir atsiųsime nuorodą naujam slaptažodžiui sukurti.', 'Siųsti nuorodą', 'Jei šis el. paštas turi paskyrą, slaptažodžio atkūrimo nuoroda jau keliauja. Ji galioja 1 valandą.', 'El. paštas patvirtintas! Jūsų paskyra aktyvi.', 'Slaptažodis pakeistas. Esate prisijungę.', 'Ši nuoroda neteisinga arba nebegalioja.', 'Negavote? Patikrinkite šlamšto aplanką.'],
  nl: ['Bevestig je e-mail', 'We hebben een bevestigingslink naar {email} gestuurd. Open het bericht en klik op de knop om je account te activeren.', 'Opnieuw versturen', 'Klaar! Als het account nog op bevestiging wacht, is er een nieuwe e-mail onderweg.', 'Bevestig je e-mail voordat je inlogt. Kijk in je inbox en de spammap.', 'Vul je e-mail in en we sturen je een link om een nieuw wachtwoord te maken.', 'Link versturen', 'Als dit e-mailadres een account heeft, is er een resetlink onderweg. Die is 1 uur geldig.', 'E-mail bevestigd! Je account is actief.', 'Wachtwoord gewijzigd. Je bent ingelogd.', 'Deze link is ongeldig of verlopen.', 'Niet ontvangen? Kijk in de spammap.'],
  no: ['Bekreft e-posten din', 'Vi har sendt en bekreftelseslenke til {email}. Åpne meldingen og klikk på knappen for å aktivere kontoen.', 'Send på nytt', 'Ferdig! Hvis kontoen fortsatt venter på bekreftelse, er en ny e-post på vei.', 'Bekreft e-posten før du logger inn. Sjekk innboksen og søppelpost.', 'Skriv inn e-posten din, så sender vi en lenke for å lage nytt passord.', 'Send lenke', 'Hvis denne e-posten har en konto, er en tilbakestillingslenke på vei. Den er gyldig i 1 time.', 'E-post bekreftet! Kontoen din er aktiv.', 'Passord endret. Du er logget inn.', 'Lenken er ugyldig eller utløpt.', 'Ikke mottatt? Sjekk søppelpost.'],
  ro: ['Confirmă-ți e-mailul', 'Am trimis un link de confirmare la {email}. Deschide mesajul și apasă butonul pentru a-ți activa contul.', 'Retrimite e-mailul', 'Gata! Dacă contul încă așteaptă confirmarea, un e-mail nou e pe drum.', 'Confirmă e-mailul înainte de autentificare. Verifică inboxul și dosarul spam.', 'Introdu e-mailul și îți trimitem un link pentru o parolă nouă.', 'Trimite linkul', 'Dacă acest e-mail are un cont, linkul de resetare e pe drum. Este valabil 1 oră.', 'E-mail confirmat! Contul tău este activ.', 'Parolă schimbată. Ești autentificat.', 'Acest link este invalid sau a expirat.', 'Nu a ajuns? Verifică dosarul spam.'],
  sk: ['Potvrďte svoj e-mail', 'Poslali sme potvrdzovací odkaz na {email}. Otvorte správu a kliknite na tlačidlo na aktiváciu účtu.', 'Poslať znova', 'Hotovo! Ak účet stále čaká na potvrdenie, nový e-mail je na ceste.', 'Pred prihlásením potvrďte e-mail. Skontrolujte doručenú poštu aj spam.', 'Zadajte e-mail a pošleme vám odkaz na vytvorenie nového hesla.', 'Poslať odkaz', 'Ak k tomuto e-mailu existuje účet, odkaz na obnovenie hesla je na ceste. Platí 1 hodinu.', 'E-mail potvrdený! Váš účet je aktívny.', 'Heslo zmenené. Ste prihlásení.', 'Tento odkaz je neplatný alebo vypršal.', 'Neprišlo? Skontrolujte spam.'],
  sl: ['Potrdite svoj e-poštni naslov', 'Na {email} smo poslali povezavo za potrditev. Odprite sporočilo in kliknite gumb za aktivacijo računa.', 'Pošlji znova', 'Končano! Če račun še čaka na potrditev, je novo sporočilo na poti.', 'Pred prijavo potrdite e-pošto. Preverite prejeto pošto in neželeno pošto.', 'Vnesite e-pošto in poslali vam bomo povezavo za novo geslo.', 'Pošlji povezavo', 'Če ima ta e-pošta račun, je povezava za ponastavitev na poti. Velja 1 uro.', 'E-pošta potrjena! Vaš račun je aktiven.', 'Geslo spremenjeno. Prijavljeni ste.', 'Ta povezava je neveljavna ali je potekla.', 'Ni prispelo? Preverite neželeno pošto.'],
  sv: ['Bekräfta din e-post', 'Vi har skickat en bekräftelselänk till {email}. Öppna meddelandet och klicka på knappen för att aktivera kontot.', 'Skicka igen', 'Klart! Om kontot fortfarande väntar på bekräftelse är ett nytt e-postmeddelande på väg.', 'Bekräfta din e-post innan du loggar in. Kolla inkorgen och skräpposten.', 'Ange din e-post så skickar vi en länk för att skapa ett nytt lösenord.', 'Skicka länk', 'Om e-postadressen har ett konto är en återställningslänk på väg. Den gäller i 1 timme.', 'E-post bekräftad! Ditt konto är aktivt.', 'Lösenordet är ändrat. Du är inloggad.', 'Länken är ogiltig eller har gått ut.', 'Inget mejl? Kolla skräpposten.'],
  th: ['ยืนยันอีเมลของคุณ', 'เราได้ส่งลิงก์ยืนยันไปที่ {email} เปิดข้อความแล้วกดปุ่มเพื่อเปิดใช้งานบัญชี', 'ส่งอีเมลอีกครั้ง', 'เรียบร้อย! หากบัญชียังรอการยืนยัน อีเมลใหม่กำลังส่งไป', 'โปรดยืนยันอีเมลก่อนเข้าสู่ระบบ ตรวจดูกล่องจดหมายและโฟลเดอร์สแปม', 'กรอกอีเมลของคุณ แล้วเราจะส่งลิงก์สำหรับสร้างรหัสผ่านใหม่', 'ส่งลิงก์', 'หากอีเมลนี้มีบัญชี ลิงก์รีเซ็ตรหัสผ่านกำลังส่งไป ใช้ได้ 1 ชั่วโมง', 'ยืนยันอีเมลแล้ว! บัญชีของคุณใช้งานได้', 'เปลี่ยนรหัสผ่านแล้ว คุณเข้าสู่ระบบแล้ว', 'ลิงก์นี้ไม่ถูกต้องหรือหมดอายุแล้ว', 'ไม่ได้รับใช่ไหม? ตรวจดูโฟลเดอร์สแปม'],
  tr: ['E-postanızı doğrulayın', '{email} adresine bir doğrulama bağlantısı gönderdik. Mesajı açın ve hesabınızı etkinleştirmek için düğmeye tıklayın.', 'Tekrar gönder', 'Tamam! Hesap hâlâ doğrulama bekliyorsa yeni bir e-posta yolda.', 'Giriş yapmadan önce e-postanızı doğrulayın. Gelen kutusunu ve spam klasörünü kontrol edin.', 'E-postanızı girin, yeni şifre oluşturmanız için bir bağlantı gönderelim.', 'Bağlantı gönder', 'Bu e-postaya ait bir hesap varsa sıfırlama bağlantısı yolda. 1 saat geçerlidir.', 'E-posta doğrulandı! Hesabınız aktif.', 'Şifre değiştirildi. Giriş yaptınız.', 'Bu bağlantı geçersiz veya süresi dolmuş.', 'Gelmedi mi? Spam klasörünü kontrol edin.'],
  uk: ['Підтвердьте e-mail', 'Ми надіслали посилання для підтвердження на {email}. Відкрийте лист і натисніть кнопку, щоб активувати акаунт.', 'Надіслати повторно', 'Готово! Якщо акаунт ще чекає підтвердження, новий лист уже в дорозі.', 'Підтвердьте e-mail перед входом. Перевірте вхідні та папку «Спам».', 'Введіть e-mail, і ми надішлемо посилання для створення нового пароля.', 'Надіслати посилання', 'Якщо для цього e-mail є акаунт, посилання для скидання вже в дорозі. Воно дійсне 1 годину.', 'E-mail підтверджено! Ваш акаунт активний.', 'Пароль змінено. Ви увійшли.', 'Посилання недійсне або застаріле.', 'Не прийшло? Перевірте папку «Спам».'],
  zh: ['请确认您的邮箱', '我们已向 {email} 发送确认链接。请打开邮件并点击按钮激活账户。', '重新发送邮件', '完成！如果账户仍在等待确认，新邮件正在发送。', '登录前请先确认邮箱。请查看收件箱和垃圾邮件文件夹。', '输入您的邮箱，我们将发送创建新密码的链接。', '发送链接', '如果该邮箱有账户，重置密码的链接正在发送，1 小时内有效。', '邮箱已确认！您的账户已激活。', '密码已更改，您已登录。', '此链接无效或已过期。', '没收到？请查看垃圾邮件文件夹。'],
  'zh-TW': ['請確認您的電子郵件', '我們已向 {email} 寄出確認連結。請開啟郵件並點擊按鈕啟用帳戶。', '重新寄送郵件', '完成！如果帳戶仍在等待確認，新郵件正在寄送。', '登入前請先確認電子郵件。請查看收件匣和垃圾郵件資料夾。', '輸入您的電子郵件，我們將寄送建立新密碼的連結。', '寄送連結', '如果該電子郵件有帳戶，重設密碼的連結正在寄送，1 小時內有效。', '電子郵件已確認！您的帳戶已啟用。', '密碼已變更，您已登入。', '此連結無效或已過期。', '沒收到？請查看垃圾郵件資料夾。']
};
function acc2T(lang){ return ACC2_I18N[lang] || ACC2_I18N.en; }
function accT(lang){ return ACC_I18N[lang] || ACC_I18N.en; }
function accApi(path, body){
  var opts = body
    ? { method:'POST', headers:{ 'Content-Type':'application/json' }, body: JSON.stringify(body), credentials:'same-origin' }
    : { credentials:'same-origin' };
  return fetch(PROXY_BASE + '/api/account' + path, opts).then(function(r){
    return r.json().catch(function(){ return { ok:false }; }).then(function(d){ d.status = r.status; return d; });
  });
}
// the account's e-mails (price alerts, password, orders) go out in the language the person is using
// on the site: recorded whenever the signed-in page is opened in a different language
function syncAccountLang(){
  if(!accountState || !accountState.account) return;
  // the visitor's language is only set once the page has finished loading (language-final.js)
  if(document.readyState !== 'complete'){ window.addEventListener('load', function(){ setTimeout(syncAccountLang, 600); }, { once: true }); return; }
  var lang = currentLang();
  if(accountState.account.lang === lang) return;
  accountState.account.lang = lang;
  accApi('/lang', { lang: lang }).catch(function(){});
}
function loadAccount(){
  return accApi('/me').then(function(d){ accountState = d.ok ? d.data : null; syncFavsWithAccount(); syncAccountLang(); return accountState; })
    .catch(function(){ accountState = null; return null; });
}
function accError(d, a){
  var map = { credentials: a[13], exists: a[14], rate: a[15], password: a[7] };
  return (d && map[d.code]) || (d && d.error) || 'error';
}
function openAccount(mode){
  if(window.GalaxiaShowView) window.GalaxiaShowView('conta');
  var btn = document.getElementById('accountBtn');
  if(btn && typeof setNav === 'function') setNav(btn);
  try{ var u = new URL(location.href); u.searchParams.delete('coin'); u.searchParams.set('view', 'conta'); history.replaceState(null, '', u.toString()); }catch(e){}
  // always fresh: the panel shows live request counts
  var go = function(){ renderAccount(currentLang(), mode); };
  if(accountState) go();
  loadAccount().then(function(){ renderPlanBox(); go(); });
}
function accField(id, label, type, extra){
  return '<label class=accFld><span>' + escHtml(label) + '</span><input id=' + id + ' type=' + (type || 'text') + (extra || '') + '></label>';
}
function productLabel(o, lang){
  if(o.kind === 'listing'){
    var lt = LISTING_I18N[lang] || LISTING_I18N.en, l2 = LISTING2_I18N[lang] || LISTING2_I18N.en;
    var coinName = o.tier === 'standard' ? lt[3] : (LISTING_AUDIT_I18N[lang] || LISTING_AUDIT_I18N.en)[0];
    return (o.listing_type === 'exchange' ? lt[4] : coinName) + ' · ' + (o.tier === 'standard' ? l2[0] : l2[1]) + (o.listing_name ? ' — ' + o.listing_name : '');
  }
  return 'API ' + String(o.plan || '').replace(/^./, function(c){ return c.toUpperCase(); });
}

// Links from the account e-mails: ?verify=<token> confirms the e-mail, ?reset=<token> opens the new
// password form. The token is taken out of the address bar at once (history, shared screenshots).
var accountLinkToken = null;
(function(){
  try{
    var u = new URL(location.href);
    var v = u.searchParams.get('verify'), r = u.searchParams.get('reset');
    if(v || r){
      accountLinkToken = v ? { kind:'verify', token:v } : { kind:'reset', token:r };
      u.searchParams.delete('verify'); u.searchParams.delete('reset');
      history.replaceState(null, '', u.toString());
    }
  }catch(e){}
})();

function renderAccount(lang, mode){
  var box = document.getElementById('contaApp');
  if(!box) return;
  var a = accT(lang), b = acc2T(lang);
  var title = document.querySelector('.contaViewTitle');
  if(title) title.textContent = ACC_NAV_I18N[lang] || ACC_NAV_I18N.en;
  if(accountLinkToken && !mode){
    var link = accountLinkToken;
    if(link.kind === 'verify'){
      accountLinkToken = null;
      accApi('/verify', { token: link.token, lang: currentLang() }).then(function(d){
        if(!d.ok){ renderAccount.notice = { text: b[10], bad: true }; accountState = null; return renderAccount(lang, 'login'); }
        renderAccount.notice = { text: b[8] };
        return loadAccount().then(function(){ renderPlanBox(lang); renderAccount(lang); });
      });
      box.innerHTML = '<div class=accCard><p class=mini>…</p></div>';
      return;
    }
    mode = 'reset';
  }
  var notice = renderAccount.notice;
  renderAccount.notice = null;
  var noticeHtml = notice ? '<p class=mini style="color:' + (notice.bad ? 'var(--red)' : 'var(--green)') + ';font-weight:600">' + escHtml(notice.text) + '</p>' : '';
  if(accountState && mode !== 'reset'){
    renderAccount.lastMode = null;
    renderAccountPanel(box, lang, a);
    if(noticeHtml){ var card = box.querySelector('.accCard'); if(card) card.insertAdjacentHTML('afterbegin', noticeHtml); }
    return;
  }
  mode = mode || 'login';
  renderAccount.lastMode = mode;
  var back = '<p class=mini><a href=# class=link data-acc=login>' + escHtml(a[48]) + '</a></p>';

  if(mode === 'register'){
    box.innerHTML = '<div class=accCard><h3>' + escHtml(a[1]) + '</h3>' +
      accField('accName', a[5], 'text', ' autocomplete=name maxlength=80') + accField('accEmail', a[3], 'email', ' autocomplete=email maxlength=120') +
      accField('accCompany', a[6], 'text', ' autocomplete=organization maxlength=80') +
      accField('accPass', a[4] + ' (' + a[7] + ')', 'password', ' autocomplete=new-password maxlength=200') +
      '<p class=coErr id=accErr></p><button type=button class=btn id=accGo>' + escHtml(a[1]) + '</button>' + back + '</div>';
  }else if(mode === 'forgot'){
    box.innerHTML = '<div class=accCard><h3>' + escHtml(a[11]) + '</h3><p class=mini>' + escHtml(b[5]) + '</p>' +
      accField('accEmail', a[3], 'email', ' autocomplete=email maxlength=120') +
      '<p class=coErr id=accErr></p><button type=button class=btn id=accGo>' + escHtml(b[6]) + '</button>' + back + '</div>';
  }else if(mode === 'reset'){
    box.innerHTML = '<div class=accCard><h3>' + escHtml(a[11]) + '</h3>' +
      accField('accPass', a[10] + ' (' + a[7] + ')', 'password', ' autocomplete=new-password maxlength=200') +
      '<p class=coErr id=accErr></p><button type=button class=btn id=accGo>' + escHtml(a[11]) + '</button>' + back + '</div>';
  }else if(mode === 'check-email'){
    var email = renderAccount.email || '';
    box.innerHTML = '<div class=accCard><h3>' + escHtml(b[0]) + '</h3>' + noticeHtml +
      '<p class=mini>' + escHtml(b[1]).replace('{email}', '<b>' + escHtml(email) + '</b>') + '</p><p class=mini>' + escHtml(b[11]) + '</p>' +
      '<p class=coErr id=accErr></p><button type=button class=btn id=accGo>' + escHtml(b[2]) + '</button>' + back + '</div>';
  }else{
    box.innerHTML = '<div class=accCard><h3>' + escHtml(a[0]) + '</h3>' + noticeHtml + '<p class=mini>' + escHtml(a[37]) + '</p>' +
      accField('accEmail', a[3], 'email', ' autocomplete=email') + accField('accPass', a[4], 'password', ' autocomplete=current-password') +
      '<p class=coErr id=accErr></p><button type=button class=btn id=accGo>' + escHtml(a[0]) + '</button>' +
      '<p class=mini><a href=# class=link data-acc=register>' + escHtml(a[1]) + '</a> · <a href=# class=link data-acc=forgot>' + escHtml(a[8]) + '</a></p></div>';
  }
  Array.prototype.forEach.call(box.querySelectorAll('[data-acc]'), function(l){
    l.onclick = function(e){ e.preventDefault(); if(mode === 'reset') accountLinkToken = null; renderAccount(lang, l.getAttribute('data-acc')); };
  });
  var val = function(id){ var el = document.getElementById(id); return el ? el.value.trim() : ''; };
  var pass = function(){ var el = document.getElementById('accPass'); return el ? el.value : ''; };
  var go = document.getElementById('accGo');
  var submit = function(){
    var err = document.getElementById('accErr');
    err.textContent = '';
    go.disabled = true;
    var req;
    if(mode === 'register') req = accApi('/register', { name: val('accName'), email: val('accEmail'), company: val('accCompany'), password: pass(), lang: currentLang() });
    else if(mode === 'forgot') req = accApi('/forgot', { email: val('accEmail'), lang: currentLang() });
    else if(mode === 'reset') req = accApi('/reset', { token: accountLinkToken ? accountLinkToken.token : '', new_password: pass(), lang: currentLang() });
    else if(mode === 'check-email') req = accApi('/resend', { email: renderAccount.email || '', lang: currentLang() });
    else req = accApi('/login', { email: val('accEmail'), password: pass(), lang: currentLang() });
    req.then(function(d){
      go.disabled = false;
      if(!d.ok){
        if(d.code === 'unverified'){ renderAccount.email = val('accEmail'); renderAccount.notice = { text: b[4], bad: true }; return renderAccount(lang, 'check-email'); }
        if(d.code === 'link'){ accountLinkToken = null; renderAccount.notice = { text: b[10], bad: true }; return renderAccount(lang, 'forgot'); }
        err.textContent = accError(d, a);
        return;
      }
      if(mode === 'register'){ renderAccount.email = d.data.email; return renderAccount(lang, 'check-email'); }
      if(mode === 'check-email'){ renderAccount.notice = { text: b[3] }; return renderAccount(lang, 'check-email'); }
      if(mode === 'forgot'){ renderAccount.notice = { text: b[7] }; return renderAccount(lang, 'login'); }
      if(mode === 'reset'){ accountLinkToken = null; renderAccount.notice = { text: b[9] }; }
      return loadAccount().then(function(){ renderPlanBox(lang); renderAccount(lang); });
    }).catch(function(e){ go.disabled = false; err.textContent = String(e); });
  };
  go.onclick = submit;
  Array.prototype.forEach.call(box.querySelectorAll('input'), function(i){ i.onkeydown = function(e){ if(e.key === 'Enter') submit(); }; });
}

function wireCopyInside(root, lang){
  var co = PLAN_I18N_CHECKOUT[lang] || PLAN_I18N_CHECKOUT.en;
  Array.prototype.forEach.call(root.querySelectorAll('.coCopy'), function(b){
    b.onclick = function(){
      var v = b.getAttribute('data-copy');
      if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(v).then(function(){
        b.textContent = co[12]; setTimeout(function(){ b.textContent = co[11]; }, 1500);
      }, function(){});
    };
  });
}

function renderAccountPanel(box, lang, a){
  var s = accountState, p = planT(lang), pc = PLANCHG_I18N[lang] || PLANCHG_I18N.en;
  var ct = CONTRACT_I18N[lang] || CONTRACT_I18N.en;
  var lf = LIFETIME_I18N[lang] || LIFETIME_I18N.en;
  var nf = function(v){ return Number(v).toLocaleString(lang); };
  var fmtD = function(x){ return x ? new Date(x).toLocaleDateString(lang) : '—'; };
  var stateLbl = { active: [a[44], 'var(--green)'], revoked: [a[45], 'var(--red)'], expired: [a[42], 'var(--amber)'], paused: [ct[4], 'var(--amber)'], cancelled: [ct[9], 'var(--red)'] };
  var statusLbl = { pending: a[39], confirming: a[40], paid: a[41], expired: a[42], registered: a[43] };
  var keysHtml = s.keys.length ? s.keys.map(function(k){
    var st = stateLbl[k.state] || [k.state, 'var(--mut)'];
    var pct = k.per_month ? Math.min(100, k.used_this_month / k.per_month * 100) : 0;
    return '<div class=accKey><div class=accKeyHead><b>' + escHtml(k.plan_name) + '</b> <code>' + escHtml(k.prefix) + '…</code>' +
      '<span class=pill style="color:' + st[1] + ';border-color:' + st[1] + '">' + escHtml(st[0]) + '</span></div>' +
      '<div class=meter><i style="width:' + pct.toFixed(1) + '%"></i></div>' +
      '<div class=accKeyStats><span>' + escHtml(a[19]) + ': <b>' + nf(k.used_this_month) + '</b>' + (k.per_month ? ' / ' + nf(k.per_month) : '') + '</span>' +
      '<span>' + escHtml(a[49]) + ': <b>' + (k.per_minute ? nf(k.per_minute) : '—') + '</b></span>' +
      '<span>' + escHtml(a[20]) + ': <b>' + (k.lifetime ? escHtml(lf[1]) : fmtD(k.expires_at)) + '</b></span></div>' +
      '<div class=accKeyBtns>' + (k.lifetime ? '' : '<button type=button class=btn data-renew="' + escHtml(k.plan) + '" data-key="' + escHtml(k.id) + '">' + escHtml(a[21]) + '</button>') +
      (k.coin_audit === 'available' && k.state === 'active' ? '<button type=button class=btn data-audit-req="' + escHtml(k.id) + '">' + escHtml(lf[6]) + '</button>' : '') +
      (!k.lifetime && k.state !== 'revoked' && k.state !== 'cancelled' ? '<button type=button class=btn data-change="' + escHtml(k.id) + '" data-plan="' + escHtml(k.plan) + '">' + escHtml(pc[0]) + '</button>' : '') +
      (k.state === 'active' ? '<button type=button class=btn data-rotate="' + escHtml(k.id) + '">' + escHtml(a[22]) + '</button>' : '') +
      (k.state === 'active' ? '<button type=button class=btn data-key-act=pause data-key="' + escHtml(k.id) + '">' + escHtml(ct[0]) + '</button>' : '') +
      (k.state === 'paused' ? '<button type=button class=btn data-key-act=resume data-key="' + escHtml(k.id) + '">' + escHtml(ct[1]) + '</button>' : '') +
      (k.state === 'active' || k.state === 'paused' ? '<button type=button class="btn ghost accDanger" data-key-cancel="' + escHtml(k.id) + '">' + escHtml(ct[2]) + '</button>' : '') +
      (k.state === 'revoked' || k.state === 'cancelled' || k.state === 'expired' ? '<button type=button class="btn ghost" data-key-act=remove data-key="' + escHtml(k.id) + '">' + escHtml(ct[3]) + '</button>' : '') + '</div>' +
      (k.state === 'paused' ? '<p class=mini style="margin:10px 0 0">' + escHtml(ct[8]) + '</p>' : '') +
      '<div class=accPlanChg id=planchg-' + escHtml(k.id) + ' hidden></div>' +
      '<div class=accNewKey id=newkey-' + escHtml(k.id) + '></div></div>';
  }).join('') : '<p class=mini>' + escHtml(a[28]) + '</p><button type=button class=btn id=accBuy>' + escHtml(a[38]) + '</button>';
  var ordersHtml = s.orders.length ? '<div class=tableWrap><table class=apiTable><thead><tr><th>Ticket</th><th>' + escHtml((CK_PRODUCT_LABEL[lang] || CK_PRODUCT_LABEL.en)) + '</th><th>Status</th><th></th></tr></thead><tbody>' +
    s.orders.map(function(o){
      var amount = o.included_in_plan ? lf[7] : o.free ? p[2] : (o.amount_xln ? nf(o.amount_xln) + ' XLN' : '');
      return '<tr><td>' + escHtml(o.ticket || '—') + '<div class=mini>' + fmtD(o.created_at) + '</div></td><td>' + escHtml(productLabel(o, lang)) + '<div class=mini>' + escHtml(amount) + '</div></td>' +
        '<td>' + escHtml(statusLbl[o.status] || o.status) + '</td>' +
        '<td><a class=link href="checkout.html?lang=' + encodeURIComponent(lang) + '#order=' + encodeURIComponent(o.order_id) + '" target=_blank rel=noopener>' + escHtml(a[26]) + '</a>' +
          (o.status === 'expired' ? ' <button type=button class="btn ghost accSmall" data-order-remove="' + escHtml(o.order_id) + '">' + escHtml(ct[3]) + '</button>' : '') + '</td></tr>';
    }).join('') + '</tbody></table></div>' : '<p class=mini>' + escHtml(a[27]) + '</p>';
  box.innerHTML =
    '<div class="accCard accHead"><div><h3>' + escHtml(a[16].replace('{name}', s.account.name)) + '</h3><p class=mini>' + escHtml(s.account.email) + (s.account.company ? ' · ' + escHtml(s.account.company) : '') + '</p></div>' +
      '<button type=button class=btn id=accLogout>' + escHtml(a[2]) + '</button></div>' +
    favoritesCardHtml(lang) +
    '<div class=accCard><h3>' + escHtml(a[17]) + '</h3>' + keysHtml +
      '<details class=accMore><summary>' + escHtml(a[31]) + '</summary><div class=coRow><input id=accClaimKey class=coInput type=password placeholder="glx_…" autocomplete=off><button type=button class=btn id=accClaimKeyGo>' + escHtml(a[32]) + '</button></div><p class=coErr id=accClaimKeyErr></p></details></div>' +
    '<div class=accCard><h3>' + escHtml(a[25]) + '</h3>' + ordersHtml +
      '<details class=accMore><summary>' + escHtml(a[29]) + '</summary><div class=coRow><input id=accClaimOrder class=coInput placeholder="' + escHtml(a[30]) + '" autocomplete=off><button type=button class=btn id=accClaimOrderGo>' + escHtml(a[32]) + '</button></div><p class=coErr id=accClaimOrderErr></p></details></div>' +
    '<div class=accCard><details class=accMore><summary>' + escHtml(a[33]) + '</summary>' +
      accField('accCur', a[34], 'password', ' autocomplete=current-password') + accField('accNew', a[10] + ' (' + a[7] + ')', 'password', ' autocomplete=new-password') +
      '<p class=coErr id=accPwErr></p><button type=button class=btn id=accPwGo>' + escHtml(a[35]) + '</button></details></div>';

  wireFavoritesCard(box, lang);
  var reload = function(){ return loadAccount().then(function(){ renderPlanBox(lang); renderAccount(lang); }); };
  document.getElementById('accLogout').onclick = function(){
    accApi('/logout', {}).then(function(){
      // signing out also forgets the API key kept in this browser (shared computers)
      accountState = null;
      setSavedApiKey('');
      apiAccountCache = null;
      renderPlanBox(lang);
      renderAccount(lang);
    });
  };
  var buy = document.getElementById('accBuy');
  if(buy) buy.onclick = openPlansDocs;
  Array.prototype.forEach.call(box.querySelectorAll('[data-renew]'), function(b){
    b.onclick = function(){ window.open('checkout.html?product=' + encodeURIComponent(b.getAttribute('data-renew')) + '&renew=' + encodeURIComponent(b.getAttribute('data-key')) + '&lang=' + encodeURIComponent(lang), '_blank', 'noopener'); };
  });
  // the coin listing and audit included in the key's plan: the request form, with nothing to pay
  Array.prototype.forEach.call(box.querySelectorAll('[data-audit-req]'), function(b){
    b.onclick = function(){ window.open('checkout.html?product=listing_coin&plan_key_id=' + encodeURIComponent(b.getAttribute('data-audit-req')) + '&lang=' + encodeURIComponent(lang), '_blank', 'noopener'); };
  });
  // change plan: the other paid plans, then the checkout window for the chosen one (applied to this key)
  Array.prototype.forEach.call(box.querySelectorAll('[data-change]'), function(b){
    b.onclick = function(){
      var id = b.getAttribute('data-change'), cur = b.getAttribute('data-plan');
      var pane = document.getElementById('planchg-' + id);
      if(!pane.hidden){ pane.hidden = true; return; }
      pane.hidden = false;
      pane.innerHTML = '<p class=mini>…</p>';
      fetch(PROXY_BASE + '/api/v1/plans').then(function(r){ return r.json(); }).then(function(d){
        if(!d || !d.ok) return;
        var nfx = function(v){ return Number(v).toLocaleString(lang); };
        pane.innerHTML = '<p class=mini><b>' + escHtml(pc[1]) + '</b></p><div class=accPlanList>' +
          d.data.plans.filter(function(pl){ return pl.price_usd_month > 0; }).map(function(pl){
            var isCur = pl.id === cur;
            return '<button type=button class="btn' + (isCur ? ' ghost' : '') + '"' + (isCur ? ' disabled' : ' data-pick="' + escHtml(pl.id) + '"') + '>' +
              '<b>' + escHtml(pl.name) + '</b> · ' + nfx(pl.price_xln_month) + ' XLN' + escHtml(p[23]) +
              '<span class=mini style="display:block;opacity:.8">' + nfx(pl.per_minute) + ' ' + escHtml(p[3]) + (pl.per_month ? ' · ' + nfx(pl.per_month) + ' ' + escHtml(p[4]) : '') + (isCur ? ' · ' + escHtml(pc[2]) : '') + '</span></button>';
          }).join('') + '</div><p class=mini>' + escHtml(pc[4]) + '</p><button type=button class="btn ghost" data-cancel>' + escHtml(pc[3]) + '</button>';
        Array.prototype.forEach.call(pane.querySelectorAll('[data-pick]'), function(x){
          x.onclick = function(){
            window.open('checkout.html?product=' + encodeURIComponent(x.getAttribute('data-pick')) + '&renew=' + encodeURIComponent(id) + '&from=' + encodeURIComponent(cur) + '&lang=' + encodeURIComponent(lang), '_blank', 'noopener');
          };
        });
        pane.querySelector('[data-cancel]').onclick = function(){ pane.hidden = true; };
      }).catch(function(){ pane.hidden = true; });
    };
  });
  // pause / resume / delete a contract, delete an expired order
  Array.prototype.forEach.call(box.querySelectorAll('[data-key-act]'), function(b){
    b.onclick = function(){
      b.disabled = true;
      accApi('/keys/' + encodeURIComponent(b.getAttribute('data-key')) + '/' + b.getAttribute('data-key-act'), {}).then(function(){ apiAccountCache = null; return reload(); }).catch(function(){ b.disabled = false; });
    };
  });
  Array.prototype.forEach.call(box.querySelectorAll('[data-order-remove]'), function(b){
    b.onclick = function(){
      b.disabled = true;
      accApi('/orders/' + encodeURIComponent(b.getAttribute('data-order-remove')) + '/remove', {}).then(function(){ return reload(); }).catch(function(){ b.disabled = false; });
    };
  });
  // cancel a contract: asked twice, with the consequences written out (no refund, cannot be undone)
  Array.prototype.forEach.call(box.querySelectorAll('[data-key-cancel]'), function(b){
    b.onclick = function(){
      var id = b.getAttribute('data-key-cancel');
      var pane = document.getElementById('planchg-' + id);
      pane.hidden = false;
      pane.innerHTML = '<p class=mini style="color:var(--red);font-weight:700">' + escHtml(ct[5]) + '</p>' +
        '<div class=accKeyBtns><button type=button class="btn accDanger" data-yes>' + escHtml(ct[6]) + '</button><button type=button class="btn ghost" data-no>' + escHtml(ct[7]) + '</button></div>';
      pane.querySelector('[data-no]').onclick = function(){ pane.hidden = true; };
      pane.querySelector('[data-yes]').onclick = function(){
        accApi('/keys/' + encodeURIComponent(id) + '/cancel', { confirm: true }).then(function(){ apiAccountCache = null; return reload(); });
      };
    };
  });
  Array.prototype.forEach.call(box.querySelectorAll('[data-rotate]'), function(b){
    b.onclick = function(){
      if(!window.confirm(a[23])) return;
      var id = b.getAttribute('data-rotate');
      accApi('/keys/' + encodeURIComponent(id) + '/rotate', {}).then(function(d){
        if(!d.ok) return;
        try{ localStorage.setItem('galaxia_api_key', d.data.api_key); }catch(e){}
        apiAccountCache = null;
        return reload().then(function(){ return d; });
      }).then(function(d){
        if(!d) return;
        var slot = document.getElementById('newkey-' + id);
        if(slot){
          slot.innerHTML = '<p class=mini>' + escHtml(a[24]) + '</p><div class=coRow><code class=coBig>' + escHtml(d.data.api_key) + '</code><button type=button class="btn coCopy" data-copy="' + escHtml(d.data.api_key) + '">' + escHtml((PLAN_I18N_CHECKOUT[lang] || PLAN_I18N_CHECKOUT.en)[11]) + '</button></div>';
          wireCopyInside(slot, lang);
        }
      });
    };
  });
  document.getElementById('accClaimKeyGo').onclick = function(){
    var err = document.getElementById('accClaimKeyErr');
    accApi('/claim-key', { api_key: document.getElementById('accClaimKey').value.trim() }).then(function(d){ if(!d.ok){ err.textContent = a[46]; return; } reload(); });
  };
  document.getElementById('accClaimOrderGo').onclick = function(){
    var err = document.getElementById('accClaimOrderErr');
    var raw = document.getElementById('accClaimOrder').value.trim();
    var h = new URLSearchParams((raw.split('#')[1] || ''));
    if(!h.get('order') || !h.get('token')){ err.textContent = a[46]; return; }
    accApi('/claim-order', { order_id: h.get('order'), token: h.get('token') }).then(function(d){ if(!d.ok){ err.textContent = a[46]; return; } reload(); });
  };
  document.getElementById('accPwGo').onclick = function(){
    var err = document.getElementById('accPwErr');
    accApi('/password', { current_password: document.getElementById('accCur').value, new_password: document.getElementById('accNew').value }).then(function(d){
      err.style.color = d.ok ? 'var(--green)' : '';
      err.textContent = d.ok ? a[36] : accError(d, a);
    });
  };
}
