function renderDisclaimer(){
  var lang = currentLang();
  var d = DISCLAIMER[lang] || DISCLAIMER.en;
  var titleEl = document.querySelector('.documentacaoViewTitle');
  var docsBtnEl = document.getElementById('docsBtn');
  if(titleEl) titleEl.textContent = (docsBtnEl && docsBtnEl.textContent.trim()) || d.title;
  var container = document.querySelector('.documentacaoSections');
  if(container){
    container.innerHTML = renderApiDocs(lang) +
      '<h3 class=apiH>' + d.title + '</h3>' +
      d.h.map(function(h, i){
        return '<h3 style="color:var(--text);margin:20px 0 8px;font-size:14px;font-weight:800">' + h + '</h3><p class=mini style="line-height:1.6">' + d.p[i] + '</p>';
      }).join('');
    wireApiDocs();
    if(location.hash === '#api' || location.hash === '#planos' || location.hash === '#listagem'){ var anchorEl = document.getElementById(location.hash.slice(1)); if(anchorEl) anchorEl.scrollIntoView({ block: 'start' }); }
  }
  try{
    var shareUrl = new URL(location.href);
    shareUrl.searchParams.delete('coin');
    shareUrl.searchParams.delete('exchange');
    shareUrl.searchParams.set('view', 'documentacao');
    history.replaceState(null, '', shareUrl.toString());
  }catch(e){}
}
