function showDisclaimerModalIfNeeded(){
  var seen = false;
  try{ seen = localStorage.getItem('galaxia_disclaimer_seen') === '1'; }catch(e){}
  if(seen) return;
  var modal = document.getElementById('disclaimerModal');
  if(!modal) return;
  var lang = currentLang();
  var m = DISCLAIMER_MODAL[lang] || DISCLAIMER_MODAL.en;
  var titleEl = modal.querySelector('.disclaimerModalTitle');
  if(titleEl) titleEl.textContent = m.title;
  var textEl = modal.querySelector('.disclaimerModalText');
  if(textEl) textEl.textContent = m.text;
  var linkEl = document.getElementById('disclaimerModalLink');
  if(linkEl) linkEl.textContent = m.btn;
  modal.classList.remove('hidden');
  try{ localStorage.setItem('galaxia_disclaimer_seen', '1'); }catch(e){}
  var closeEl = document.getElementById('disclaimerModalClose');
  function close(){ modal.classList.add('hidden'); }
  if(closeEl) closeEl.onclick = close;
  if(linkEl) linkEl.onclick = function(){
    close();
    var docsBtn = document.getElementById('docsBtn');
    if(docsBtn) docsBtn.click();
  };
}

// replaced by galaxialunarium-visitors.js (v219); kept unused
function initVisitorCounter(){
  var el = document.getElementById('visitorCountValue');
  if(!el) return;
  function show(count){ el.textContent = count.toLocaleString('en-US'); }
  var already = false;
  try{ already = localStorage.getItem('galaxia_visitor_counted') === '1'; }catch(e){}
  var url = PROXY_BASE + (already ? '/api/visitors' : '/api/visitors/increment');
  fetch(url).then(function(r){ return r.json(); }).then(function(data){
    if(!data || !data.ok) return;
    show(data.count);
    if(!already){ try{ localStorage.setItem('galaxia_visitor_counted', '1'); }catch(e){} }
  }).catch(function(){});
}

// ---- Coins approved through listing requests (/api/listed-coins): each gets a standard page built
// from its verified markets, and a row in the Moedas or Tokens table. Their text comes from the
// customer, so it is escaped here as well as sanitized by the server.
var LISTED_COLORS = ['#2ecfe6', '#8a5cf6', '#20df84', '#f4b72f', '#3f83ff', '#ff5b5b'];
var LISTED_EX_LOGOS = {
  MEXC:'mexc-logo.png', WEEX:'weex-logo.svg', CoinEx:'coinex-logo.jpg', NonKYC:'nonkyc-logo.png', Gatevia:'gatevia-logo.png',
  Qutrade:'qutrade-favicon.png', LunariumTrade:'lunariumtrade-logo.png', Cexius:'cexius-logo.png',
  Binance:'binance-logo.ico', PancakeSwap:'pancakeswap-logo.png', 'Bitget Onchain':'bitget-logo.png'
};
// an exchange missing above falls back to its entry in EXCHANGES, so no market shows a bare letter
function listedExLogo(name){
  if(LISTED_EX_LOGOS[name]) return LISTED_EX_LOGOS[name];
  for(var k in EXCHANGES) if(EXCHANGES[k].name === name) return EXCHANGES[k].logo;
  return '';
}
function buildListedCoin(c){
  var markets = (c.markets || []).filter(function(m){ return m && m.ticker && /^\/api\/ticker\/[a-z]+$/.test(m.ticker); });
  var sym = escHtml(c.symbol);
  var name = escHtml(c.name);
  var isToken = c.category === 'token';
  var network = c.contract ? 'BEP20 (BNB Chain)' : escHtml(c.network || '—');
  var links = c.links || {};
  var officialLinks = [];
  if(links.website) officialLinks.push({label:I18N.officialWebsiteLabel, url:escHtml(links.website), text:I18N.visitWebsite});
  if(links.explorer) officialLinks.push({label:'Explorer', url:escHtml(links.explorer), text:I18N.viewOnExplorer});
  if(c.contract) officialLinks.push({label:I18N.s11ContractBscScanLabel, url:'https://bscscan.com/token/' + escHtml(c.contract), text:I18N.viewOnExplorer});
  if(links.source_code) officialLinks.push({label:'GitHub', url:escHtml(links.source_code), text:I18N.viewSourceCode});
  var bottomStats = [
    {label:I18N.kpiTotalSupply, value:c.supply != null ? Number(c.supply).toLocaleString('en-US') + ' ' + sym : '—'},
    {label:I18N.kpiNetwork, value:network}
  ];
  if(c.contract) bottomStats.push({label:I18N.s11ContractLabel, linkUrl:'https://bscscan.com/address/' + escHtml(c.contract) + '#code', linkText:I18N.viewSourceCode});
  return {
    ticker: sym,
    name: name + ' (' + sym + ')',
    icon: c.logo ? escHtml(c.logo) : 'galaxialunarium-logo.png',
    isOfficial: false,
    listedCoin: true,
    price: '—',
    change: '—',
    changeColor: 'inherit',
    subsExchanges: markets.map(function(m){ return {name:escHtml(m.exchange), url:escHtml(m.url || '')}; }),
    chartLines: markets.map(function(m, i){
      return {name:escHtml(m.exchange), color:LISTED_COLORS[i % LISTED_COLORS.length], points:[], live:true, proxyPath:m.ticker.replace('/ticker/', '/klines/'), proxyParams:escHtml(m.params || ''), candlePrimary:i === 0};
    }),
    kpis: [
      {label:I18N.kpi24hVolume, value:'—', delta:{sourceName:'GaláxiaLunarium'}},
      {label:I18N.kpiMarketCap, value:'—', delta:{sourceName:'GaláxiaLunarium'}},
      {label:I18N.kpiTotalSupply, value:c.supply != null ? Number(c.supply).toLocaleString('en-US') + ' ' + sym : '—', delta:c.contract ? {sourceName:'BNB Chain'} : '—'},
      {label:I18N.kpiNetwork, value:network, delta:I18N.kpiNetwork}
    ],
    donutGradient: 'conic-gradient(var(--line) 0 100%)',
    donutText: '—',
    legend: markets.map(function(m, i){ return {name:escHtml(m.exchange), value:'—', pct:'—', color:LISTED_COLORS[i % LISTED_COLORS.length]}; }),
    alerts: c.description ? [{dot:'var(--cyan)', b:name, span:escHtml(c.description)}] : [],
    exchanges: markets.map(function(m){
      return {name:escHtml(m.exchange), logo:listedExLogo(m.exchange), url:escHtml(m.url || ''), type:m.type === 'DEX' ? 'DEX' : 'CEX', pair:escHtml(m.pair || sym), price:'—', change:'—', changeColor:'inherit', volume:'—'};
    }),
    bottomStats: bottomStats,
    officialLinks: officialLinks,
    tableView: isToken ? 'tokensView' : 'moedasView'
  };
}
// Volume / market cap for a listed coin's page, from the public API snapshot.
// Live figures for token pages (coins with no network endpoint of their own): volume, market cap and
// supply come from the public API snapshot, whose supply is read from the token contract -- so no
// page keeps a hand-typed number that goes stale.
var liveKpiCache = {};
function applyLiveKpis(id, d){
  var coin = COINS[id];
  if(!coin || !d) return;
  // a market that was waiting for its exchange has opened: the page is drawn again with it
  if(openPendingMarkets(id, d.markets) && window.GalaxiaCurrentCoin === id){ renderCoin(id); return; }
  var supplyText = d.supply != null ? Number(d.supply).toLocaleString('en-US', { maximumFractionDigits: 2 }) + ' ' + coin.ticker : null;
  // coins with their own network endpoint keep its supply figures; volume and market cap still come from here
  var fromChain = d.supply_source === 'contract' && !coin.networkApi;
  // a native coin whose supply the server reads from its chain's explorer or node (Bitcoin, Solana, Vivo)
  if(d.supply_source === 'explorer' && supplyText && !coin.networkApi){
    var origin = String(d.supply_origin || '').replace(/[^a-zA-Z0-9.:\/ -]/g, '');
    coin.kpis.forEach(function(k){ if(k.label === I18N.kpiCirculatingSupply){ k.value = supplyText; if(origin) k.delta = {sourceName: origin}; } });
  }
  coin.kpis.forEach(function(k){
    if(k.label === I18N.kpi24hVolume && d.volume_24h_usd != null){ k.value = fmtUsdt(d.volume_24h_usd); k.delta = {sourceName:'GaláxiaLunarium'}; }
    else if(k.label === I18N.kpiMarketCap && d.market_cap_usd != null){ k.value = fmtUsdt(d.market_cap_usd); k.delta = {sourceName:'GaláxiaLunarium'}; }
    // no verifiable circulating supply (locked/vesting allocations): no market cap rather than a stale one
    else if(k.label === I18N.kpiMarketCap && d.price_usd != null && d.supply_source === 'contract'){ k.value = '—'; }
    else if(k.label === I18N.kpiTotalSupply && supplyText && fromChain){ k.value = supplyText; k.delta = {sourceName:'BNB Chain'}; }
    else if(k.label === I18N.kpiCirculatingSupply && supplyText && fromChain && d.market_cap_usd != null){ k.value = supplyText; k.delta = {sourceName:'BNB Chain'}; }
  });
  (coin.bottomStats || []).forEach(function(b){
    if(b.label === I18N.kpiTotalSupply && supplyText && fromChain) b.value = supplyText;
  });
  // volume share per exchange (live markets with volume; reference-only prices left out)
  var vm = (d.markets || []).filter(function(m){ return m.status === 'live' && !m.reference_only && m.volume_24h_usd > 0; })
    .sort(function(x, y){ return y.volume_24h_usd - x.volume_24h_usd; });
  var vt = vm.reduce(function(t, m){ return t + m.volume_24h_usd; }, 0);
  if(vt > 0){
    var palette = ['var(--cyan)', 'var(--violet)', 'var(--green)', 'var(--amber)', 'var(--blue)', 'var(--red)'];
    var acc = 0, stops = [];
    coin.legend = vm.map(function(m, i){
      var pct = m.volume_24h_usd / vt * 100, color = palette[i % palette.length];
      stops.push(color + ' ' + acc.toFixed(2) + '% ' + (acc + pct).toFixed(2) + '%');
      acc += pct;
      return {name:escHtml(m.exchange + (m.cross_pair ? ' ' + m.pair : '')), value:fmtUsdt(m.volume_24h_usd), pct:pct.toFixed(2) + '%', color:color};
    });
    coin.donutGradient = 'conic-gradient(' + stops.join(',') + ')';
    coin.donutText = 'USDT<br>' + Number(vt).toLocaleString('en-US', { maximumFractionDigits: vt >= 1000 ? 0 : 2 });
  }
  if(d.markets) coin.liveSnap = d;
  if(window.GalaxiaCurrentCoin !== id) return;
  refreshExplorerStatus(id);
  var lang = currentLang();
  if(d.markets && !coin.exchangeCoin) renderAlerts(coin, lang);
  if(vt > 0){
    var donut = document.querySelector('.donut');
    if(donut){ donut.style.background = coin.donutGradient; var dspan = donut.querySelector('span'); if(dspan) dspan.innerHTML = coin.donutText; }
    setHTML('#dashboardView .legend', coin.legend.map(function(l){
      return '<div><i class=dot style=background:' + l.color + '></i><span>' + l.name + '<br><b>' + l.value + '</b></span><span>' + l.pct + '</span></div>';
    }).join(''));
  }
  var kp = document.querySelectorAll('#dashboardView .kpi');
  coin.kpis.forEach(function(k, i){
    if(!kp[i]) return;
    var strong = kp[i].querySelector('strong'), delta = kp[i].querySelector('.delta');
    if(strong) strong.textContent = k.value;
    if(delta) delta.textContent = (k.delta && k.delta.sourceName) ? (pick(I18N.sourcePrefix, lang) + ' ' + k.delta.sourceName) : pick(k.delta, lang);
  });
  var bottoms = document.querySelectorAll('.bottom');
  if(bottoms[0]) Array.prototype.forEach.call(bottoms[0].children, function(div, i){
    var b = coin.bottomStats[i];
    if(b && !b.linkUrl){ var st = div.querySelector('strong'); if(st) st.textContent = b.value; }
  });
}
function fillLiveKpis(id){
  var coin = COINS[id];
  if(!coin) return;
  if(coin.exchangeCoin){ exchangeCoinKpis(id); return; } // not in the public API: exchange snapshot
  var hit = liveKpiCache[id];
  if(hit && Date.now() - hit.at < 60000) return applyLiveKpis(id, hit.data);
  fetch(PROXY_BASE + '/api/v1/coins/' + encodeURIComponent(id)).then(function(r){ return r.json(); }).then(function(res){
    var d = res && res.ok && res.data;
    if(!d) return;
    liveKpiCache[id] = { at: Date.now(), data: d };
    applyLiveKpis(id, d);
  }).catch(function(){});
}
// Every row of the Moedas / Tokens / Mineração / Stake tables, refreshed from one API call.
function refreshCoinTables(){
  fetch(PROXY_BASE + '/api/v1/coins').then(function(r){ return r.json(); }).then(function(list){
    var rows = list && list.ok && Array.isArray(list.data) ? list.data : [];
    rows.forEach(function(s){
      coinSummaries[s.id] = s;
      Array.prototype.forEach.call(document.querySelectorAll('.moedasView tr.coinRow[data-coin="' + s.id + '"]'), function(tr){
        var td = tr.children;
        if(td.length < 6) return;
        if(s.price_usd == null && td[2].classList.contains('soonText')) return;
        var ch = s.change_24h_pct;
        // a cell still marked "coming soon" would be rewritten by the language script: the price is here now
        if(s.price_usd != null) td[2].classList.remove('soonText');
        td[2].textContent = s.price_usd != null ? 'USDT ' + fmtPrice(s.price_usd) : '—';
        td[3].textContent = ch == null ? '—' : (ch >= 0 ? '+' : '') + ch.toFixed(2) + '%';
        td[3].style.color = ch == null ? 'inherit' : ch >= 0 ? 'var(--green)' : 'var(--red)';
        td[4].textContent = s.market_cap_usd != null ? fmtUsdt(s.market_cap_usd) : '—';
        td[5].textContent = s.volume_24h_usd != null ? fmtUsdt(s.volume_24h_usd) : '—';
      });
    });
  }).catch(function(){});
}
function listedRowCells(coin, s){
  s = s || {};
  var ch = s.change_24h_pct;
  var newBadge = s.is_new ? ' <span class="pill newBadge">' + escHtml((NEWL_I18N[currentLang()] || NEWL_I18N.en)[2]) + '</span>' : '';
  return '<td><span class=platform><img class=coinIcon src="' + coin.icon + '" alt="' + coin.ticker + '">' + coin.name + newBadge + '</span></td>' +
    '<td>' + (s.price_usd != null ? 'USDT ' + fmtPrice(s.price_usd) : '—') + '</td>' +
    '<td style="color:' + (ch == null ? 'inherit' : ch >= 0 ? 'var(--green)' : 'var(--red)') + '">' + (ch == null ? '—' : (ch >= 0 ? '+' : '') + ch.toFixed(2) + '%') + '</td>' +
    '<td>' + (s.market_cap_usd != null ? fmtUsdt(s.market_cap_usd) : '—') + '</td>' +
    '<td>' + (s.volume_24h_usd != null ? fmtUsdt(s.volume_24h_usd) : '—') + '</td>';
}
// a coin can belong to several tabs (e.g. stake and masternode): one row in each
function addListedRow(id, coin, summary){
  (coin.tableViews || [coin.tableView]).forEach(function(viewId){
    var view = document.getElementById(viewId);
    var tbody = view && view.querySelector('tbody');
    if(!tbody) return;
    var tr = tbody.querySelector('tr[data-coin="' + id + '"]');
    if(tr){ tr.innerHTML = tr.firstElementChild.outerHTML + listedRowCells(coin, summary); return; }
    tr = document.createElement('tr');
    tr.className = 'coinRow';
    tr.setAttribute('data-coin', id);
    tr.innerHTML = '<td>' + (tbody.querySelectorAll('tr').length + 1) + '</td>' + listedRowCells(coin, summary);
    tr.onclick = function(){ if(typeof window.showView === 'function') window.showView('dashboard'); renderCoin(id); };
    tbody.appendChild(tr);
  });
  addCoinRowStars();
}
function loadListedCoins(requested){
  fetch(PROXY_BASE + '/api/listed-coins').then(function(r){ return r.json(); }).then(function(res){
    if(!res || !res.ok || !Array.isArray(res.data) || !res.data.length) return;
    var fresh = [];
    res.data.forEach(function(c){
      if(!c || !/^[a-z0-9-]{1,40}$/.test(c.id) || COINS[c.id]) return;
      COINS[c.id] = buildListedCoin(c);
      if(COINS[c.id].ticker) coinByTicker[COINS[c.id].ticker.toUpperCase()] = c.id;
      fresh.push(c.id);
    });
    if(!fresh.length) return;
    fresh.forEach(function(id){ addListedRow(id, COINS[id]); });
    if(typeof window.runLang === 'function') window.runLang(currentLang());
    if(requested && fresh.indexOf(requested) >= 0) renderCoin(requested);
    refreshCoinTables();
    refreshSynOptions();
  }).catch(function(){});
}

// ---- Coins traded on the partner exchanges (Qutrade, Gatevia): /api/exchange-coins places each one
// in its tab by consensus (masternode, stake, mining, token) with live price, change and volume.
var EXC_TAB = { masternode: 'moedasView', stake: 'stakeView', mining: 'mineracaoView', token: 'tokensView' };
var exchangeCoinData = {};
function buildExchangeCoin(c){
  var usdt = (c.markets || []).filter(function(m){ return m.ticker; });
  var coin = buildListedCoin({ id: c.id, symbol: c.symbol, name: c.name, category: c.category, network: null, contract: null, logo: c.logo, links: c.links,
    markets: usdt.map(function(m){ return { exchange: m.exchange, type: 'CEX', pair: m.pair, url: m.url, ticker: m.ticker, params: m.params }; }) });
  coin.exchangeCoin = true;
  coin.tableView = EXC_TAB[c.category] || 'tokensView';
  coin.tableViews = (c.categories && c.categories.length ? c.categories : [c.category]).map(function(k){ return EXC_TAB[k]; }).filter(Boolean);
  coin.kpis[3].value = '—';
  coin.bottomStats = coin.bottomStats.filter(function(b){ return b.label !== I18N.kpiNetwork; });
  // every market, USDT or not, in the exchanges table of the coin page
  coin.exchanges = (c.markets || []).map(function(m){
    return { name: escHtml(m.exchange), logo: listedExLogo(m.exchange), url: escHtml(m.url), type: 'CEX', pair: escHtml(m.pair),
      price: m.price != null ? fmtPrice(m.price) : '—', change: m.change_24h_pct != null ? (m.change_24h_pct >= 0 ? '+' : '') + m.change_24h_pct.toFixed(2) + '%' : '—',
      changeColor: m.change_24h_pct == null ? 'inherit' : m.change_24h_pct >= 0 ? 'var(--green)' : 'var(--red)', volume: m.volume_24h_usd != null ? fmtUsdt(m.volume_24h_usd) : '—' };
  });
  setExchangeCoinHeadline(coin, c);
  return coin;
}
function setExchangeCoinHeadline(coin, c){
  coin.price = c.price_usd != null ? 'USDT ' + fmtPrice(c.price_usd) : '—';
  var ch = c.change_24h_pct;
  coin.change = ch != null ? (ch >= 0 ? '+' : '') + ch.toFixed(2) + '%' : '—';
  coin.changeColor = ch == null ? 'inherit' : ch >= 0 ? 'var(--green)' : 'var(--red)';
}
// volume and markets for the KPIs / donut of an exchange coin's page
function exchangeCoinKpis(id){
  var c = exchangeCoinData[id];
  if(!c) return;
  // supply read from the coin's own chain by the server (the explorer is named as the source);
  // set before applyLiveKpis, which writes the KPIs to the page
  var coin = COINS[id];
  if(coin && c.supply != null){
    var supplyText = Number(c.supply).toLocaleString('en-US', { maximumFractionDigits: 2 }) + ' ' + coin.ticker;
    var supplySource = String(c.supply_source || '').replace(/[^a-zA-Z0-9.:/ -]/g, '');
    coin.kpis.forEach(function(k){ if(k.label === I18N.kpiTotalSupply){ k.value = supplyText; k.delta = {sourceName: supplySource}; } });
    (coin.bottomStats || []).forEach(function(b){ if(b.label === I18N.kpiTotalSupply) b.value = supplyText; });
  }
  applyLiveKpis(id, { volume_24h_usd: c.volume_24h_usd, market_cap_usd: c.market_cap_usd != null ? c.market_cap_usd : null, price_usd: c.price_usd,
    markets: (c.markets || []).map(function(m){ return { status: m.price != null ? 'live' : '', reference_only: false, exchange: m.exchange + ' ' + m.pair, volume_24h_usd: m.volume_24h_usd }; }) });
}
// coins with their own page that belong to more than one tab (from their official source code)
var SITE_COIN_TABS = { xln: ['moedasView', 'stakeView'], pivx: ['moedasView', 'stakeView'], mon: ['moedasView', 'stakeView'], ns: ['moedasView', 'stakeView'], vivo: ['moedasView', 'mineracaoView'], dash: ['moedasView', 'mineracaoView'], 'eth-coin': ['stakeView'], bnb: ['stakeView'] };
function ensureSiteCoinTabs(){
  Object.keys(SITE_COIN_TABS).forEach(function(id){
    var src = document.querySelector('.moedasView tr.coinRow[data-coin="' + id + '"]');
    if(!src) return;
    SITE_COIN_TABS[id].forEach(function(viewId){
      var tbody = document.querySelector('#' + viewId + ' tbody');
      if(!tbody || tbody.querySelector('tr[data-coin="' + id + '"]')) return;
      var tr = src.cloneNode(true);
      var mnCell = tr.querySelector('.mnCollTd');
      if(mnCell) mnCell.parentNode.removeChild(mnCell);
      tr.children[0].textContent = tbody.querySelectorAll('tr').length + 1;
      tr.onclick = function(){ if(typeof window.showView === 'function') window.showView('dashboard'); renderCoin(id); };
      tbody.appendChild(tr);
    });
  });
  if(typeof window.runLang === 'function') window.runLang(currentLang());
}
// ---- Top search box: coins and tokens (name, ticker, contract address), partner exchanges and
// pairs (BTC/USDT, btcusdt, xln_usdt ...). Everything searched is what the page already has loaded:
// the site's own coins, the coins of the partner exchanges and their markets. Enter opens the first
// result; arrows move through the list; Esc closes it.
function globalSearchResults(q){
  var norm = function(v){ return String(v || '').toLowerCase(); };
  var flat = function(v){ return norm(v).replace(/[^a-z0-9]/g, ''); };
  var text = function(v){ var d = document.createElement('span'); d.innerHTML = String(v || ''); return d.textContent; };
  var query = norm(q).trim(), fq = flat(q);
  var out = { coins: [], exchanges: [], pairs: [] };
  if(!query) return out;
  var isAddress = /^0x[0-9a-f]{6,}$/.test(query) || fq.length >= 20;
  var pairSeen = {};
  Object.keys(COINS).forEach(function(id){
    var c = COINS[id], ex = exchangeCoinData[id], sum = coinSummaries[id] || {};
    var ticker = norm(c.ticker), name = norm(text(c.name));
    var contract = norm(sum.contract) + ' ' + norm(ex && ex.links && ex.links.explorer);
    (c.bottomStats || []).concat(c.officialLinks || []).forEach(function(l){ contract += ' ' + norm(l.linkUrl || l.url); });
    var score = ticker === query ? 0 : ticker.indexOf(query) === 0 ? 1 : name.indexOf(query) === 0 ? 2
      : (name.indexOf(query) >= 0 || id.indexOf(query) >= 0 || ticker.indexOf(query) >= 0) ? 3
      : (isAddress && contract.indexOf(query) >= 0) ? 4 : -1;
    if(score >= 0) out.coins.push({ id: id, score: score, name: text(c.name), ticker: c.ticker, icon: c.icon });
    // pairs: looked for once the text is specific enough to be one ("btc/", "btcusdt", "xln_usdt")
    if(/[\/_-]/.test(query) || fq.length >= 5){
      var markets = ex ? (ex.markets || []).map(function(m){ return { pair: m.pair, exchange: m.exchange }; })
        : (c.exchanges || []).map(function(m){ return { pair: text(m.pair), exchange: text(m.name) }; });
      markets.forEach(function(m){
        var fp = flat(m.pair);
        if(!fp || fp.indexOf(fq) < 0) return;
        var key = id + '|' + m.pair + '|' + m.exchange;
        if(pairSeen[key]) return;
        pairSeen[key] = true;
        out.pairs.push({ id: id, pair: m.pair, exchange: m.exchange, ticker: c.ticker, icon: c.icon, exact: fp === fq ? 0 : fp.indexOf(fq) === 0 ? 1 : 2 });
      });
    }
  });
  EXCHANGE_ORDER.forEach(function(id){
    var e = EXCHANGES[id];
    if(e && (norm(e.name).indexOf(query) >= 0 || id.indexOf(query) >= 0)) out.exchanges.push({ id: id, name: e.name, logo: e.logo });
  });
  out.coins.sort(function(a, b){ return a.score - b.score || a.name.localeCompare(b.name); });
  out.pairs.sort(function(a, b){ return a.exact - b.exact || a.pair.localeCompare(b.pair); });
  out.coins = out.coins.slice(0, 8);
  out.exchanges = out.exchanges.slice(0, 4);
  out.pairs = out.pairs.slice(0, 8);
  return out;
}
function initGlobalSearch(){
  var label = document.querySelector('.top .search');
  var input = label && label.querySelector('input');
  if(!input || label.querySelector('.searchResults')) return;
  input.type = 'search';
  input.autocomplete = 'off';
  input.setAttribute('aria-autocomplete', 'list');
  var box = document.createElement('div');
  box.className = 'searchResults';
  box.hidden = true;
  label.appendChild(box);
  var active = -1;
  var items = function(){ return box.querySelectorAll('.searchItem'); };
  var mark = function(){
    Array.prototype.forEach.call(items(), function(b, i){ b.classList.toggle('on', i === active); });
    var on = items()[active];
    if(on && on.scrollIntoView) on.scrollIntoView({ block: 'nearest' });
  };
  var close = function(){ box.hidden = true; active = -1; };
  var go = function(el){
    if(!el) return;
    var coin = el.getAttribute('data-coin'), ex = el.getAttribute('data-ex');
    close();
    input.value = '';
    input.blur();
    if(coin && COINS[coin]){
      if(window.GalaxiaShowView) window.GalaxiaShowView('dashboard');
      renderCoin(coin);
      window.scrollTo(0, 0);
    }else if(ex && EXCHANGES[ex]){
      var b = document.getElementById('exchangesBtn');
      if(b) b.click();
      openExchange(ex);
      window.scrollTo(0, 0);
    }
  };
  var draw = function(){
    var q = input.value, lang = currentLang();
    if(!q.trim()){ close(); return; }
    var r = globalSearchResults(q);
    var navEx = document.querySelector('#exchangesBtn span');
    var section = function(title, html){ return html ? '<div class=searchGroup>' + escHtml(title) + '</div>' + html : ''; };
    var img = function(src){ return src ? '<img class=coinIcon src="' + escHtml(src) + '" alt="" onerror="this.style.visibility=\'hidden\'">' : '<span class=coinIcon></span>'; };
    var coinsHtml =
      section(pick(I18N.exColCoin, lang), r.coins.map(function(c){
        return '<button type=button class=searchItem data-coin="' + escHtml(c.id) + '">' + img(c.icon) + '<span class=searchMain>' + escHtml(c.name) + '</span><span class=searchSub>' + escHtml(c.ticker || '') + '</span></button>';
      }).join(''));
    var exHtml =
      section(navEx ? navEx.textContent : 'Exchanges', r.exchanges.map(function(e){
        return '<button type=button class=searchItem data-ex="' + escHtml(e.id) + '">' + img(e.logo) + '<span class=searchMain>' + escHtml(e.name) + '</span></button>';
      }).join(''));
    var pairsHtml =
      section(pick(I18N.exColPair, lang), r.pairs.map(function(m){
        return '<button type=button class=searchItem data-coin="' + escHtml(m.id) + '">' + img(m.icon) + '<span class=searchMain>' + escHtml(m.pair) + '</span><span class=searchSub>' + escHtml(m.exchange) + ' · ' + escHtml(m.ticker || '') + '</span></button>';
      }).join(''));
    // the exact name of an exchange brings the exchange first ("gatevia" is also how GateviaCoin starts)
    var typed = q.trim().toLowerCase();
    var exactEx = r.exchanges.some(function(e){ return e.name.toLowerCase() === typed; });
    var html = (exactEx ? exHtml + coinsHtml : coinsHtml + exHtml) + pairsHtml;
    box.innerHTML = html || '<div class=searchEmpty>' + escHtml(favT(lang)[18]) + '</div>';
    box.hidden = false;
    active = items().length ? 0 : -1;
    mark();
    Array.prototype.forEach.call(items(), function(b){
      // mousedown: before the field loses focus and the list closes
      b.addEventListener('mousedown', function(e){ e.preventDefault(); go(b); });
    });
  };
  input.addEventListener('input', draw);
  input.addEventListener('focus', function(){ if(input.value.trim()) draw(); });
  input.addEventListener('blur', function(){ setTimeout(close, 150); });
  input.addEventListener('keydown', function(e){
    var n = items().length;
    if(e.key === 'ArrowDown' && n){ e.preventDefault(); active = (active + 1) % n; mark(); }
    else if(e.key === 'ArrowUp' && n){ e.preventDefault(); active = (active - 1 + n) % n; mark(); }
    else if(e.key === 'Enter'){ e.preventDefault(); if(box.hidden) draw(); go(items()[active >= 0 ? active : 0]); }
    else if(e.key === 'Escape'){ close(); input.blur(); }
  });
}

// ---- Masternode collateral: last column of the "Coins masternode" table (that tab only). The
// figures come from /api/masternode-collateral, which reads them in each coin's official source
// code and follows the block height where the collateral depends on it. The header is the first
// part of the "Masternode collateral: ..." sentence already translated for the coin pages.
var mnCollateral = null;
// shown in red where a coin has no collateral figure (no rule in its code, or no explorer to tell the block height)
var MN_NO_DATA = { en:'No data', ru:'Нет данных', de:'Keine Daten', pl:'Brak danych', es:'Sin datos', vi:'Không có dữ liệu', fr:'Aucune donnée', 'pt-BR':'Sem dados', ar:'لا توجد بيانات', bg:'Няма данни', cs:'Žádná data', da:'Ingen data', el:'Χωρίς δεδομένα', fi:'Ei tietoja', he:'אין נתונים', hi:'कोई डेटा नहीं', hr:'Nema podataka', hu:'Nincs adat', id:'Tidak ada data', it:'Nessun dato', ja:'データなし', ko:'데이터 없음', lt:'Nėra duomenų', nl:'Geen gegevens', no:'Ingen data', ro:'Fără date', sk:'Žiadne údaje', sl:'Ni podatkov', sv:'Inga data', th:'ไม่มีข้อมูล', tr:'Veri yok', uk:'Немає даних', zh:'暂无数据', 'zh-TW':'暫無資料' };
function mnCollateralLabel(lang){
  if(lang === 'pt-BR') return 'Colateral do masternode'; // the word the site's owner and Brazilian users use
  return String(pick(I18N.vivoMnB, lang)).split(/[:：]/)[0].trim();
}
function mnCollateralHtml(ticker){
  if(!mnCollateral) return '—'; // still loading
  var d = mnCollateral[String(ticker || '').toUpperCase()];
  if(!d || d.amount == null) return '<span class=mnNoData>' + escHtml(pick(MN_NO_DATA, currentLang())) + '</span>';
  var n = function(v){ return Number(v).toLocaleString('en-US', { maximumFractionDigits: d.approx ? 0 : 2 }); };
  var main = (d.approx ? '≈ ' : '') + n(d.amount) + ' ' + escHtml(d.symbol);
  var named = (d.tiers || []).filter(function(t){ return t.name; });
  var sub = named.length > 1 ? named.map(function(t){ return escHtml(t.name) + ' ' + n(t.amount); }).join(' · ') : '';
  if(d.next && d.next.height) sub = '→ ' + n(d.next.amount) + ' · #' + Number(d.next.height).toLocaleString('en-US');
  return main + (sub ? '<span class=mnCollSub>' + sub + '</span>' : '');
}
function applyMnCollateral(){
  var view = document.getElementById('moedasView');
  var headRow = view && view.querySelector('thead tr');
  if(!headRow) return;
  var th = headRow.querySelector('.mnCollTh');
  if(!th){ th = document.createElement('th'); th.className = 'mnCollTh'; headRow.appendChild(th); }
  var label = mnCollateralLabel(currentLang());
  if(th.textContent !== label) th.textContent = label;
  Array.prototype.forEach.call(view.querySelectorAll('tbody tr.coinRow[data-coin]'), function(tr){
    var td = tr.querySelector('.mnCollTd');
    if(!td){ td = document.createElement('td'); td.className = 'mnCollTd'; tr.appendChild(td); }
    var coin = COINS[tr.getAttribute('data-coin')];
    var html = mnCollateralHtml(coin && coin.ticker);
    if(td.getAttribute('data-v') !== html){ td.setAttribute('data-v', html); td.innerHTML = html; }
  });
}
function initMnCollateral(){
  var view = document.getElementById('moedasView');
  if(!view) return;
  var load = function(){
    fetch(PROXY_BASE + '/api/masternode-collateral').then(function(r){ return r.json(); }).then(function(res){
      if(res && res.ok && res.data){ mnCollateral = res.data; applyMnCollateral(); }
    }).catch(function(){});
  };
  // rows are added, redrawn and translated by other parts of the page: the column follows them
  if(window.MutationObserver){
    new MutationObserver(function(){ applyMnCollateral(); }).observe(view, { childList: true, subtree: true });
    new MutationObserver(function(){ applyMnCollateral(); }).observe(document.documentElement, { attributes: true, attributeFilter: ['lang'] });
  }
  applyMnCollateral();
  load();
  setInterval(load, 10 * 60 * 1000);
}

