function chartTheme(){
  var cs = getComputedStyle(document.documentElement);
  var v = function(name, fallback){ return (cs.getPropertyValue(name) || '').trim() || fallback; };
  return { text: v('--mut', '#95a8ad'), grid: v('--gridline', 'rgba(255,255,255,.07)'), line: v('--line', '#26383f') };
}
function applyChartTheme(){
  var c = chartTheme();
  var o = { layout: { textColor: c.text }, grid: { vertLines: { color: c.grid }, horzLines: { color: c.grid } }, timeScale: { borderColor: c.line }, rightPriceScale: { borderColor: c.line } };
  [typeof lwChart !== 'undefined' ? lwChart : null, typeof synChart !== 'undefined' ? synChart : null].forEach(function(ch){
    if(ch){ try{ ch.applyOptions(o); }catch(e){} }
  });
}
function setThemeLabel(lang){
  var btn = document.getElementById('themeBtn');
  if(!btn) return;
  var t = pick(THEME_I18N, lang);
  btn.title = t;
  btn.setAttribute('aria-label', t);
}
function initTheme(){
  var btn = document.getElementById('themeBtn');
  if(!btn) return;
  setThemeLabel(currentLang());
  btn.onclick = function(){
    var light = document.documentElement.getAttribute('data-theme') !== 'light';
    if(light) document.documentElement.setAttribute('data-theme', 'light'); else document.documentElement.removeAttribute('data-theme');
    try{ localStorage.setItem('galaxia_theme', light ? 'light' : 'dark'); }catch(e){}
    applyChartTheme();
  };
}

